(() => {
  const DATA = window.JLPT_DATA;
  if (!DATA?.grammar) return;
  const DETAILS = {"g-n5-001":{"overview":"用「は」提出主题，再用名词或形容词对主题作礼貌判断或描写，是最基础的名词谓语句。","category":"基础判断・描写","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"N + は + N/形容词 + です","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["介绍姓名、职业、国籍、性质和身份。","回答“某人／某物是什么、怎么样”。","介绍身份、属性、状态或事物之间的关系。"],"cautions":["「は」标记的是话题，不一定等于动作句中的语法主语。","名词和な形容词可接「です」；い形容词不能先加「だ」再接「です」。"],"specialCases":["普通体多用「AはBだ」；疑问句通常在句末加「か」。"]},"g-n5-002":{"overview":"名词和な形容词谓语的礼貌否定，表示“不是／不……”。","category":"基础判断・描写","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"N/な形 + ではありません","formationNotes":["な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["否定身份、类别和な形容词性质。","介绍身份、属性、状态或事物之间的关系。","把形容词或修饰成分组织成完整句子。"],"cautions":["不能用来否定い形容词；い形容词改为「〜くないです／〜くありません」。","要区分名词／な形容词与い形容词的活用方式。"],"specialCases":["会话中「では」常缩为「じゃ」：じゃありません。"]},"g-n5-003":{"overview":"「～ました／～ませんでした」的核心意义是：动词礼貌体的过去与过去否定。表示动作的时间、进行阶段、完成状态或结果状态。","category":"时态・体","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vます → Vました / Vませんでした","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["叙述已经发生或过去未发生的动作。","说明动作是否发生、是否完成或是否持续。","把两个动作按先后或状态关系连接起来。"],"cautions":["过去否定是「ませんでした」，不是「ましたない」。","日语的过去形也表示完成；「ている」不一定等于中文“正在”。"],"specialCases":["动作是否“完成”由语境判断；持续状态有时需用「ていました」。"]},"g-n5-004":{"overview":"「助词「が」」的核心意义是：标记主语、新信息；也常与好き・分かる等搭配。说明名词与谓语、其他名词之间的语法关系。","category":"助词・格关系","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + が","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["提示新出现的主语，或标记存在、能力、喜好、理解的对象。","标记主题之外的格关系、方向、范围或并列关系。","通过助词选择明确动作参与者与信息焦点。"],"cautions":["与「は」相比，「が」更聚焦主语本身；二者不能仅按“主语助词／主题助词”机械替换。","助词往往不能按中文介词逐字对应，应结合谓语的固定搭配判断。"],"specialCases":["「好きだ・分かる・できる・ある／いる」等常要求相关对象或存在主体用「が」。"]},"g-n5-005":{"overview":"「助词「を」」的核心意义是：标记动作直接作用的对象。说明名词与谓语、其他名词之间的语法关系。","category":"助词・格关系","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + を + V","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["标记他动词直接作用的对象。","与移动动词搭配时也可标记经过或离开的场所。","标记主题之外的格关系、方向、范围或并列关系。"],"cautions":["读作「お」，书写仍为「を」。","助词往往不能按中文介词逐字对应，应结合谓语的固定搭配判断。"],"specialCases":["「公園を歩く」「家を出る」中的「を」不是直接宾语，而是路径或离开点。"]},"g-n5-006":{"overview":"「助词「に」」的核心意义是：表示时间、到达点、存在地点、动作对象等。说明名词与谓语、其他名词之间的语法关系。","category":"助词・格关系","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"时间/地点/对象 + に","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["表示具体时间、到达点、存在地点、对象、目的等。","标记主题之外的格关系、方向、范围或并列关系。","通过助词选择明确动作参与者与信息焦点。"],"cautions":["动作发生地多用「で」，存在地点多用「に」；不要混用。","助词往往不能按中文介词逐字对应，应结合谓语的固定搭配判断。"],"specialCases":["相对时间词「今日、毎日、来年」通常不加表示时点的「に」。"]},"g-n5-007":{"overview":"「助词「で」」的核心意义是：表示动作地点、手段、工具、材料等。说明名词与谓语、其他名词之间的语法关系。","category":"助词・格关系","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"地点/手段 + で","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["标记动作场所、手段、工具、材料或原因。","标记主题之外的格关系、方向、范围或并列关系。","通过助词选择明确动作参与者与信息焦点。"],"cautions":["「学校で勉強する」是动作地点；「学校にいる」是存在地点。","助词往往不能按中文介词逐字对应，应结合谓语的固定搭配判断。"],"specialCases":["人数或数量后的「で」可表示合计范围，如「三人で」。"]},"g-n5-008":{"overview":"「助词「と」」的核心意义是：表示“和”、完整列举或引用。说明名词与谓语、其他名词之间的语法关系。","category":"助词・格关系","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + と / 「文」と言う","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["完整列举共同对象，或标记引用内容和共同动作对象。","标记主题之外的格关系、方向、范围或并列关系。","通过助词选择明确动作参与者与信息焦点。"],"cautions":["列举时「と」通常表示所列项目完整；不完全列举用「や／など」。","助词往往不能按中文介词逐字对应，应结合谓语的固定搭配判断。"],"specialCases":["引用内容后接「と言う／と思う」；引用部分通常保持普通形。"]},"g-n5-009":{"overview":"「助词「の」」的核心意义是：表示所属、属性或用名词修饰名词。说明名词与谓语、其他名词之间的语法关系。","category":"助词・格关系","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + の + N","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["连接两个名词，表示所属、属性、种类、材料等。","标记主题之外的格关系、方向、范围或并列关系。","通过助词选择明确动作参与者与信息焦点。"],"cautions":["不能把所有中文“的”都直接译为「の」；动词和形容词可直接修饰名词。","助词往往不能按中文介词逐字对应，应结合谓语的固定搭配判断。"],"specialCases":["上下文明确时，后面的名词可省略，如「私のです」。"]},"g-n5-010":{"overview":"「～から／～まで」的核心意义是：表示起点与终点：“从……到……”。说明名词与谓语、其他名词之间的语法关系。","category":"助词・格关系","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + から / N + まで","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["表示时间、地点或范围的起点与终点。","标记主题之外的格关系、方向、范围或并列关系。","通过助词选择明确动作参与者与信息焦点。"],"cautions":["「から」和「まで」可单独使用，不必总成对出现。","助词往往不能按中文介词逐字对应，应结合谓语的固定搭配判断。"],"specialCases":["「まで」表示界限；“在期限前完成”通常用「までに」。"]},"g-n5-011":{"overview":"「～があります／います」的核心意义是：表示存在；あります用于无生命物，います用于人和动物。用于指出人、事物、地点以及它们的存在位置。","category":"存在・指示","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"場所に + Nが + ある/いる","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用「ある」说明无生命物存在，用「いる」说明人和动物存在。","说明某处有什么／有谁。","根据说话人与听话人的距离选择指示词。"],"cautions":["基本语序是「場所に Nが ある／いる」；地点不用「で」。","存在句的地点通常用「に」，动作发生地则多用「で」。"],"specialCases":["「ある」还可表示拥有或活动举行；选择仍取决于主语性质。"]},"g-n5-012":{"overview":"「い形容词变化」的核心意义是：い形容词可变为否定、过去、过去否定。构成最基础的判断、性质描写和名词修饰。","category":"基础判断・描写","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"高い→高くない→高かった→高くなかった","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["把い形容词变为否定、过去、过去否定及连接形式。","介绍身份、属性、状态或事物之间的关系。","把形容词或修饰成分组织成完整句子。"],"cautions":["活用时去掉最后的「い」再接「くない／かった」；「いい」例外使用词干「よ」。","要区分名词／な形容词与い形容词的活用方式。"],"specialCases":["礼貌否定可说「高くないです」或较正式的「高くありません」。"]},"g-n5-013":{"overview":"「な形容词变化」的核心意义是：な形容词作谓语时类似名词变化；修饰名词时加「な」。构成最基础的判断、性质描写和名词修饰。","category":"基础判断・描写","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"静かだ / 静かな町","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["な形容词修饰名词时加「な」，作谓语时按名词谓语变化。","介绍身份、属性、状态或事物之间的关系。","把形容词或修饰成分组织成完整句子。"],"cautions":["句末现在肯定不是「静かなです」，而是「静かです」。","要区分名词／な形容词与い形容词的活用方式。"],"specialCases":["连接句子常用「で」，副词用法常用「に」。"]},"g-n5-014":{"overview":"「～てください」的核心意义是：礼貌地请求对方做某事。用于请求、邀请、提议或向对方征求行动意见。","category":"请求・邀请","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vて + ください","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["礼貌请求对方实施某动作。","礼貌地请对方做或不做某事。","邀请共同参与，或主动提出帮助。"],"cautions":["虽有「ください」，对上级仍可能显得直接，可用「〜ていただけますか」更委婉。","礼貌程度取决于句型、句尾和人际关系；对上级需避免命令感。"],"specialCases":["否定请求使用「ないでください」，不是「てください」的简单否定。"]},"g-n5-015":{"overview":"「～ないでください」的核心意义是：礼貌地请求对方不要做某事。用于请求、邀请、提议或向对方征求行动意见。","category":"请求・邀请","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vない + でください","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["礼貌请求对方不要实施某动作。","礼貌地请对方做或不做某事。","邀请共同参与，或主动提出帮助。"],"cautions":["先变成ない形，再接「でください」；不能使用「なくてください」。","先正确变出ない形，不能从辞书形机械删除词尾。"],"specialCases":["正式禁止告示常用「〜ないでください」或更强的「〜てはいけません」。"]},"g-n5-016":{"overview":"「～てもいいです」的核心意义是：表示许可：“可以……”。表达可以做、不可以做、必须做或不必做。","category":"许可・禁止・义务","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vて + もいい","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["询问或给予做某事的许可。","说明规则、许可、禁止和必要性。","在日常交流中询问或给予行动许可。"],"cautions":["表示许可，不表示能力；“能做”应根据语境用可能形。","义务强度与礼貌度不同，对特定听话人直接使用强制表达可能显得生硬。"],"specialCases":["询问时常说「〜てもいいですか」；否定许可可用「〜てはいけません」。"]},"g-n5-017":{"overview":"「～てはいけません」的核心意义是：表示禁止：“不可以……”。表达可以做、不可以做、必须做或不必做。","category":"许可・禁止・义务","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vて + はいけない","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["说明规则上不允许做某事。","说明规则、许可、禁止和必要性。","在日常交流中询问或给予行动许可。"],"cautions":["语气较强，对具体听话人直接使用可能像训斥。","义务强度与礼貌度不同，对特定听话人直接使用强制表达可能显得生硬。"],"specialCases":["口语常缩为「ちゃいけない／じゃいけない」。"]},"g-n5-018":{"overview":"「～ています」的核心意义是：表示正在进行、持续状态或结果状态。表示动作的时间、进行阶段、完成状态或结果状态。","category":"时态・体","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vて + いる","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["表示正在进行、反复习惯、职业身份或动作结果持续。","说明动作是否发生、是否完成或是否持续。","把两个动作按先后或状态关系连接起来。"],"cautions":["瞬间动词如「結婚する・知る」的「ている」常表示结果状态，而非正在发生。","日语的过去形也表示完成；「ている」不一定等于中文“正在”。"],"specialCases":["「行っています」可根据语境表示“正在去”或“去了并在那里”，需结合地点和上下文。"]},"g-n5-019":{"overview":"「～ませんか」的核心意义是：委婉邀请：“要不要一起……？”。用于请求、邀请、提议或向对方征求行动意见。","category":"请求・邀请","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vます去ます + ませんか","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。"],"usages":["用否定疑问形式委婉邀请对方共同做某事。","礼貌地请对方做或不做某事。","邀请共同参与，或主动提出帮助。"],"cautions":["形式是否定，但功能通常是邀请，不是询问对方是否不做。","不要保留「ます」再接句型。"],"specialCases":["比「ましょう」更把决定权留给对方。"]},"g-n5-020":{"overview":"「～ましょう」的核心意义是：表示提议：“一起……吧”。用于请求、邀请、提议或向对方征求行动意见。","category":"请求・邀请","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vます去ます + ましょう","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。"],"usages":["提出共同做某事，或表示说话人的积极意志。","礼貌地请对方做或不做某事。","邀请共同参与，或主动提出帮助。"],"cautions":["直接对上级使用可能显得替对方作决定。","不要保留「ます」再接句型。"],"specialCases":["征求意见或主动帮忙时常用「ましょうか」。"]},"g-n5-021":{"overview":"「～たいです」的核心意义是：表示说话人的愿望：“想做……”。表达说话人的愿望、意志、打算或既定计划。","category":"愿望・意志・计划","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vます去ます + たい","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。"],"usages":["表达说话人想做某事的愿望。","说明自己想做什么、想要什么。","区分临时意向、个人打算与已经安排的日程。"],"cautions":["直接陈述第三者愿望通常用「〜たがっている」或引用「〜たいと言っている」。","不要保留「ます」再接句型。"],"specialCases":["对象助词有时由「を」变为「が」，如「水が飲みたい」。"]},"g-n5-022":{"overview":"「～が欲しいです」的核心意义是：表示想要某个东西。表达说话人的愿望、意志、打算或既定计划。","category":"愿望・意志・计划","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"N + が欲しい","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["表达说话人想得到某个事物。","说明自己想做什么、想要什么。","区分临时意向、个人打算与已经安排的日程。"],"cautions":["想要做某动作不用「欲しい」单独表达，而用「Vたい」；希望别人做用「Vてほしい」。","直接愿望通常以说话人自己为主；第三者愿望需使用观察或引用表达。"],"specialCases":["第三者愿望常用「欲しがっている」。"]},"g-n5-023":{"overview":"「～に行く／来る」的核心意义是：表示移动的目的：“去/来做……”。说明行动的目的、目标或为了达到某状态而采取的措施。","category":"目的","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vます去ます + に行く/来る","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["说明移动行为的目的。","说明移动或行动是为了做什么。","表达努力达到能力、状态或避免某结果。"],"cautions":["前接动词ます形词干，或动作性名词；不是接完整「ます」形。","不要保留「ます」再接句型。"],"specialCases":["「買い物に行く」等名词可直接接「に行く」。"]},"g-n5-024":{"overview":"「～てから」的核心意义是：表示先完成 A，再做 B。表示动作的时间、进行阶段、完成状态或结果状态。","category":"时态・体","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + から","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["明确表示先完成前项，再进行后项。","说明动作是否发生、是否完成或是否持续。","把两个动作按先后或状态关系连接起来。"],"cautions":["前项必须先于后项；单纯说明起点持续有时用「て以来」。","日语的过去形也表示完成；「ている」不一定等于中文“正在”。"],"specialCases":["同一动作反复的普通顺序不一定需要「てから」，可直接用て形连接。"]},"g-n5-025":{"overview":"「～前に／～後で」的核心意义是：表示“在……之前 / ……之后”。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书形 + 前に / Vた + 後で","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。","前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["说明动作发生前后的时间关系。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。"],"cautions":["「前に」前多用辞书形，即使整句在过去；「後で」前多用た形。","辞书形、ている形和た形会改变动作相对时间。"],"specialCases":["名词接续为「Nの前に／Nの後で」。"]},"g-n5-026":{"overview":"「～ことができます」的核心意义是：表示能力或可能：“能够……”。表达能力、客观条件或实现某动作的可能性。","category":"能力・可能","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"V辞书形 + ことができる","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["表达能力、技能或条件上可以做某事。","说明会不会、能不能完成某动作。","描述场所、规则或条件允许做某事。"],"cautions":["前接辞书形；与许可「てもいい」意义不同。","可能形与许可表达不同；“有能力”不等于“被允许”。"],"specialCases":["口语常直接使用可能形，语气更简洁。"]},"gx-n5-1ijb8s9":{"overview":"「～も」的核心意义是：表示“也”；也可代替 は／が／を 等部分助词。说明名词与谓语、其他名词之间的语法关系。","category":"助词・格关系","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + も","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["表示同类追加“也”，或与数量词搭配表示强调。","标记主题之外的格关系、方向、范围或并列关系。","通过助词选择明确动作参与者与信息焦点。"],"cautions":["替代「は／が／を」时原助词通常消失；与「に／で／から」等可组合。","助词往往不能按中文介词逐字对应，应结合谓语的固定搭配判断。"],"specialCases":["「一度も〜ない」等结构中，与否定呼应表示“连一次也不”。"]},"gx-n5-1frf7uj":{"overview":"「～へ」的核心意义是：表示移动的方向，读作「え」。说明名词与谓语、其他名词之间的语法关系。","category":"助词・格关系","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"地点 + へ + 行く／来る／帰る","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["表示移动方向，焦点在朝向某处。","标记主题之外的格关系、方向、范围或并列关系。","通过助词选择明确动作参与者与信息焦点。"],"cautions":["读作「え」；到达点更明确时常用「に」。","助词往往不能按中文介词逐字对应，应结合谓语的固定搭配判断。"],"specialCases":["可与「の」组合成「〜へのN」，如「日本への旅行」。"]},"gx-n5-1mjj0eu":{"overview":"「～や～など」的核心意义是：不完全列举：“A、B之类”。并列理由、动作或例子，并说明列举是否完整。","category":"并列・列举","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + や + N + など","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["列举几个代表性名词并暗示还有其他项目。","列出多个同类事实、理由或动作。","用代表性项目暗示还有其他内容。"],"cautions":["「や」连接名词；「など」可省略，也可单独表示“之类”。","「と」偏完整列举，「や／など／とか」多为不完全列举。"],"specialCases":["完整列举通常用「と」。"]},"gx-n5-12pxw8u":{"overview":"「～か」的核心意义是：句末表示疑问；名词之间可表示“或者”。构成疑问、不定表达，或传达说话人的态度。","category":"疑问・终助词","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"文 + か / N + か + N","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["句末构成疑问，名词之间表示选择“或者”。","提问、确认信息或表示任意／全面范围。","在句末提示新信息、寻求共鸣或加强语气。"],"cautions":["礼貌疑问句中不一定需要上扬语调；普通体「か」有时显得较硬。","句末助词高度依赖语气和人际关系，中文译词不能固定。"],"specialCases":["疑问词＋か可变为不定表达，如「誰か」。"]},"gx-n5-1c5kdtw":{"overview":"「～ね」的核心意义是：寻求认同或确认：“……呢／吧”。构成疑问、不定表达，或传达说话人的态度。","category":"疑问・终助词","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"文 + ね","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["寻求认同、确认共同信息，或表达感叹。","提问、确认信息或表示任意／全面范围。","在句末提示新信息、寻求共鸣或加强语气。"],"cautions":["并非每次都等于中文“吧”；对明显不共享的信息滥用会显得强求认同。","句末助词高度依赖语气和人际关系，中文译词不能固定。"],"specialCases":["「よね」兼有提示新信息和寻求认同的作用。"]},"gx-n5-1k78uy3":{"overview":"「～よ」的核心意义是：向对方提供新信息或加强语气。构成疑问、不定表达，或传达说话人的态度。","category":"疑问・终助词","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"文 + よ","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["告知听话人尚不知道的信息，或加强判断、提醒。","提问、确认信息或表示任意／全面范围。","在句末提示新信息、寻求共鸣或加强语气。"],"cautions":["频繁或强势使用可能显得居高临下。","句末助词高度依赖语气和人际关系，中文译词不能固定。"],"specialCases":["与「ね」组合为「よね」时，既提示又确认。"]},"gx-n5-1atxtlv":{"overview":"「これ／それ／あれ／どれ」的核心意义是：指示事物：这个／那个／那个（远）／哪个。用于指出人、事物、地点以及它们的存在位置。","category":"存在・指示","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"これ・それ・あれ・どれ + は…","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["单独指代事物：靠近说话人／靠近听话人／远离双方／疑问。","说明某处有什么／有谁。","根据说话人与听话人的距离选择指示词。"],"cautions":["这些是代词，后面不能直接再接名词。","存在句的地点通常用「に」，动作发生地则多用「で」。"],"specialCases":["指前文内容时，「それ」常表示对方刚提到的事情。"]},"gx-n5-1cjs22f":{"overview":"「この／その／あの／どの」的核心意义是：必须直接修饰名词的指示词。用于指出人、事物、地点以及它们的存在位置。","category":"存在・指示","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"この・その・あの・どの + N","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["直接放在名词前指定事物。","说明某处有什么／有谁。","根据说话人与听话人的距离选择指示词。"],"cautions":["必须修饰名词，不能单独作代词；单独指物用「これ／それ／あれ／どれ」。","存在句的地点通常用「に」，动作发生地则多用「で」。"],"specialCases":["也可指话语中的信息距离，不只表示物理距离。"]},"gx-n5-dki11q":{"overview":"「ここ／そこ／あそこ／どこ」的核心意义是：指示地点：这里／那里／那边／哪里。用于指出人、事物、地点以及它们的存在位置。","category":"存在・指示","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"ここ・そこ・あそこ・どこ","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["指示地点或场所。","说明某处有什么／有谁。","根据说话人与听话人的距离选择指示词。"],"cautions":["礼貌说法常用「こちら／そちら／あちら／どちら」。","存在句的地点通常用「に」，动作发生地则多用「で」。"],"specialCases":["「そこ」也可指对方刚提到的情境或论点。"]},"gx-n5-1j76xzu":{"overview":"「～より～のほうが」的核心意义是：比较两者：“比起A，B更……”。设定比较基准，或说明数量、性质和程度。","category":"比较・程度","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"A より B のほうが + 形容词","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["比较两项，并指出B在某性质上程度更高。","比较两个对象或范围内的高低。","用极端例子、数量或结果说明程度。"],"cautions":["基本结构是「AよりBのほうが〜」；不要把比较基准和被评价对象颠倒。","比较对象、基准和评价对象的助词不能互换。"],"specialCases":["上下文明确时可省略「のほうが」或一方对象。"]},"gx-n5-1a5otf8":{"overview":"「～で一番」的核心意义是：在某范围内“最……”。设定比较基准，或说明数量、性质和程度。","category":"比较・程度","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"范围 + で + N + が一番 + 形容词","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["在明确范围内选出最高程度的对象。","比较两个对象或范围内的高低。","用极端例子、数量或结果说明程度。"],"cautions":["范围用「で」，被比较对象常用「が」。","比较对象、基准和评价对象的助词不能互换。"],"specialCases":["问句常用「何／誰／どこが一番〜ですか」。"]},"gx-n5-1rn5c93":{"overview":"「もう～ました」的核心意义是：表示动作已经完成：“已经……了”。表示动作的时间、进行阶段、完成状态或结果状态。","category":"时态・体","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"もう + Vました","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["说明预期中的动作已经完成。","说明动作是否发生、是否完成或是否持续。","把两个动作按先后或状态关系连接起来。"],"cautions":["「もう」与肯定过去搭配表示“已经”；与否定搭配常表示“不再”。","日语的过去形也表示完成；「ている」不一定等于中文“正在”。"],"specialCases":["回答「もう〜ましたか」常用「はい、もう〜ました／いいえ、まだです」。"]},"gx-n5-xpfeuf":{"overview":"「まだ～ていません」的核心意义是：表示动作尚未完成：“还没……”。表示动作的时间、进行阶段、完成状态或结果状态。","category":"时态・体","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"まだ + Vていません","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["说明到目前为止动作尚未完成。","说明动作是否发生、是否完成或是否持续。","把两个动作按先后或状态关系连接起来。"],"cautions":["用「ていません」表达“还没做”，而不是简单现在否定「ません」。","日语的过去形也表示完成；「ている」不一定等于中文“正在”。"],"specialCases":["「まだ」与肯定形式也可表示“仍然”。"]},"gx-n5-1x4e5gj":{"overview":"「あまり～ない」的核心意义是：与否定搭配，表示“不太……”。与否定形式呼应，弱化或强化否定程度。","category":"否定程度","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"あまり + 否定","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["弱化否定，表示程度或频率不高。","表达“不太……”或“完全不……”。","调整否定判断的强弱。"],"cautions":["标准用法与否定谓语呼应。","传统教材多要求与否定呼应；现代口语中「全然」也可修饰肯定，但语体较口语。"],"specialCases":["比直接否定语气柔和。"]},"gx-n5-z3uq7t":{"overview":"「全然～ない」的核心意义是：与否定搭配，表示“完全不……”。与否定形式呼应，弱化或强化否定程度。","category":"否定程度","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"全然 + 否定","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["强化全面否定，表示完全不。","表达“不太……”或“完全不……”。","调整否定判断的强弱。"],"cautions":["考试和正式写作中优先与否定呼应。","传统教材多要求与否定呼应；现代口语中「全然」也可修饰肯定，但语体较口语。"],"specialCases":["现代口语可说「全然大丈夫」等肯定搭配，但语体较口语。"]},"gx-n5-1jwsaac":{"overview":"「～ましょうか」的核心意义是：主动提出帮忙或征求一起行动的意见。用于请求、邀请、提议或向对方征求行动意见。","category":"请求・邀请","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vます去ます + ましょうか","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。"],"usages":["主动提出为对方做事，或征求是否一起行动。","礼貌地请对方做或不做某事。","邀请共同参与，或主动提出帮助。"],"cautions":["语境决定是“我来……吧”还是“一起……吧”。","不要保留「ます」再接句型。"],"specialCases":["接受帮助可答「お願いします」；拒绝可用「いいえ、結構です」。"]},"gx-n5-10x1zzt":{"overview":"「～時」的核心意义是：表示“……的时候”；前项时态与动作先后有关。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + 時 / Nの + 時","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["说明主句动作发生时的状态或时间。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。"],"cautions":["前项辞书形／た形反映相对先后，不一定与整句绝对时态一致。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。"],"specialCases":["名词接「Nの時」，な形容词接「な時」。"]},"gx-n5-1aw2p7r":{"overview":"「～と思います」的核心意义是：表示意见或推测：“我觉得……”。引用话语、想法和信息，或给事物命名、下定义。","category":"引用・定义","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"普通形 + と思います","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["表达自己的意见、判断或较委婉的推测。","转述说话内容或表达自己的判断。","说明名称、概念和前文结论。"],"cautions":["引用内容使用普通形；名词和な形容词现在肯定常为「だと思う」。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。"],"specialCases":["询问对方意见常说「どう思いますか」。"]},"gx-n5-y2g13i":{"overview":"「～と言います」的核心意义是：引用说话内容或表示名称。引用话语、想法和信息，或给事物命名、下定义。","category":"引用・定义","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"普通形／「引用」+ と言う","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["引用话语，或说明人、事物的名称。","转述说话内容或表达自己的判断。","说明名称、概念和前文结论。"],"cautions":["直接引用用引号保留原话；间接引用要调整人称和时态。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。"],"specialCases":["命名常用「〜といいます／〜というN」。"]},"gx-n5-1kgof7u":{"overview":"「～でしょう」的核心意义是：表示推测或征求确认：“大概……吧”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + でしょう","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["表达较有依据的推测，或以升调向对方确认。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。"],"cautions":["降调多为推测，升调常为确认；功能由语调和语境决定。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。"],"specialCases":["普通体常用「だろう」，语气较直接。"]},"gx-n5-o5j05w":{"overview":"「名词修饰句」的核心意义是：动词普通形或形容词可以直接放在名词前修饰。构成最基础的判断、性质描写和名词修饰。","category":"基础判断・描写","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + N","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["把动词普通形、形容词或名词判断放在名词前限定内容。","介绍身份、属性、状态或事物之间的关系。","把形容词或修饰成分组织成完整句子。"],"cautions":["日语修饰从句前不使用相当于中文“的”的「の」。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。"],"specialCases":["修饰从句中的主语常用「が」，口语有时可用「の」。"]},"gx-n5-1dktwcs":{"overview":"「～のが好き／上手／下手」的核心意义是：用「の」把动作名词化，再表示喜好或擅长程度。把动作或状态名词化后，作为喜好、能力等评价的对象。","category":"名词化・评价","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V普通形 + のが + 好き／上手／下手","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["把动作名词化后评价喜好或擅长程度。","表达喜欢、擅长或不擅长某种活动。","把整句动作当作名词成分使用。"],"cautions":["动作部分用普通形＋「の」；评价对象通常用「が」。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。"],"specialCases":["「上手／下手」直接评价对方时可能失礼，可改用更客观说法。"]},"gx-n5-1l8ue6l":{"overview":"「数量词 + 动词」的核心意义是：数量词通常放在助词之后、动词之前。说明数量在句中的位置、分配方式或递增单位。","category":"数量・分配","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Nを + 数量词 + V","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["把次数、人数、个数、时长等数量作为副词修饰动作。","表达一次做多少、每份多少或逐步变化。","把数量词作为副词性成分修饰动作。"],"cautions":["数量词通常位于格助词之后、动词之前，如「本を三冊買う」。","数量词通常不直接取代格助词，应放在合适的句法位置。"],"specialCases":["表示持续时间时通常不加「に」：三時間勉強する。"]},"gx-n5-1oe8uw4":{"overview":"「形容词～くて／～で」的核心意义是：连接两个性质或状态。构成最基础的判断、性质描写和名词修饰。","category":"基础判断・描写","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"い形：～くて / な形・N：～で","formationNotes":["な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["连接同一主语的多个性质、状态或并列原因。","介绍身份、属性、状态或事物之间的关系。","把形容词或修饰成分组织成完整句子。"],"cautions":["い形容词用「くて」，な形容词和名词用「で」。","要区分名词／な形容词与い形容词的活用方式。"],"specialCases":["若前后是明显逆接关系，应使用「が／けれど」等。"]},"g-n4-001":{"overview":"「～んです／のです」的核心意义是：用于解释背景、原因，或向对方寻求解释。补充背景、原因、依据或说话人的解释。","category":"说明・理由","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"普通形 + んです（N/な形：なんです）","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：用于解释背景、原因，或向对方寻求解释。","解释为什么出现某结果。","在会话、说明文或正式通知中交代理由。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["用于解释背景或寻求说明，不只是把「です」换一种说法。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","原因句型可能带客观说明、感谢、责怪或辩解等不同语气。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["名词、な形容词现在肯定接「なんです」。","后项能否接命令、请求或意志表达，取决于具体形式。"]},"g-n4-002":{"overview":"「～と思います」的核心意义是：表达判断、意见或推测：“我认为……”。引用话语、想法和信息，或给事物命名、下定义。","category":"引用・定义","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"普通形 + と思う","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["表达自己的意见、判断或较委婉的推测。","转述说话内容或表达自己的判断。","说明名称、概念和前文结论。"],"cautions":["引用内容使用普通形；名词和な形容词现在肯定常为「だと思う」。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。"],"specialCases":["询问对方意见常说「どう思いますか」。"]},"g-n4-003":{"overview":"「～と言います」的核心意义是：引用话语或内容：“说……”。引用话语、想法和信息，或给事物命名、下定义。","category":"引用・定义","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"普通形/引用 + と言う","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["引用话语，或说明人、事物的名称。","转述说话内容或表达自己的判断。","说明名称、概念和前文结论。"],"cautions":["直接引用用引号保留原话；间接引用要调整人称和时态。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。"],"specialCases":["命名常用「〜といいます／〜というN」。"]},"g-n4-004":{"overview":"「～そうです（样态）」的核心意义是：根据眼前样子判断：“看起来……”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vます去ます / い形去い / な形 + そう","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：根据眼前样子判断：“看起来……”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["い形容词去「い」，な形容词直接接；「いい」通常为「よさそうだ」，否定形常用「〜そうにない／〜なさそうだ」。","不要保留「ます」再接句型。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["样态形式没有过去观察的普通形接续，重点是眼前迹象。","确信度、证据来源和语体决定应选哪一种形式。"]},"g-n4-005":{"overview":"「～そうです（传闻）」的核心意义是：表示从他人或媒体得知：“听说……”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"普通形 + そうだ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：表示从他人或媒体得知：“听说……”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["前接完整普通形，不做词干变化；不要与样态「そうだ」混用。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["传闻来源常用「〜によると／〜では」。","确信度、证据来源和语体决定应选哪一种形式。"]},"g-n4-006":{"overview":"「～ようです」的核心意义是：根据情况、证据推测：“似乎、好像……”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"普通形 + ようだ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：根据情况、证据推测：“似乎、好像……”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["「ようだ」偏中性，「みたいだ」更口语；名词接续分别常为「Nのようだ／Nみたいだ」。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["修饰名词用「ような」，修饰动词或形容词用「ように」。","确信度、证据来源和语体决定应选哪一种形式。"]},"g-n4-007":{"overview":"「～みたいです」的核心意义是：「ようだ」的较口语表达：“好像……”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"偏口语","note":"适合会话或带个人态度的表达；正式场合需选择更中性的形式。"},"formation":"普通形/N + みたいだ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：「ようだ」的较口语表达：“好像……”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","适合会话或带个人态度的表达；正式场合需选择更中性的形式。"],"cautions":["「ようだ」偏中性，「みたいだ」更口语；名词接续分别常为「Nのようだ／Nみたいだ」。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["修饰名词用「ような」，修饰动词或形容词用「ように」。","确信度、证据来源和语体决定应选哪一种形式。"]},"g-n4-008":{"overview":"「～かもしれません」的核心意义是：表示可能性：“也许、可能……”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"普通形 + かもしれない","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：表示可能性：“也许、可能……”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["表示可能性较低或不确定，不能用来表达高度确信。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["礼貌形为「かもしれません」，会话中有时缩为「かも」。","确信度、证据来源和语体决定应选哪一种形式。"]},"g-n4-009":{"overview":"「可能形」的核心意义是：表示能力、条件许可：“能……”。表达能力、客观条件或实现某动作的可能性。","category":"能力・可能","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"書く→書ける / 食べる→食べられる","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示能力、条件许可：“能……”。","说明会不会、能不能完成某动作。","描述场所、规则或条件允许做某事。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["五段动词变え段＋る；一段动词去る＋られる；する→できる；来る→来られる。","可能形与许可表达不同；“有能力”不等于“被允许”。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["口语中的「ら抜き」形式不宜用于规范写作。","一段动词的可能形与被动形外形相同，要靠助词和语境判断。"]},"g-n4-010":{"overview":"「～たことがあります」的核心意义是：表示过去经历：“曾经……过”。表达过去经历、一般常识、感慨或回忆性的习惯。","category":"经历・惯常","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vた + ことがある","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。"],"usages":["用于表达：表示过去经历：“曾经……过”。","说明曾经做过某事。","概括通常规律，或回想过去经常发生的事。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["只能用过去形「Vた」表示经历；不要与「V辞书形ことがある＝有时会」混淆。","「Vたことがある」是经历；「V辞书形ことがある」表示有时会发生。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["否定经历常用「Vたことがない」。","「ものだ」的常识、感慨与回忆用法应靠时态和语境区分。"]},"g-n4-011":{"overview":"「～たり～たりします」的核心意义是：列举代表性动作：“做做……、做做……”。并列理由、动作或例子，并说明列举是否完整。","category":"并列・列举","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vた + り、Vた + りする","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。"],"usages":["用于表达：列举代表性动作：“做做……、做做……”。","列出多个同类事实、理由或动作。","用代表性项目暗示还有其他内容。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["列举的是代表性动作，不表示动作顺序；句末通常保留「する」。","「と」偏完整列举，「や／など／とか」多为不完全列举。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["时态由最后的「する」承担：したりした。","列举句型通常要求前后项目在语法形式和评价方向上协调。"]},"g-n4-012":{"overview":"「～ながら」的核心意义是：表示同一主体同时进行两个动作：“一边……一边……”。表示两个动作并行、顺便进行，或两个变化相互伴随。","category":"同步・伴随","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vます去ます + ながら","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。"],"usages":["用于表达：表示同一主体同时进行两个动作：“一边……一边……”。","说明同一主体同时做两件事。","表达随一个变化发生另一个变化，或利用机会顺便做事。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示同时动作时前后主语原则上相同，后项通常是主要动作。","不要保留「ます」再接句型。","同时动作常要求主语一致；长期副业与一次性顺便行为要区分。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「つつ」比「ながら」书面；「つつも」则表示逆接。","正式书面形式与日常「ながら」在语域上不同。"]},"g-n4-013":{"overview":"「～し」的核心意义是：列举多个理由或特征，并暗示还有其他理由。并列理由、动作或例子，并说明列举是否完整。","category":"并列・列举","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + し","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：列举多个理由或特征，并暗示还有其他理由。","列出多个同类事实、理由或动作。","用代表性项目暗示还有其他内容。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可只列一个理由，以「し」暗示还有未说出的理由。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「と」偏完整列举，「や／など／とか」多为不完全列举。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["名词、な形容词在普通体中常接「だし」。","列举句型通常要求前后项目在语法形式和评价方向上协调。"]},"g-n4-014":{"overview":"「～ので」的核心意义是：表示原因，语气比「から」柔和、客观。补充背景、原因、依据或说话人的解释。","category":"说明・理由","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + ので（N/な形：なので）","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示原因，语气比「から」柔和、客观。","解释为什么出现某结果。","在会话、说明文或正式通知中交代理由。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["语气较客观柔和，常用于礼貌说明；命令、强烈主张后接时限制较多。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","原因句型可能带客观说明、感谢、责怪或辩解等不同语气。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["名词、な形容词现在肯定接「なので」。","后项能否接命令、请求或意志表达，取决于具体形式。"]},"g-n4-015":{"overview":"「～のに」的核心意义是：表示与期待相反：“明明……却……”。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + のに（N/な形：なのに）","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示与期待相反：“明明……却……”。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["常带意外、遗憾或不满；后项通常不是说话人的命令或请求。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「V辞书形＋のに」也可表示用途“用于……”，需与逆接区分。","要区分既成事实的逆接与假设条件的让步。"]},"g-n4-016":{"overview":"「～ても」的核心意义是：表示让步：“即使……也……”。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて / い形くて / N・な形でも","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示让步：“即使……也……”。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示即使前项成立，后项仍不改变；与许可「てもいい」不同。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["名词、な形容词使用「でも」。","要区分既成事实的逆接与假设条件的让步。"]},"g-n4-017":{"overview":"「～たら」的核心意义是：表示假设条件，也可表示“做完 A 后 B”。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形过去 + ら","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。"],"usages":["用于表达：表示假设条件，也可表示“做完 A 后 B”。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["既可表示假设，也可表示前项完成后发现后项；语境决定。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项可接意志、命令和请求，使用范围较广。","必要条件与充分条件不应混为一谈。"]},"g-n4-018":{"overview":"「～と（条件）」的核心意义是：表示自然规律、必然结果：“一……就……”。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"辞书形 + と","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：表示自然规律、必然结果：“一……就……”。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["常用于自然规律、机器操作和习惯结果；后项一般不接说话人的命令、请求或意志。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["也可表示做了前项后发现意外事实。","必要条件与充分条件不应混为一谈。"]},"g-n4-019":{"overview":"「～なら」的核心意义是：基于对方话题提出判断或建议：“如果是……的话”。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形/N + なら","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：基于对方话题提出判断或建议：“如果是……的话”。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["常承接对方已提出的信息，再给建议或判断；不要求前项时间上先发生。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["名词可直接接「なら」。","必要条件与充分条件不应混为一谈。"]},"g-n4-020":{"overview":"「～なければなりません」的核心意义是：表示义务：“必须……”。表达可以做、不可以做、必须做或不必做。","category":"许可・禁止・义务","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vない去い + ければならない","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示义务：“必须……”。","说明规则、许可、禁止和必要性。","在日常交流中询问或给予行动许可。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["两者都表示义务；会话中常缩为「なきゃ／なくちゃ」。","先正确变出ない形，不能从辞书形机械删除词尾。","义务强度与礼貌度不同，对特定听话人直接使用强制表达可能显得生硬。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["否定形式整体表示肯定义务，不要逐词理解为否定。","口语中常有缩约，但正式说明应使用完整形式。"]},"g-n4-021":{"overview":"「～なくてもいいです」的核心意义是：表示不做也可以：“不必……”。表达可以做、不可以做、必须做或不必做。","category":"许可・禁止・义务","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vない去い + くてもいい","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示不做也可以：“不必……”。","说明规则、许可、禁止和必要性。","在日常交流中询问或给予行动许可。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["表示没有做前项的必要，不等于禁止做。","先正确变出ない形，不能从辞书形机械删除词尾。","义务强度与礼貌度不同，对特定听话人直接使用强制表达可能显得生硬。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与「てはいけない」意义相反。","口语中常有缩约，但正式说明应使用完整形式。"]},"g-n4-022":{"overview":"「～ほうがいいです」的核心意义是：提出建议：“最好…… / 最好不要……”。基于常识、责任、既定事实或立场提出应有行动。","category":"建议・责任","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vた / Vない + ほうがいい","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：提出建议：“最好…… / 最好不要……”。","给出建议、忠告或道义判断。","表示既然前项成立，就应承担相应后果。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["肯定建议通常用た形，否定建议用ない形。","先正确变出ない形，不能从辞书形机械删除词尾。","语气通常比单纯建议强；对听话人使用时需注意礼貌。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["直接对长辈给强建议可能失礼，可用「〜たらいかがですか」。","客观义务、个人意见和社会责任应分别选择合适形式。"]},"g-n4-023":{"overview":"「～すぎます」的核心意义是：表示程度过量：“太……”。描述容易出现的倾向、程度过量或持续发展的趋势。","category":"趋势・倾向","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vます去ます / い形去い / な形 + すぎる","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示程度过量：“太……”。","说明经常发生、略有迹象或不断加剧。","评价行为或状态是否容易、过度或偏向某一方向。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["接动词ます形词干、い形词干或な形词干；自身按一段动词活用。","不要保留「ます」再接句型。","「がち／気味／っぽい」的负面程度和适用词类不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["通常表示超过适当程度，带负面或困扰语气。","趋势表达通常不用于一次性的偶然事件。"]},"g-n4-024":{"overview":"「～やすい／～にくい」的核心意义是：表示容易做 / 难做。描述容易出现的倾向、程度过量或持续发展的趋势。","category":"趋势・倾向","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vます去ます + やすい/にくい","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示容易做 / 难做。","说明经常发生、略有迹象或不断加剧。","评价行为或状态是否容易、过度或偏向某一方向。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示动作本身容易／难以进行，也可表示事物具有某种倾向。","不要保留「ます」再接句型。","「がち／気味／っぽい」的负面程度和适用词类不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与能力上的「できる／できない」不完全相同。","趋势表达通常不用于一次性的偶然事件。"]},"g-n4-025":{"overview":"「～てみます」的核心意义是：表示尝试做某事：“试着……”。说明试做、事先准备、彻底完成或即将采取行动。","category":"尝试・准备・完成","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vて + みる","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：表示尝试做某事：“试着……”。","尝试以前没有做过的行为。","为以后做准备，或说明动作完成后的语气。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["这里的「みる」是补助动词，通常写平假名，表示尝试而非“看”。","这些补助动词仍保留各自语义，不能只按一个中文词机械翻译。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["对无法由意志控制的状态一般不使用。","会话中常出现缩约形式，但写作中应使用完整形式。"]},"g-n4-026":{"overview":"「～ておきます」的核心意义是：表示为将来提前做准备，或保持某状态。说明试做、事先准备、彻底完成或即将采取行动。","category":"尝试・准备・完成","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vて + おく","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：表示为将来提前做准备，或保持某状态。","尝试以前没有做过的行为。","为以后做准备，或说明动作完成后的语气。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["可表示事先准备，也可表示暂时保持现状；口语缩为「とく／どく」。","这些补助动词仍保留各自语义，不能只按一个中文词机械翻译。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["根据语境可译为“先……”或“就让它……”。","会话中常出现缩约形式，但写作中应使用完整形式。"]},"g-n4-027":{"overview":"「～てしまいます」的核心意义是：表示做完，或带有遗憾/不小心的语气。说明试做、事先准备、彻底完成或即将采取行动。","category":"尝试・准备・完成","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"Vて + しまう","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：表示做完，或带有遗憾/不小心的语气。","尝试以前没有做过的行为。","为以后做准备，或说明动作完成后的语气。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["既可表示彻底完成，也可表达遗憾、意外或不小心；口语缩为「ちゃう／じゃう」。","这些补助动词仍保留各自语义，不能只按一个中文词机械翻译。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["是否含遗憾需由语境判断。","会话中常出现缩约形式，但写作中应使用完整形式。"]},"g-n4-028":{"overview":"「～てあげる／くれる／もらう」的核心意义是：表示动作恩惠的方向。从说话人视角说明谁为谁做事以及受益方向。","category":"授受・受益","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + あげる/くれる/もらう","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示动作恩惠的方向。","表达为别人做、别人为我方做、请别人为自己做。","在请求与感谢中标明恩惠关系。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["选择取决于恩惠方向：向外「あげる」、向我方「くれる」、从接受者视角「もらう」。","主语、动作执行者和受益者不能混淆；人际内外关系会影响选择。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["请求上级常用「ていただく」，避免用「あげる」突出自己的恩惠。","对上级直接用「あげる」描述自己的恩惠可能显得居高临下。"]},"g-n4-029":{"overview":"「～てあります」的核心意义是：表示人为动作完成后留下的状态。表示动作的时间、进行阶段、完成状态或结果状态。","category":"时态・体","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"他动词て + ある","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：表示人为动作完成后留下的状态。","说明动作是否发生、是否完成或是否持续。","把两个动作按先后或状态关系连接起来。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["通常接他动词，动作对象多用「が」，强调有人有意做后留下的状态。","日语的过去形也表示完成；「ている」不一定等于中文“正在”。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与自动词结果状态、单纯「ている」要区分。","瞬间动词与持续动词接体表达时，解释可能不同。"]},"g-n4-030":{"overview":"「～ようになります」的核心意义是：表示能力、习惯或状态发生变化。描述状态、习惯、能力或趋势发生变化，以及人为改变。","category":"变化・结果","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"V辞书/ない/可能形 + ようになる","formationNotes":["前接动词使用辞书形，不接「ます」。","前接可能形；一段动词与被动形同形，需先确认语义。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示能力、习惯或状态发生变化。","说明从过去到现在或从现在向未来的变化。","表达自然变化、主动改变或动作的开始／持续／结束。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["表示自然形成的新能力、习惯或状态；可能形＋ようになる很常见。","要区分自然变化「なる」与人为改变「する」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["主动努力保持行为用「ようにする」。","方向补助动词「てくる／ていく」也可表示时间上的变化。"]},"g-n4-031":{"overview":"「～ようにします」的核心意义是：表示有意识地努力养成习惯。说明个人决定、外部安排、规则或持续努力形成的习惯。","category":"习惯・决定・规则","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"V辞书/ない + ようにする","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示有意识地努力养成习惯。","表达自己决定做什么。","说明制度安排、既定规则或日常坚持。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["表示有意识地努力做到或避免；持续习惯用「ようにしている」。","「ことにする」与「ことになる」的决定主体不同；「ようにする」强调努力。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["自然变化用「ようになる」。","进行体形式常表示决定或规则持续有效。"]},"g-n4-032":{"overview":"「～つもりです」的核心意义是：表示个人打算。表达说话人的愿望、意志、打算或既定计划。","category":"愿望・意志・计划","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"V辞书/ない + つもり","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示个人打算。","说明自己想做什么、想要什么。","区分临时意向、个人打算与已经安排的日程。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["表示主语已经形成的个人意图；不用于描述明显不由意志控制的结果。","直接愿望通常以说话人自己为主；第三者愿望需使用观察或引用表达。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「つもりだった」可表示原有打算未必实现。","计划的确定程度和决定主体会影响句型选择。"]},"g-n4-033":{"overview":"「～予定です」的核心意义是：表示已经安排好的计划、日程。表达说话人的愿望、意志、打算或既定计划。","category":"愿望・意志・计划","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"V辞书/Nの + 予定","formationNotes":["前接动词使用辞书形，不接「ます」。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示已经安排好的计划、日程。","说明自己想做什么、想要什么。","区分临时意向、个人打算与已经安排的日程。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["侧重客观安排或日程，确定度通常高于临时意向。","直接愿望通常以说话人自己为主；第三者愿望需使用观察或引用表达。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["名词接「Nの予定だ」。","计划的确定程度和决定主体会影响句型选择。"]},"g-n4-034":{"overview":"「～ことにします」的核心意义是：表示说话人主动做出决定。说明个人决定、外部安排、规则或持续努力形成的习惯。","category":"习惯・决定・规则","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"V辞书/ない + ことにする","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示说话人主动做出决定。","表达自己决定做什么。","说明制度安排、既定规则或日常坚持。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["决定主体是说话人或主语；「ことにしている」可表示个人规则。","「ことにする」与「ことになる」的决定主体不同；「ようにする」强调努力。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与外部决定的「ことになる」对照。","进行体形式常表示决定或规则持续有效。"]},"g-n4-035":{"overview":"「～ことになります」的核心意义是：表示由外部安排、规则或情况决定。说明个人决定、外部安排、规则或持续努力形成的习惯。","category":"习惯・决定・规则","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"V辞书/ない + ことになる","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示由外部安排、规则或情况决定。","表达自己决定做什么。","说明制度安排、既定规则或日常坚持。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["表示组织、规则、他人或事态发展造成的决定，也可表示逻辑结果。","「ことにする」与「ことになる」的决定主体不同；「ようにする」强调努力。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「ことになっている」常表示既定规则或安排。","进行体形式常表示决定或规则持续有效。"]},"gx-n4-1cbyiph":{"overview":"「～そうだ（样态）」的核心意义是：根据眼前迹象判断“看起来……”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vます去ます／い形去い／な形 + そうだ","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：根据眼前迹象判断“看起来……”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["い形容词去「い」，な形容词直接接；「いい」通常为「よさそうだ」，否定形常用「〜そうにない／〜なさそうだ」。","不要保留「ます」再接句型。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["样态形式没有过去观察的普通形接续，重点是眼前迹象。","确信度、证据来源和语体决定应选哪一种形式。"]},"gx-n4-axzupa":{"overview":"「～そうだ（传闻）」的核心意义是：转述听到的信息：“听说……”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + そうだ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：转述听到的信息：“听说……”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["前接完整普通形，不做词干变化；不要与样态「そうだ」混用。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["传闻来源常用「〜によると／〜では」。","确信度、证据来源和语体决定应选哪一种形式。"]},"gx-n4-uq21qt":{"overview":"「～ようだ」的核心意义是：根据证据作较客观推测：“似乎、好像”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + ようだ（Nの／な形な）","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","名词后先加「の」再连接。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：根据证据作较客观推测：“似乎、好像”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「ようだ」偏中性，「みたいだ」更口语；名词接续分别常为「Nのようだ／Nみたいだ」。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["修饰名词用「ような」，修饰动词或形容词用「ように」。","确信度、证据来源和语体决定应选哪一种形式。"]},"gx-n4-jbxhv7":{"overview":"「～みたいだ」的核心意义是：「ようだ」的口语表达：“好像……”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"偏口语","note":"适合会话或带个人态度的表达；正式场合需选择更中性的形式。"},"formation":"普通形／N + みたいだ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：「ようだ」的口语表达：“好像……”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","适合会话或带个人态度的表达；正式场合需选择更中性的形式。"],"cautions":["「ようだ」偏中性，「みたいだ」更口语；名词接续分别常为「Nのようだ／Nみたいだ」。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["修饰名词用「ような」，修饰动词或形容词用「ように」。","确信度、证据来源和语体决定应选哪一种形式。"]},"gx-n4-1uro7mp":{"overview":"「～かもしれない」的核心意义是：表示不确定可能：“也许、可能”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + かもしれない","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：表示不确定可能：“也许、可能”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示可能性较低或不确定，不能用来表达高度确信。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["礼貌形为「かもしれません」，会话中有时缩为「かも」。","确信度、证据来源和语体决定应选哪一种形式。"]},"gx-n4-1rw5r3o":{"overview":"「～たことがある」的核心意义是：表示曾经有过某种经历。表达过去经历、一般常识、感慨或回忆性的习惯。","category":"经历・惯常","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vた + ことがある","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。"],"usages":["用于表达：表示曾经有过某种经历。","说明曾经做过某事。","概括通常规律，或回想过去经常发生的事。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["只能用过去形「Vた」表示经历；不要与「V辞书形ことがある＝有时会」混淆。","「Vたことがある」是经历；「V辞书形ことがある」表示有时会发生。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["否定经历常用「Vたことがない」。","「ものだ」的常识、感慨与回忆用法应靠时态和语境区分。"]},"gx-n4-1vvi6d7":{"overview":"「～たり～たりする」的核心意义是：列举代表性动作：“做做A、做做B之类”。并列理由、动作或例子，并说明列举是否完整。","category":"并列・列举","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vた + り、Vた + りする","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。"],"usages":["用于表达：列举代表性动作：“做做A、做做B之类”。","列出多个同类事实、理由或动作。","用代表性项目暗示还有其他内容。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["列举的是代表性动作，不表示动作顺序；句末通常保留「する」。","「と」偏完整列举，「や／など／とか」多为不完全列举。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["时态由最后的「する」承担：したりした。","列举句型通常要求前后项目在语法形式和评价方向上协调。"]},"gx-n4-1h2cra1":{"overview":"「～し～し」的核心意义是：列举并列理由或特点：“又……又……”。并列理由、动作或例子，并说明列举是否完整。","category":"并列・列举","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + し","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：列举并列理由或特点：“又……又……”。","列出多个同类事实、理由或动作。","用代表性项目暗示还有其他内容。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可只列一个理由，以「し」暗示还有未说出的理由。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「と」偏完整列举，「や／など／とか」多为不完全列举。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["名词、な形容词在普通体中常接「だし」。","列举句型通常要求前后项目在语法形式和评价方向上协调。"]},"gx-n4-1lo6ncy":{"overview":"「～なくてもいい」的核心意义是：表示“不做也可以／不必”。表达可以做、不可以做、必须做或不必做。","category":"许可・禁止・义务","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vない去い + くてもいい","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示“不做也可以／不必”。","说明规则、许可、禁止和必要性。","在日常交流中询问或给予行动许可。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示没有做前项的必要，不等于禁止做。","先正确变出ない形，不能从辞书形机械删除词尾。","义务强度与礼貌度不同，对特定听话人直接使用强制表达可能显得生硬。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与「てはいけない」意义相反。","口语中常有缩约，但正式说明应使用完整形式。"]},"gx-n4-1gfr88v":{"overview":"「～なければならない」的核心意义是：表示义务：“必须……”。表达可以做、不可以做、必须做或不必做。","category":"许可・禁止・义务","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vない去い + ければならない","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示义务：“必须……”。","说明规则、许可、禁止和必要性。","在日常交流中询问或给予行动许可。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["两者都表示义务；会话中常缩为「なきゃ／なくちゃ」。","先正确变出ない形，不能从辞书形机械删除词尾。","义务强度与礼貌度不同，对特定听话人直接使用强制表达可能显得生硬。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["否定形式整体表示肯定义务，不要逐词理解为否定。","口语中常有缩约，但正式说明应使用完整形式。"]},"gx-n4-w6hht8":{"overview":"「～なくてはいけない」的核心意义是：表示义务：“不……不行”，即必须。表达可以做、不可以做、必须做或不必做。","category":"许可・禁止・义务","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vない去い + くてはいけない","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示义务：“不……不行”，即必须。","说明规则、许可、禁止和必要性。","在日常交流中询问或给予行动许可。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["两者都表示义务；会话中常缩为「なきゃ／なくちゃ」。","先正确变出ない形，不能从辞书形机械删除词尾。","义务强度与礼貌度不同，对特定听话人直接使用强制表达可能显得生硬。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["否定形式整体表示肯定义务，不要逐词理解为否定。","口语中常有缩约，但正式说明应使用完整形式。"]},"gx-n4-1tnhlhg":{"overview":"「～ほうがいい」的核心意义是：提出建议：“最好……／最好不要……”。基于常识、责任、既定事实或立场提出应有行动。","category":"建议・责任","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vた + ほうがいい／Vない + ほうがいい","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：提出建议：“最好……／最好不要……”。","给出建议、忠告或道义判断。","表示既然前项成立，就应承担相应后果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["肯定建议通常用た形，否定建议用ない形。","先正确变出ない形，不能从辞书形机械删除词尾。","语气通常比单纯建议强；对听话人使用时需注意礼貌。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["直接对长辈给强建议可能失礼，可用「〜たらいかがですか」。","客观义务、个人意见和社会责任应分别选择合适形式。"]},"gx-n4-inhc57":{"overview":"「～すぎる」的核心意义是：表示超过适当程度：“太……”。描述容易出现的倾向、程度过量或持续发展的趋势。","category":"趋势・倾向","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vます去ます／い形去い／な形 + すぎる","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示超过适当程度：“太……”。","说明经常发生、略有迹象或不断加剧。","评价行为或状态是否容易、过度或偏向某一方向。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["接动词ます形词干、い形词干或な形词干；自身按一段动词活用。","不要保留「ます」再接句型。","「がち／気味／っぽい」的负面程度和适用词类不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["通常表示超过适当程度，带负面或困扰语气。","趋势表达通常不用于一次性的偶然事件。"]},"gx-n4-19pnc0y":{"overview":"「～始める／～終わる／～続ける」的核心意义是：表示动作开始、结束或持续。描述状态、习惯、能力或趋势发生变化，以及人为改变。","category":"变化・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vます去ます + 始める／終わる／続ける","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示动作开始、结束或持续。","说明从过去到现在或从现在向未来的变化。","表达自然变化、主动改变或动作的开始／持续／结束。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["接动词ます形词干，分别表示动作开始、结束或持续。","不要保留「ます」再接句型。","要区分自然变化「なる」与人为改变「する」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["瞬间完成的动词与「続ける」通常不自然。","方向补助动词「てくる／ていく」也可表示时间上的变化。"]},"gx-n4-1txwdhb":{"overview":"「～てみる」的核心意义是：尝试做某事：“试着……”。说明试做、事先准备、彻底完成或即将采取行动。","category":"尝试・准备・完成","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + みる","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：尝试做某事：“试着……”。","尝试以前没有做过的行为。","为以后做准备，或说明动作完成后的语气。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["这里的「みる」是补助动词，通常写平假名，表示尝试而非“看”。","这些补助动词仍保留各自语义，不能只按一个中文词机械翻译。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["对无法由意志控制的状态一般不使用。","会话中常出现缩约形式，但写作中应使用完整形式。"]},"gx-n4-1k4b94m":{"overview":"「～ておく」的核心意义是：为了之后而预先做；或让状态保持。说明试做、事先准备、彻底完成或即将采取行动。","category":"尝试・准备・完成","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + おく","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：为了之后而预先做；或让状态保持。","尝试以前没有做过的行为。","为以后做准备，或说明动作完成后的语气。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示事先准备，也可表示暂时保持现状；口语缩为「とく／どく」。","这些补助动词仍保留各自语义，不能只按一个中文词机械翻译。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["根据语境可译为“先……”或“就让它……”。","会话中常出现缩约形式，但写作中应使用完整形式。"]},"gx-n4-1p254l6":{"overview":"「～てしまう」的核心意义是：表示彻底完成，或遗憾、不小心发生。说明试做、事先准备、彻底完成或即将采取行动。","category":"尝试・准备・完成","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + しまう","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：表示彻底完成，或遗憾、不小心发生。","尝试以前没有做过的行为。","为以后做准备，或说明动作完成后的语气。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["既可表示彻底完成，也可表达遗憾、意外或不小心；口语缩为「ちゃう／じゃう」。","这些补助动词仍保留各自语义，不能只按一个中文词机械翻译。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["是否含遗憾需由语境判断。","会话中常出现缩约形式，但写作中应使用完整形式。"]},"gx-n4-gwbrlm":{"overview":"「～てあげる」的核心意义是：说话人/某人帮别人做某事。从说话人视角说明谁为谁做事以及受益方向。","category":"授受・受益","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + あげる","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：说话人/某人帮别人做某事。","表达为别人做、别人为我方做、请别人为自己做。","在请求与感谢中标明恩惠关系。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["选择取决于恩惠方向：向外「あげる」、向我方「くれる」、从接受者视角「もらう」。","主语、动作执行者和受益者不能混淆；人际内外关系会影响选择。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["请求上级常用「ていただく」，避免用「あげる」突出自己的恩惠。","对上级直接用「あげる」描述自己的恩惠可能显得居高临下。"]},"gx-n4-ckqp3":{"overview":"「～てくれる」的核心意义是：别人为说话人或“我方”做某事。从说话人视角说明谁为谁做事以及受益方向。","category":"授受・受益","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + くれる","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：别人为说话人或“我方”做某事。","表达为别人做、别人为我方做、请别人为自己做。","在请求与感谢中标明恩惠关系。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["选择取决于恩惠方向：向外「あげる」、向我方「くれる」、从接受者视角「もらう」。","主语、动作执行者和受益者不能混淆；人际内外关系会影响选择。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["请求上级常用「ていただく」，避免用「あげる」突出自己的恩惠。","对上级直接用「あげる」描述自己的恩惠可能显得居高临下。"]},"gx-n4-1slh5nq":{"overview":"「～てもらう」的核心意义是：说话人接受/请求别人帮忙做某事。从说话人视角说明谁为谁做事以及受益方向。","category":"授受・受益","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + もらう","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：说话人接受/请求别人帮忙做某事。","表达为别人做、别人为我方做、请别人为自己做。","在请求与感谢中标明恩惠关系。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["选择取决于恩惠方向：向外「あげる」、向我方「くれる」、从接受者视角「もらう」。","主语、动作执行者和受益者不能混淆；人际内外关系会影响选择。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["请求上级常用「ていただく」，避免用「あげる」突出自己的恩惠。","对上级直接用「あげる」描述自己的恩惠可能显得居高临下。"]},"gx-n4-v3eo1c":{"overview":"「自动词／他动词」的核心意义是：自动词描述状态变化，他动词描述人为使对象变化。表达被动、使役以及自动词与他动词的事件视角。","category":"被动・使役","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Nが + 自动词／Nを + 他动词","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：自动词描述状态变化，他动词描述人为使对象变化。","说明谁受到动作影响，或谁让谁做事。","选择以状态变化还是施事行为为叙述中心。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["自动词常用「Nが」，他动词常用「Nを」；需成对记忆具体动词。","被动句助词由原句结构决定；使役句的人物关系也影响「に／を」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["自动词不是被动形，他动词也不一定带人的主观故意。","一段动词的被动与可能形式相同，需要结合句法判断。"]},"gx-n4-1u35ii2":{"overview":"「～てある」的核心意义是：表示人为动作完成后留下的状态。表示动作的时间、进行阶段、完成状态或结果状态。","category":"时态・体","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"他动词Vて + ある","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：表示人为动作完成后留下的状态。","说明动作是否发生、是否完成或是否持续。","把两个动作按先后或状态关系连接起来。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["通常接他动词，动作对象多用「が」，强调有人有意做后留下的状态。","日语的过去形也表示完成；「ている」不一定等于中文“正在”。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与自动词结果状态、单纯「ている」要区分。","瞬间动词与持续动词接体表达时，解释可能不同。"]},"gx-n4-17ugzj7":{"overview":"「～ようになる」的核心意义是：表示能力、习惯或状态发生变化：“变得……”。描述状态、习惯、能力或趋势发生变化，以及人为改变。","category":"变化・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书／可能／ない + ようになる","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示能力、习惯或状态发生变化：“变得……”。","说明从过去到现在或从现在向未来的变化。","表达自然变化、主动改变或动作的开始／持续／结束。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示自然形成的新能力、习惯或状态；可能形＋ようになる很常见。","要区分自然变化「なる」与人为改变「する」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["主动努力保持行为用「ようにする」。","方向补助动词「てくる／ていく」也可表示时间上的变化。"]},"gx-n4-1ah05kx":{"overview":"「～なくなる」的核心意义是：表示“变得不再……”。描述状态、习惯、能力或趋势发生变化，以及人为改变。","category":"变化・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vない去い + くなる","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示“变得不再……”。","说明从过去到现在或从现在向未来的变化。","表达自然变化、主动改变或动作的开始／持续／结束。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["Vない去「い」＋くなる，表示从会做／做某事的状态变为不再做。","先正确变出ない形，不能从辞书形机械删除词尾。","要区分自然变化「なる」与人为改变「する」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["い形容词的否定变化也会出现「くなくなる」，需区分结构层次。","方向补助动词「てくる／ていく」也可表示时间上的变化。"]},"gx-n4-e4tr6":{"overview":"「～くなる／～になる」的核心意义是：表示自然变化：“变得……”。描述状态、习惯、能力或趋势发生变化，以及人为改变。","category":"变化・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"い形→くなる；N/な形→になる","formationNotes":["な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示自然变化：“变得……”。","说明从过去到现在或从现在向未来的变化。","表达自然变化、主动改变或动作的开始／持续／结束。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["い形容词用「くなる」，名词和な形容词用「になる」，表示自然变化。","要区分自然变化「なる」与人为改变「する」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["人为使其改变用「くする／にする」。","方向补助动词「てくる／ていく」也可表示时间上的变化。"]},"gx-n4-jim7yk":{"overview":"「～くする／～にする」的核心意义是：表示人为改变状态，或作出选择。描述状态、习惯、能力或趋势发生变化，以及人为改变。","category":"变化・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"い形→くする；N/な形→にする","formationNotes":["な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示人为改变状态，或作出选择。","说明从过去到现在或从现在向未来的变化。","表达自然变化、主动改变或动作的开始／持续／结束。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["い形容词用「くする」，名词和な形容词用「にする」，表示人为改变或作出选择。","要区分自然变化「なる」与人为改变「する」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["自然变化用「なる」。","方向补助动词「てくる／ていく」也可表示时间上的变化。"]},"gx-n4-1rt5btg":{"overview":"「～ようにする」的核心意义是：表示有意识地努力养成习惯或避免某事。说明个人决定、外部安排、规则或持续努力形成的习惯。","category":"习惯・决定・规则","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书／Vない + ようにする","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示有意识地努力养成习惯或避免某事。","表达自己决定做什么。","说明制度安排、既定规则或日常坚持。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示有意识地努力做到或避免；持续习惯用「ようにしている」。","先正确变出ない形，不能从辞书形机械删除词尾。","「ことにする」与「ことになる」的决定主体不同；「ようにする」强调努力。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["自然变化用「ようになる」。","进行体形式常表示决定或规则持续有效。"]},"gx-n4-ybpblh":{"overview":"「～ように（目的）」的核心意义是：表示为了达到能力、状态或避免某事。说明行动的目的、目标或为了达到某状态而采取的措施。","category":"目的","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V可能／Vない + ように","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示为了达到能力、状态或避免某事。","说明移动或行动是为了做什么。","表达努力达到能力、状态或避免某结果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["常接可能形、ない形或非意志状态，表示为了使某状态实现。","先正确变出ない形，不能从辞书形机械删除词尾。","「ために」与「ように」对意志性、主语和可控制性有不同限制。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项可为努力、准备、提醒等；前后主语可以不同。","目的句前后主语是否相同，需要按具体句型确认。"]},"gx-n4-1axsf3f":{"overview":"「～ために（目的）」的核心意义是：表示有意志动作的目的：“为了……”。说明行动的目的、目标或为了达到某状态而采取的措施。","category":"目的","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书／Nの + ために","formationNotes":["前接动词使用辞书形，不接「ます」。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示有意志动作的目的：“为了……”。","说明移动或行动是为了做什么。","表达努力达到能力、状态或避免某结果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["前项多为有意志、可控制的目标，前后主语原则上相同。","「ために」与「ように」对意志性、主语和可控制性有不同限制。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["能力、状态或否定目标常用「ように」。","目的句前后主语是否相同，需要按具体句型确认。"]},"gx-n4-1rw2wad":{"overview":"「～つもりだ」的核心意义是：表示个人打算、意图。表达说话人的愿望、意志、打算或既定计划。","category":"愿望・意志・计划","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书／Vない + つもりだ","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示个人打算、意图。","说明自己想做什么、想要什么。","区分临时意向、个人打算与已经安排的日程。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示主语已经形成的个人意图；不用于描述明显不由意志控制的结果。","先正确变出ない形，不能从辞书形机械删除词尾。","直接愿望通常以说话人自己为主；第三者愿望需使用观察或引用表达。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「つもりだった」可表示原有打算未必实现。","计划的确定程度和决定主体会影响句型选择。"]},"gx-n4-1szlw1l":{"overview":"「～予定だ」的核心意义是：表示已经安排或计划好的事项。表达说话人的愿望、意志、打算或既定计划。","category":"愿望・意志・计划","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书／Nの + 予定だ","formationNotes":["前接动词使用辞书形，不接「ます」。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示已经安排或计划好的事项。","说明自己想做什么、想要什么。","区分临时意向、个人打算与已经安排的日程。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["侧重客观安排或日程，确定度通常高于临时意向。","直接愿望通常以说话人自己为主；第三者愿望需使用观察或引用表达。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["名词接「Nの予定だ」。","计划的确定程度和决定主体会影响句型选择。"]},"gx-n4-1x5zmu7":{"overview":"「～ことにする」的核心意义是：表示由自己决定做/不做某事。说明个人决定、外部安排、规则或持续努力形成的习惯。","category":"习惯・决定・规则","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书／Vない + ことにする","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示由自己决定做/不做某事。","表达自己决定做什么。","说明制度安排、既定规则或日常坚持。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["决定主体是说话人或主语；「ことにしている」可表示个人规则。","先正确变出ない形，不能从辞书形机械删除词尾。","「ことにする」与「ことになる」的决定主体不同；「ようにする」强调努力。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与外部决定的「ことになる」对照。","进行体形式常表示决定或规则持续有效。"]},"gx-n4-1d3yty8":{"overview":"「～ことになる」的核心意义是：表示由外部安排、规则或结果决定。说明个人决定、外部安排、规则或持续努力形成的习惯。","category":"习惯・决定・规则","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书／Vない + ことになる","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示由外部安排、规则或结果决定。","表达自己决定做什么。","说明制度安排、既定规则或日常坚持。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示组织、规则、他人或事态发展造成的决定，也可表示逻辑结果。","先正确变出ない形，不能从辞书形机械删除词尾。","「ことにする」与「ことになる」的决定主体不同；「ようにする」强调努力。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「ことになっている」常表示既定规则或安排。","进行体形式常表示决定或规则持续有效。"]},"gx-n4-ny2tya":{"overview":"「～ようと思う」的核心意义是：表示当下或持续的打算：“想要……”。表达说话人的愿望、意志、打算或既定计划。","category":"愿望・意志・计划","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"意向形 + と思う","formationNotes":["前接意向形，如「行こう／食べよう／しよう／来よう」。"],"usages":["用于表达：表示当下或持续的打算：“想要……”。","说明自己想做什么、想要什么。","区分临时意向、个人打算与已经安排的日程。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["意向形＋と思う表示形成或保持某个打算；「と思っている」更突出持续意图。","直接愿望通常以说话人自己为主；第三者愿望需使用观察或引用表达。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["比「つもりだ」有时更接近当下想到的意向。","计划的确定程度和决定主体会影响句型选择。"]},"gx-n4-liltal":{"overview":"「意向形」的核心意义是：表示意志或提议：“……吧／打算……”。表达说话人的愿望、意志、打算或既定计划。","category":"愿望・意志・计划","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"五段：う段→お段+う；一段：る→よう","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示意志或提议：“……吧／打算……”。","说明自己想做什么、想要什么。","区分临时意向、个人打算与已经安排的日程。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["五段动词变お段＋う，一段动词去る＋よう；する→しよう，来る→来よう。","直接愿望通常以说话人自己为主；第三者愿望需使用观察或引用表达。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["单独使用可表示邀请或自言自语的意志。","计划的确定程度和决定主体会影响句型选择。"]},"gx-n4-1h7lvw":{"overview":"「被动形」的核心意义是：表示“被……”，也常用于客观叙述。表达被动、使役以及自动词与他动词的事件视角。","category":"被动・使役","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"五段：ない形词干+れる；一段：られる","formationNotes":["い形容词根据公式保留「い」或变为「く／くて／かった」。"],"usages":["用于表达：表示“被……”，也常用于客观叙述。","说明谁受到动作影响，或谁让谁做事。","选择以状态变化还是施事行为为叙述中心。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["被动动作主体常用「に／によって」；迷惑被动强调主语受到不利影响。","被动句助词由原句结构决定；使役句的人物关系也影响「に／を」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["一段动词被动形与可能形同形，助词和语义决定解释。","一段动词的被动与可能形式相同，需要结合句法判断。"]},"gx-n4-ijame":{"overview":"「迷惑被动」的核心意义是：用被动形式表达说话人受到不利影响。表达被动、使役以及自动词与他动词的事件视角。","category":"被动・使役","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"受影响者は + 人に + V被动","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：用被动形式表达说话人受到不利影响。","说明谁受到动作影响，或谁让谁做事。","选择以状态变化还是施事行为为叙述中心。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["被动动作主体常用「に／によって」；迷惑被动强调主语受到不利影响。","被动句助词由原句结构决定；使役句的人物关系也影响「に／を」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["一段动词被动形与可能形同形，助词和语义决定解释。","一段动词的被动与可能形式相同，需要结合句法判断。"]},"gx-n4-1gaad79":{"overview":"「使役形」的核心意义是：表示让/使某人做某事。表达被动、使役以及自动词与他动词的事件视角。","category":"被动・使役","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"五段：ない形词干+せる；一段：させる","formationNotes":["い形容词根据公式保留「い」或变为「く／くて／かった」。"],"usages":["用于表达：表示让/使某人做某事。","说明谁受到动作影响，或谁让谁做事。","选择以状态变化还是施事行为为叙述中心。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["让某人做某事时，被使役者常用「に」；让其进行移动或自动词行为时也可能用「を」。","被动句助词由原句结构决定；使役句的人物关系也影响「に／を」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["上级允许下级做事也可用使役，翻译未必是强迫。","一段动词的被动与可能形式相同，需要结合句法判断。"]},"gx-n4-1jho9hy":{"overview":"「命令形／禁止形」的核心意义是：强烈命令“做！”或“别做！”，日常使用需谨慎。表达可以做、不可以做、必须做或不必做。","category":"许可・禁止・义务","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"命令形 / V辞书 + な","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：强烈命令“做！”或“别做！”，日常使用需谨慎。","说明规则、许可、禁止和必要性。","在日常交流中询问或给予行动许可。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["直接命令形和「V辞书＋な」语气很强；「なさい」多用于上对下。","义务强度与礼貌度不同，对特定听话人直接使用强制表达可能显得生硬。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["公共指示、紧急情况、口号和转述规则中较常见。","口语中常有缩约，但正式说明应使用完整形式。"]},"gx-n4-r0xcu0":{"overview":"「～なさい」的核心意义是：比直接命令形稍柔和，常用于上对下指示。用于请求、邀请、提议或向对方征求行动意见。","category":"请求・邀请","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vます去ます + なさい","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。"],"usages":["用于表达：比直接命令形稍柔和，常用于上对下指示。","礼貌地请对方做或不做某事。","邀请共同参与，或主动提出帮助。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["直接命令形和「V辞书＋な」语气很强；「なさい」多用于上对下。","不要保留「ます」再接句型。","礼貌程度取决于句型、句尾和人际关系；对上级需避免命令感。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["公共指示、紧急情况、口号和转述规则中较常见。","否定请求、提议和许可的形式相似，必须看完整句型。"]},"gx-n4-1yv6geh":{"overview":"「疑问词 + か」的核心意义是：表示不定的人、物、地点：“某……”。构成疑问、不定表达，或传达说话人的态度。","category":"疑问・终助词","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"誰／何／どこ／いつ + か","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示不定的人、物、地点：“某……”。","提问、确认信息或表示任意／全面范围。","在句末提示新信息、寻求共鸣或加强语气。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["组合后成为不定代词，如「誰か＝某人」，句末不一定是疑问。","句末助词高度依赖语气和人际关系，中文译词不能固定。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["格助词通常放在组合后：誰かに、どこかへ。","疑问词与「か／も／でも」组合后，句子不一定仍是疑问句。"]},"gx-n4-am01r9":{"overview":"「疑问词 + も + 否定」的核心意义是：表示全面否定：“谁也不／什么也不……”。构成疑问、不定表达，或传达说话人的态度。","category":"疑问・终助词","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"疑问词 + も + 否定","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示全面否定：“谁也不／什么也不……”。","提问、确认信息或表示任意／全面范围。","在句末提示新信息、寻求共鸣或加强语气。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["与否定呼应表示全面否定，如「誰も来ない」。","句末助词高度依赖语气和人际关系，中文译词不能固定。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「何も」在肯定句中也可表示“什么都”，但需特定语境。","疑问词与「か／も／でも」组合后，句子不一定仍是疑问句。"]},"gx-n4-9uupzx":{"overview":"「疑问词 + でも」的核心意义是：表示任意选择：“无论谁／什么／哪里都……”。构成疑问、不定表达，或传达说话人的态度。","category":"疑问・终助词","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"疑问词 + でも","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示任意选择：“无论谁／什么／哪里都……”。","提问、确认信息或表示任意／全面范围。","在句末提示新信息、寻求共鸣或加强语气。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示范围内任意选择都可以，如「誰でも」。","句末助词高度依赖语气和人际关系，中文译词不能固定。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与让步条件「Vても」不是同一结构。","疑问词与「か／も／でも」组合后，句子不一定仍是疑问句。"]},"gx-n4-1mch6ue":{"overview":"「～かどうか」的核心意义是：表示“是否……”。构成疑问、不定表达，或传达说话人的态度。","category":"疑问・终助词","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + かどうか","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：表示“是否……”。","提问、确认信息或表示任意／全面范围。","在句末提示新信息、寻求共鸣或加强语气。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["嵌入句不使用句末疑问语调；有疑问词时通常不用「かどうか」。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","句末助词高度依赖语气和人际关系，中文译词不能固定。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["名词、な形容词现在肯定一般不加「だ」再接「かどうか」。","疑问词与「か／も／でも」组合后，句子不一定仍是疑问句。"]},"gx-n4-3dbp00":{"overview":"「间接疑问句」的核心意义是：把疑问句嵌入另一个句子中。构成疑问、不定表达，或传达说话人的态度。","category":"疑问・终助词","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"疑问词 + 普通形 + か","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：把疑问句嵌入另一个句子中。","提问、确认信息或表示任意／全面范围。","在句末提示新信息、寻求共鸣或加强语气。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["嵌入句不使用句末疑问语调；有疑问词时通常不用「かどうか」。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","句末助词高度依赖语气和人际关系，中文译词不能固定。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["名词、な形容词现在肯定一般不加「だ」再接「かどうか」。","疑问词与「か／も／でも」组合后，句子不一定仍是疑问句。"]},"gx-n4-jxbjxd":{"overview":"「～しか～ない」的核心意义是：表示限定：“只有……”，必须搭配否定。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + しか + 否定","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示限定：“只有……”，必须搭配否定。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["名词限定「Nしか〜ない」必须与否定呼应；动词「V辞书＋しかない」表示别无选择。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不要与单纯限定且可接肯定的「だけ」混淆。","强调句型常带说话人评价，正式度也各不相同。"]},"gx-n4-1j3qgna":{"overview":"「～だけ」的核心意义是：表示单纯限定：“只、仅仅”。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N／普通形 + だけ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示单纯限定：“只、仅仅”。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可接肯定或否定，表示中性的范围限定；不自带无奈语气。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「できるだけ」是“尽可能”的固定表达。","强调句型常带说话人评价，正式度也各不相同。"]},"gx-n4-755gug":{"overview":"「～について」的核心意义是：表示主题：“关于……”。引出讨论、评价、态度或动作所针对的主题和对象。","category":"主题・对象","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + について","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示主题：“关于……”。","说明关于什么进行调查、说明或讨论。","指出态度、作用或对比所面向的对象。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["修饰名词时用「についてのN／に関するN」；「に関して」更正式。","表示主题的形式与表示动作对象、对比对象的形式不能完全互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["多用于主题，不一定能替代具体动作对象的格助词。","修饰名词时常需改用「〜に関する／〜についての」等连体形式。"]},"gx-n4-8v56lr":{"overview":"「～によって」的核心意义是：表示根据、手段、原因或因人而异等。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + によって","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示根据、手段、原因或因人而异等。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示手段、原因、被动施事者、差异或依据，必须看谓语。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["被动句中正式施事者常用「によって」。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"gx-n4-1f1rcm5":{"overview":"「～間／～間に」的核心意义是：「間」表示整个期间持续；「間に」表示期间内发生某事。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + 間／間に","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：「間」表示整个期间持续；「間に」表示期间内发生某事。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「間」强调整个期间持续；「間に」强调期间内某时发生一次或若干次。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前接持续状态常用「ている／Nの」。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"gx-n4-zsnqhb":{"overview":"「～までに」的核心意义是：表示截止期限：“在……之前完成”。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"时间 + までに","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示截止期限：“在……之前完成”。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示截止点前完成，动作可早于该时点。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与持续到某时的「まで」区分。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"gx-n4-1gzsgxr":{"overview":"「～たばかり」的核心意义是：表示说话人主观认为“刚刚……”。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vた + ばかり","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。"],"usages":["用于表达：表示说话人主观认为“刚刚……”。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["“刚刚”是说话人的主观判断，不要求客观时间极短。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与真正紧接发生的「たところ」不同。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"gx-n4-19imq25":{"overview":"「～ところだ」的核心意义是：表示动作正要进行、正在进行或刚结束。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书／Vている／Vた + ところだ","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。","前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。","前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示动作正要进行、正在进行或刚结束。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["辞书形／ている形／た形分别表示正要、正在、刚做完。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不能只记作“地方”；这是表示动作阶段的形式名词。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"gx-n4-1lvpd1l":{"overview":"「～ような／～ように」的核心意义是：表示比喻或举例：“像……一样的／像……一样地”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Nの + ようなN／ようにV","formationNotes":["名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示比喻或举例：“像……一样的／像……一样地”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「ようだ」偏中性，「みたいだ」更口语；名词接续分别常为「Nのようだ／Nみたいだ」。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["修饰名词用「ような」，修饰动词或形容词用「ように」。","确信度、证据来源和语体决定应选哪一种形式。"]},"gx-n4-1lax0rv":{"overview":"「～そうな／～そうに」的核心意义是：样态「そうだ」修饰名词或动词。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"～そうなN／～そうにV","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：样态「そうだ」修饰名词或动词。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["い形容词去「い」，な形容词直接接；「いい」通常为「よさそうだ」，否定形常用「〜そうにない／〜なさそうだ」。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["样态形式没有过去观察的普通形接续，重点是眼前迹象。","确信度、证据来源和语体决定应选哪一种形式。"]},"gx-n4-1tijt7r":{"overview":"「～ため（原因）」的核心意义是：较正式地表示原因、理由。补充背景、原因、依据或说话人的解释。","category":"说明・理由","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Nの／普通形 + ため","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：较正式地表示原因、理由。","解释为什么出现某结果。","在会话、说明文或正式通知中交代理由。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["较正式、客观地表示原因；名词接「Nのため」，后项常是不利或中性结果。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","原因句型可能带客观说明、感谢、责怪或辩解等不同语气。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["目的「ために」与原因「ため」需按前后逻辑区分。","后项能否接命令、请求或意志表达，取决于具体形式。"]},"gx-n4-10l2dlb":{"overview":"「～ほど～ない」的核心意义是：表示“A没有B那么……”。设定比较基准，或说明数量、性质和程度。","category":"比较・程度","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Aは Bほど + 否定","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示“A没有B那么……”。","比较两个对象或范围内的高低。","用极端例子、数量或结果说明程度。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["以B为比较基准，表示A的程度不及B。","比较对象、基准和评价对象的助词不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["基本结构是「AはBほど〜ない」，不要漏掉否定。","否定比较与最高级结构有固定语序。"]},"gx-n4-tf0317":{"overview":"「～くらい／～ぐらい」的核心意义是：表示大约的数量、时间或程度。设定比较基准，或说明数量、性质和程度。","category":"比较・程度","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"数量 + くらい／ぐらい","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示大约的数量、时间或程度。","比较两个对象或范围内的高低。","用极端例子、数量或结果说明程度。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示大约数量，也可表示程度或举出最低限度；「くらい／ぐらい」意义基本相同。","比较对象、基准和评价对象的助词不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["数量后通常不表示精确值。","否定比较与最高级结构有固定语序。"]},"gx-n4-163mrsv":{"overview":"「～ずつ」的核心意义是：表示每次等量分配：“每……；一点一点”。说明数量在句中的位置、分配方式或递增单位。","category":"数量・分配","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"数量 + ずつ","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示每次等量分配：“每……；一点一点”。","表达一次做多少、每份多少或逐步变化。","把数量词作为副词性成分修饰动作。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["接数量词表示等量分配或一点一点地变化。","数量词通常不直接取代格助词，应放在合适的句法位置。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不能直接接普通名词表示“每个”；应搭配数量单位。","「ずつ」既可表示等量分配，也可表示一点一点的变化。"]},"gx-n4-12hozl3":{"overview":"「～とか～とか」的核心意义是：口语中列举若干例子。并列理由、动作或例子，并说明列举是否完整。","category":"并列・列举","register":{"label":"偏口语","note":"适合会话或带个人态度的表达；正式场合需选择更中性的形式。"},"formation":"N／普通形 + とか","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：口语中列举若干例子。","列出多个同类事实、理由或动作。","用代表性项目暗示还有其他内容。","适合会话或带个人态度的表达；正式场合需选择更中性的形式。"],"cautions":["口语中列举代表性名词、动作或说法，暗示还有其他项目。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「と」偏完整列举，「や／など／とか」多为不完全列举。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["正式列举宜用「や／など」或更完整表达。","列举句型通常要求前后项目在语法形式和评价方向上协调。"]},"g-n3-001":{"overview":"「～ために（目的）」的核心意义是：表示明确、主动的目的：“为了……”。说明行动的目的、目标或为了达到某状态而采取的措施。","category":"目的","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书/Nの + ために","formationNotes":["前接动词使用辞书形，不接「ます」。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示明确、主动的目的：“为了……”。","说明移动或行动是为了做什么。","表达努力达到能力、状态或避免某结果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["前项多为有意志、可控制的目标，前后主语原则上相同。","「ために」与「ように」对意志性、主语和可控制性有不同限制。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["能力、状态或否定目标常用「ように」。","目的句前后主语是否相同，需要按具体句型确认。"]},"g-n3-002":{"overview":"「～ように（目的）」的核心意义是：多用于能力、状态、否定等不可直接控制的目标。说明行动的目的、目标或为了达到某状态而采取的措施。","category":"目的","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V可能/ない + ように","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：多用于能力、状态、否定等不可直接控制的目标。","说明移动或行动是为了做什么。","表达努力达到能力、状态或避免某结果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["常接可能形、ない形或非意志状态，表示为了使某状态实现。","「ために」与「ように」对意志性、主语和可控制性有不同限制。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项可为努力、准备、提醒等；前后主语可以不同。","目的句前后主语是否相同，需要按具体句型确认。"]},"g-n3-003":{"overview":"「～ようとします」的核心意义是：表示正准备做、试图做。说明试做、事先准备、彻底完成或即将采取行动。","category":"尝试・准备・完成","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"V意向形 + とする","formationNotes":["前接意向形，如「行こう／食べよう／しよう／来よう」。"],"usages":["用于表达：表示正准备做、试图做。","尝试以前没有做过的行为。","为以后做准备，或说明动作完成后的语气。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["意向形＋とする可表示尝试、正要发生；否定「ようとしない」常表示不肯尝试。","这些补助动词仍保留各自语义，不能只按一个中文词机械翻译。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["动作主语需具有相应意志；自然现象用时表示即将发生。","会话中常出现缩约形式，但写作中应使用完整形式。"]},"g-n3-004":{"overview":"「～ところです」的核心意义是：表示正要做、正在做、刚做完。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"V辞书/ている/た + ところ","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示正要做、正在做、刚做完。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["辞书形／ている形／た形分别表示正要、正在、刚做完。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不能只记作“地方”；这是表示动作阶段的形式名词。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n3-005":{"overview":"「～たばかり」的核心意义是：说话人主观觉得“刚刚做完”。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vた + ばかり","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。"],"usages":["用于表达：说话人主观觉得“刚刚做完”。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["“刚刚”是说话人的主观判断，不要求客观时间极短。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与真正紧接发生的「たところ」不同。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n3-006":{"overview":"「～うちに」的核心意义是：趁某状态还持续时做；也可表示过程中自然变化。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V/形容词/Nの + うちに","formationNotes":["名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：趁某状态还持续时做；也可表示过程中自然变化。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示趁状态未改变采取行动，或在过程中自然发生变化。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前项状态一旦结束，机会通常消失。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n3-007":{"overview":"「～間／～間に」的核心意义是：前者表示整个期间持续，后者表示期间内发生某事。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vている/Nの + 間（に）","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：前者表示整个期间持续，后者表示期间内发生某事。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「間」强调整个期间持续；「間に」强调期间内某时发生一次或若干次。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前接持续状态常用「ている／Nの」。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n3-008":{"overview":"「～最中に」的核心意义是：表示“正值……的时候”，强调动作进行到最关键处。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vている/Nの + 最中に","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示“正值……的时候”，强调动作进行到最关键处。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["强调正在进行最关键阶段，后项常为插入、打断事件。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不适合表示宽泛期间。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n3-009":{"overview":"「～たびに」的核心意义是：每当……就……。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书/Nの + たびに","formationNotes":["前接动词使用辞书形，不接「ます」。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：每当……就……。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示每次前项发生，后项都规律性重复。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["一次性事件不能使用。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n3-010":{"overview":"「～たとたん（に）」的核心意义是：刚一……就……，后项常是突发、意外事件。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vた + とたん","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。"],"usages":["用于表达：刚一……就……，后项常是突发、意外事件。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["后项多为非意志、意外或突然发生的结果。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["通常不接说话人计划好的动作、命令或请求。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n3-011":{"overview":"「～て以来」的核心意义是：自从某动作发生以来，状态一直持续。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + 以来","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：自从某动作发生以来，状态一直持续。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["起点动作发生后，某状态一直持续到现在或基准时。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["只表示普通先后时用「てから」。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n3-012":{"overview":"「～につれて」的核心意义是：随着一方变化，另一方也逐渐变化。表示两个动作并行、顺便进行，或两个变化相互伴随。","category":"同步・伴随","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N/V辞书 + につれて","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：随着一方变化，另一方也逐渐变化。","说明同一主体同时做两件事。","表达随一个变化发生另一个变化，或利用机会顺便做事。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["两项变化通常同向、逐渐或相伴发生；后项多为非意志变化。","同时动作常要求主语一致；长期副业与一次性顺便行为要区分。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["单纯同时发生不一定适用。","正式书面形式与日常「ながら」在语域上不同。"]},"g-n3-013":{"overview":"「～にしたがって」的核心意义是：随着……；也可表示按照规则、指示。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N/V辞书 + にしたがって","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：随着……；也可表示按照规则、指示。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示随变化而变化，也可表示遵照指示；两种意义需由名词性质判断。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["表示“按照”时多接规则、指示、方针。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"g-n3-014":{"overview":"「～ば～ほど」的核心意义是：越……越……。设定比较基准，或说明数量、性质和程度。","category":"比较・程度","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"ば形 + 辞书形 + ほど","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：越……越……。","比较两个对象或范围内的高低。","用极端例子、数量或结果说明程度。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["同一性质随条件增强而增强；常见形式「VばV辞书形ほど」。","比较对象、基准和评价对象的助词不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["な形容词常用「なら〜なほど」。","否定比较与最高级结构有固定语序。"]},"g-n3-015":{"overview":"「～ほど～ない」的核心意义是：表示比较：“没有……那么……”。设定比较基准，或说明数量、性质和程度。","category":"比较・程度","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + ほど + 否定","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示比较：“没有……那么……”。","比较两个对象或范围内的高低。","用极端例子、数量或结果说明程度。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["以B为比较基准，表示A的程度不及B。","比较对象、基准和评价对象的助词不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["基本结构是「AはBほど〜ない」，不要漏掉否定。","否定比较与最高级结构有固定语序。"]},"g-n3-016":{"overview":"「～しかない」的核心意义是：表示别无选择：“只能……”。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书 + しかない","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：表示别无选择：“只能……”。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["名词限定「Nしか〜ない」必须与否定呼应；动词「V辞书＋しかない」表示别无选择。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不要与单纯限定且可接肯定的「だけ」混淆。","强调句型常带说话人评价，正式度也各不相同。"]},"g-n3-017":{"overview":"「～わけです」的核心意义是：根据前文逻辑得出当然结论：“难怪、也就是说……”。根据事实、常识或前文逻辑得出结论，或否定某种推论。","category":"逻辑・结论","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"普通形 + わけだ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：根据前文逻辑得出当然结论：“难怪、也就是说……”。","说明理所当然的结果、预期或不可能性。","修正听者可能作出的过度概括。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["表示由前文自然推出的结论，也可用于换言解释；不是单纯“理由”。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「わけだ／わけではない／わけがない」意义完全不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常译为“难怪／也就是说／当然”。","「はず」表示有依据的预期，不等于道德上的“应该”。"]},"g-n3-018":{"overview":"「～わけではありません」的核心意义是：部分否定：“并不是说……”。根据事实、常识或前文逻辑得出结论，或否定某种推论。","category":"逻辑・结论","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"普通形 + わけではない","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：部分否定：“并不是说……”。","说明理所当然的结果、预期或不可能性。","修正听者可能作出的过度概括。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["否定的是对前文的整体概括，属于部分否定。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「わけだ／わけではない／わけがない」意义完全不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与强烈不可能「わけがない」不同。","「はず」表示有依据的预期，不等于道德上的“应该”。"]},"g-n3-019":{"overview":"「～わけがありません」的核心意义是：强烈否定可能性：“不可能……”。根据事实、常识或前文逻辑得出结论，或否定某种推论。","category":"逻辑・结论","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"普通形 + わけがない","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：强烈否定可能性：“不可能……”。","说明理所当然的结果、预期或不可能性。","修正听者可能作出的过度概括。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["根据常识或逻辑强烈断定不可能，语气强。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「わけだ／わけではない／わけがない」意义完全不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不要与部分否定「わけではない」混淆。","「はず」表示有依据的预期，不等于道德上的“应该”。"]},"g-n3-020":{"overview":"「～はずです」的核心意义是：基于理由判断“按理应该……”。根据事实、常识或前文逻辑得出结论，或否定某种推论。","category":"逻辑・结论","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"普通形 + はずだ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：基于理由判断“按理应该……”。","说明理所当然的结果、预期或不可能性。","修正听者可能作出的过度概括。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["「はずだ」是有依据的预期；「はずがない」是按依据判断不可能。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「わけだ／わけではない／わけがない」意义完全不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不要把「はずだ」当作给他人的道德建议。","「はず」表示有依据的预期，不等于道德上的“应该”。"]},"g-n3-021":{"overview":"「～はずがありません」的核心意义是：表示按常理“不可能……”。根据事实、常识或前文逻辑得出结论，或否定某种推论。","category":"逻辑・结论","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"普通形 + はずがない","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：表示按常理“不可能……”。","说明理所当然的结果、预期或不可能性。","修正听者可能作出的过度概括。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["「はずだ」是有依据的预期；「はずがない」是按依据判断不可能。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「わけだ／わけではない／わけがない」意义完全不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不要把「はずだ」当作给他人的道德建议。","「はず」表示有依据的预期，不等于道德上的“应该”。"]},"g-n3-022":{"overview":"「～ことはありません」的核心意义是：表示没有必要做：“不必……”。表达没有必要、不能按意愿行事或不得不采取某行动。","category":"必要・无奈","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"V辞书 + ことはない","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：表示没有必要做：“不必……”。","说明现实、责任或社会常识造成的限制。","表达不做不能了结、只能接受或没有必要做。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["表示没有必要做某事，常用于安慰或建议。","要区分客观能力不足、社会立场限制与外部强迫。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与经历否定「Vたことがない」不同。","否定成分多时应按整句理解，不能逐词相消。"]},"g-n3-023":{"overview":"「～べきです」的核心意义是：表示从道理、常识看“应该……”。基于常识、责任、既定事实或立场提出应有行动。","category":"建议・责任","register":{"label":"礼貌体常用","note":"形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"},"formation":"V辞书 + べき","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：表示从道理、常识看“应该……”。","给出建议、忠告或道义判断。","表示既然前项成立，就应承担相应后果。","形式本身适合礼貌会话；仍需根据对象调整请求或断定的强度。"],"cautions":["基于常识、道德或职责提出强建议；「する」可为「するべき／すべき」。","语气通常比单纯建议强；对听话人使用时需注意礼貌。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["直接评价他人时语气较强。","客观义务、个人意见和社会责任应分别选择合适形式。"]},"g-n3-024":{"overview":"「～てほしい」的核心意义是：希望别人做某事。用于请求、邀请、提议或向对方征求行动意见。","category":"请求・邀请","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + ほしい","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：希望别人做某事。","礼貌地请对方做或不做某事。","邀请共同参与，或主动提出帮助。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表达说话人希望别人做某事；动作执行者常用「に」。","礼貌程度取决于句型、句尾和人际关系；对上级需避免命令感。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["直接对上级说可能较强，可改用请求形式。","否定请求、提议和许可的形式相似，必须看完整句型。"]},"g-n3-025":{"overview":"「～さえ」的核心意义是：表示极端例子：“连……都……”；也可表示只要。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + さえ","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示极端例子：“连……都……”；也可表示只要。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可举极端例子表示“连……都”，也可构成「〜さえ〜ば＝只要”。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["格助词有时保留在前：にさえ、でさえ。","强调句型常带说话人评价，正式度也各不相同。"]},"g-n3-026":{"overview":"「～こそ」的核心意义是：强调前项：“正是……”。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + こそ","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：强调前项：“正是……”。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["强烈聚焦前项，常用于纠正或强调“正是”。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「こちらこそ」是回应感谢／道歉的固定表达。","强调句型常带说话人评价，正式度也各不相同。"]},"g-n3-027":{"overview":"「～なんか／なんて」的核心意义是：口语中举例、轻视或强调惊讶。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"偏口语","note":"适合会话或带个人态度的表达；正式场合需选择更中性的形式。"},"formation":"N/普通形 + なんか/なんて","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：口语中举例、轻视或强调惊讶。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","适合会话或带个人态度的表达；正式场合需选择更中性的形式。"],"cautions":["可表示举例、轻视、自谦或惊讶，语气取决于上下文。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["正式场合慎用，尤其用于他人时可能失礼。","强调句型常带说话人评价，正式度也各不相同。"]},"g-n3-028":{"overview":"「～について」的核心意义是：表示主题：“关于……”。引出讨论、评价、态度或动作所针对的主题和对象。","category":"主题・对象","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + について","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示主题：“关于……”。","说明关于什么进行调查、说明或讨论。","指出态度、作用或对比所面向的对象。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["修饰名词时用「についてのN／に関するN」；「に関して」更正式。","表示主题的形式与表示动作对象、对比对象的形式不能完全互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["多用于主题，不一定能替代具体动作对象的格助词。","修饰名词时常需改用「〜に関する／〜についての」等连体形式。"]},"g-n3-029":{"overview":"「～に対して」的核心意义是：表示对象、对比：“对于…… / 与……相对”。引出讨论、评价、态度或动作所针对的主题和对象。","category":"主题・对象","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + に対して","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示对象、对比：“对于…… / 与……相对”。","说明关于什么进行调查、说明或讨论。","指出态度、作用或对比所面向的对象。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可标记动作／态度对象，也可连接两个对照事实。","表示主题的形式与表示动作对象、对比对象的形式不能完全互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["修饰名词用「に対するN」。","修饰名词时常需改用「〜に関する／〜についての」等连体形式。"]},"g-n3-030":{"overview":"「～によって」的核心意义是：表示原因、手段、主体、差异等。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + によって","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示原因、手段、主体、差异等。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示手段、原因、被动施事者、差异或依据，必须看谓语。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["被动句中正式施事者常用「によって」。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"g-n3-031":{"overview":"「～おかげで」的核心意义是：表示因某原因得到好结果：“多亏……”。补充背景、原因、依据或说话人的解释。","category":"说明・理由","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Nの/普通形 + おかげで","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示因某原因得到好结果：“多亏……”。","解释为什么出现某结果。","在会话、说明文或正式通知中交代理由。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["通常用于好结果并带感谢；讽刺语境可反用。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","原因句型可能带客观说明、感谢、责怪或辩解等不同语气。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["坏结果通常用「せいで」。","后项能否接命令、请求或意志表达，取决于具体形式。"]},"g-n3-032":{"overview":"「～せいで」的核心意义是：表示因某原因导致坏结果：“都怪……”。补充背景、原因、依据或说话人的解释。","category":"说明・理由","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Nの/普通形 + せいで","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示因某原因导致坏结果：“都怪……”。","解释为什么出现某结果。","在会话、说明文或正式通知中交代理由。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["把坏结果归因于前项，常含责怪或遗憾。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","原因句型可能带客观说明、感谢、责怪或辩解等不同语气。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["中性客观原因宜用「ため／ので」。","后项能否接命令、请求或意志表达，取决于具体形式。"]},"g-n3-033":{"overview":"「～代わりに」的核心意义是：表示代替、交换或补偿：“代替…… / 作为交换……”。突出原因、经过及最终结果，常附带说话人的评价。","category":"原因・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Nの/V辞书 + 代わりに","formationNotes":["前接动词使用辞书形，不接「ます」。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示代替、交换或补偿：“代替…… / 作为交换……”。","说明由于某一原因而产生结果。","总结长时间、反复过程后的结局。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示替代某人／事，也可表示交换条件或相反补偿。","「ばかりに／あげく」多倾向负面结果，而「末に」可好可坏。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前后两项常存在代替或得失平衡关系。","原因与结果之间应具有自然、可理解的联系。"]},"gx-n3-phtdh1":{"overview":"「～ようとする」的核心意义是：表示尝试做某事，或某事即将发生。说明试做、事先准备、彻底完成或即将采取行动。","category":"尝试・准备・完成","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"意向形 + とする","formationNotes":["前接意向形，如「行こう／食べよう／しよう／来よう」。"],"usages":["用于表达：表示尝试做某事，或某事即将发生。","尝试以前没有做过的行为。","为以后做准备，或说明动作完成后的语气。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["意向形＋とする可表示尝试、正要发生；否定「ようとしない」常表示不肯尝试。","这些补助动词仍保留各自语义，不能只按一个中文词机械翻译。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["动作主语需具有相应意志；自然现象用时表示即将发生。","会话中常出现缩约形式，但写作中应使用完整形式。"]},"gx-n3-bz68ir":{"overview":"「～ことになっている」的核心意义是：表示规则、约定或既定安排：“规定是……”。说明个人决定、外部安排、规则或持续努力形成的习惯。","category":"习惯・决定・规则","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书／Vない + ことになっている","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示规则、约定或既定安排：“规定是……”。","表达自己决定做什么。","说明制度安排、既定规则或日常坚持。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示社会规则、约定或已确定安排持续有效。","先正确变出ない形，不能从辞书形机械删除词尾。","「ことにする」与「ことになる」的决定主体不同；「ようにする」强调努力。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与个人习惯「ことにしている」区分。","进行体形式常表示决定或规则持续有效。"]},"gx-n3-l6dc1b":{"overview":"「～ことにしている」的核心意义是：表示自己持续遵守的习惯或决定。说明个人决定、外部安排、规则或持续努力形成的习惯。","category":"习惯・决定・规则","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书／Vない + ことにしている","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示自己持续遵守的习惯或决定。","表达自己决定做什么。","说明制度安排、既定规则或日常坚持。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示主语自己决定并持续遵守的习惯。","先正确变出ない形，不能从辞书形机械删除词尾。","「ことにする」与「ことになる」的决定主体不同；「ようにする」强调努力。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["单次当场决定用「ことにする」。","进行体形式常表示决定或规则持续有效。"]},"gx-n3-q0nb0n":{"overview":"「～間に」的核心意义是：在某一持续期间内发生一次或若干次事件。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + 間に","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：在某一持续期间内发生一次或若干次事件。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「間」强调整个期间持续；「間に」强调期间内某时发生一次或若干次。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前接持续状态常用「ている／Nの」。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"gx-n3-17kpi7c":{"overview":"「～ところで」的核心意义是：转换话题：“话说回来／对了”。在会话或文章中结束当前话题并引出新话题。","category":"话题转换","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"句子 + ところで","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：转换话题：“话说回来／对了”。","补充想到的新问题。","把讨论方向转到另一件事。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["作为接续词转换话题，与动词た形后的让步「たところで」完全不同。","这里的「ところで」是接续词，不等同于「Vたところで」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常用于突然想到相关问题或另起话题。","与前句通常没有因果关系。"]},"gx-n3-xb47jd":{"overview":"「～ところが」的核心意义是：表示结果出乎预料：“然而／可是”。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"文 + ところが","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示结果出乎预料：“然而／可是”。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["连接实际结果与预期相反，前项常包含尝试、预想或计划。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不是单纯中性的「しかし」，常突出意外发现。","要区分既成事实的逆接与假设条件的让步。"]},"gx-n3-bjl4sw":{"overview":"「～とおりに」的核心意义是：按照……那样做。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书／Vた／Nの + とおりに","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。","前接动词使用辞书形，不接「ます」。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：按照……那样做。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示按照看到、听到、说明或预定的内容行动。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["名词接「Nのとおりに」，也常说「Nどおりに」。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"gx-n3-23xuvt":{"overview":"「～によると」的核心意义是：表示信息来源：“据……”。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + によると","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示信息来源：“据……”。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["只标记消息来源，句末常与「そうだ／ということだ」等传闻形式呼应。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不能用来表示行动手段。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"gx-n3-rmmp2r":{"overview":"「～わけだ」的核心意义是：基于前文得出当然结论：“难怪／也就是说”。根据事实、常识或前文逻辑得出结论，或否定某种推论。","category":"逻辑・结论","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + わけだ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：基于前文得出当然结论：“难怪／也就是说”。","说明理所当然的结果、预期或不可能性。","修正听者可能作出的过度概括。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示由前文自然推出的结论，也可用于换言解释；不是单纯“理由”。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「わけだ／わけではない／わけがない」意义完全不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常译为“难怪／也就是说／当然”。","「はず」表示有依据的预期，不等于道德上的“应该”。"]},"gx-n3-1vibpd5":{"overview":"「～わけではない」的核心意义是：部分否定：“并不是说……”。根据事实、常识或前文逻辑得出结论，或否定某种推论。","category":"逻辑・结论","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + わけではない","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：部分否定：“并不是说……”。","说明理所当然的结果、预期或不可能性。","修正听者可能作出的过度概括。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["否定的是对前文的整体概括，属于部分否定。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「わけだ／わけではない／わけがない」意义完全不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与强烈不可能「わけがない」不同。","「はず」表示有依据的预期，不等于道德上的“应该”。"]},"gx-n3-yq2i8p":{"overview":"「～わけがない」的核心意义是：强烈否定可能：“不可能……”。根据事实、常识或前文逻辑得出结论，或否定某种推论。","category":"逻辑・结论","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + わけがない","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：强烈否定可能：“不可能……”。","说明理所当然的结果、预期或不可能性。","修正听者可能作出的过度概括。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["根据常识或逻辑强烈断定不可能，语气强。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「わけだ／わけではない／わけがない」意义完全不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不要与部分否定「わけではない」混淆。","「はず」表示有依据的预期，不等于道德上的“应该”。"]},"gx-n3-aj4pho":{"overview":"「～わけにはいかない」的核心意义是：因社会、责任等原因“不能做／不得不做”。表达没有必要、不能按意愿行事或不得不采取某行动。","category":"必要・无奈","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书／Vない + わけにはいかない","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：因社会、责任等原因“不能做／不得不做”。","说明现实、责任或社会常识造成的限制。","表达不做不能了结、只能接受或没有必要做。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["前者表示因责任、立场不能做；后者双重否定表示不能不做。","先正确变出ない形，不能从辞书形机械删除词尾。","要区分客观能力不足、社会立场限制与外部强迫。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不是能力上的“做不到”，而是社会或心理限制。","否定成分多时应按整句理解，不能逐词相消。"]},"gx-n3-15dnfdc":{"overview":"「～はずだ」的核心意义是：根据依据确信“应该……”。根据事实、常识或前文逻辑得出结论，或否定某种推论。","category":"逻辑・结论","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + はずだ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：根据依据确信“应该……”。","说明理所当然的结果、预期或不可能性。","修正听者可能作出的过度概括。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「はずだ」是有依据的预期；「はずがない」是按依据判断不可能。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「わけだ／わけではない／わけがない」意义完全不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不要把「はずだ」当作给他人的道德建议。","「はず」表示有依据的预期，不等于道德上的“应该”。"]},"gx-n3-btvc56":{"overview":"「～はずがない」的核心意义是：根据常识判断“不可能……”。根据事实、常识或前文逻辑得出结论，或否定某种推论。","category":"逻辑・结论","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + はずがない","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：根据常识判断“不可能……”。","说明理所当然的结果、预期或不可能性。","修正听者可能作出的过度概括。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「はずだ」是有依据的预期；「はずがない」是按依据判断不可能。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「わけだ／わけではない／わけがない」意义完全不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不要把「はずだ」当作给他人的道德建议。","「はず」表示有依据的预期，不等于道德上的“应该”。"]},"gx-n3-19j8r2l":{"overview":"「～べきだ」的核心意义是：从常识、道德或立场提出“应该……”。基于常识、责任、既定事实或立场提出应有行动。","category":"建议・责任","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书 + べきだ（する→すべき／するべき）","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：从常识、道德或立场提出“应该……”。","给出建议、忠告或道义判断。","表示既然前项成立，就应承担相应后果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["基于常识、道德或职责提出强建议；「する」可为「するべき／すべき」。","语气通常比单纯建议强；对听话人使用时需注意礼貌。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["直接评价他人时语气较强。","客观义务、个人意见和社会责任应分别选择合适形式。"]},"gx-n3-14kft35":{"overview":"「～ことはない」的核心意义是：表示“不必……／没必要……”。表达没有必要、不能按意愿行事或不得不采取某行动。","category":"必要・无奈","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书 + ことはない","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：表示“不必……／没必要……”。","说明现实、责任或社会常识造成的限制。","表达不做不能了结、只能接受或没有必要做。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示没有必要做某事，常用于安慰或建议。","要区分客观能力不足、社会立场限制与外部强迫。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与经历否定「Vたことがない」不同。","否定成分多时应按整句理解，不能逐词相消。"]},"gx-n3-ca7u6n":{"overview":"「～ものだ」的核心意义是：表示常识、感慨、回忆或本来如此。表达过去经历、一般常识、感慨或回忆性的习惯。","category":"经历・惯常","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + ものだ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：表示常识、感慨、回忆或本来如此。","说明曾经做过某事。","概括通常规律，或回想过去经常发生的事。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示一般常识／本性、感慨、劝告或过去经常做；需结合时态和语调。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「Vたことがある」是经历；「V辞书形ことがある」表示有时会发生。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「Vたものだ」常用于怀旧回忆。","「ものだ」的常识、感慨与回忆用法应靠时态和语境区分。"]},"gx-n3-9hkb10":{"overview":"「～ような気がする」的核心意义是：委婉表达不确定感觉：“总觉得……”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + ような気がする","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：委婉表达不确定感觉：“总觉得……”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示没有充分把握的主观感觉，比直接断言更委婉。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前接普通形；名词、な形容词接续需注意「の／な」。","确信度、证据来源和语体决定应选哪一种形式。"]},"gx-n3-1swip23":{"overview":"「～らしい」的核心意义是：根据传闻判断“听说／似乎”；也可表示典型特征。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + らしい／N + らしい","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：根据传闻判断“听说／似乎”；也可表示典型特征。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示根据传闻推测，也可表示具有典型特征；「男らしい」等不一定是传闻。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["根据眼前外观通常不用传闻意义的「らしい」。","确信度、证据来源和语体决定应选哪一种形式。"]},"gx-n3-1lhydvj":{"overview":"「～っぽい」的核心意义是：表示容易有某倾向或“很有……的感觉”。描述容易出现的倾向、程度过量或持续发展的趋势。","category":"趋势・倾向","register":{"label":"偏口语","note":"适合会话或带个人态度的表达；正式场合需选择更中性的形式。"},"formation":"N／Vます去ます／い形词干 + っぽい","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示容易有某倾向或“很有……的感觉”。","说明经常发生、略有迹象或不断加剧。","评价行为或状态是否容易、过度或偏向某一方向。","适合会话或带个人态度的表达；正式场合需选择更中性的形式。"],"cautions":["可表示容易出现某倾向、含有较多某成分或给人某种印象，口语性较强。","不要保留「ます」再接句型。","「がち／気味／っぽい」的负面程度和适用词类不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常带负面或随意评价；前接形式随词类变化。","趋势表达通常不用于一次性的偶然事件。"]},"gx-n3-1gpyfky":{"overview":"「～がち」的核心意义是：表示容易出现不希望的倾向：“往往……”。描述容易出现的倾向、程度过量或持续发展的趋势。","category":"趋势・倾向","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N／Vます去ます + がち","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示容易出现不希望的倾向：“往往……”。","说明经常发生、略有迹象或不断加剧。","评价行为或状态是否容易、过度或偏向某一方向。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示某种不理想行为或状态容易反复出现。","不要保留「ます」再接句型。","「がち／気味／っぽい」的负面程度和适用词类不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["多接动词词干或名词，不用于一次性事件。","趋势表达通常不用于一次性的偶然事件。"]},"gx-n3-qspxc3":{"overview":"「～気味」的核心意义是：表示“稍微有点……倾向/状态”。描述容易出现的倾向、程度过量或持续发展的趋势。","category":"趋势・倾向","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N／Vます去ます + 気味","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示“稍微有点……倾向/状态”。","说明经常发生、略有迹象或不断加剧。","评价行为或状态是否容易、过度或偏向某一方向。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示程度轻微、略有某种状态，常用于身体或负面倾向。","不要保留「ます」再接句型。","「がち／気味／っぽい」的负面程度和适用词类不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["比「がち」更侧重当前感觉，而非反复频率。","趋势表达通常不用于一次性的偶然事件。"]},"gx-n3-1qdli6y":{"overview":"「～一方だ」的核心意义是：表示某种趋势不断单向发展。描述容易出现的倾向、程度过量或持续发展的趋势。","category":"趋势・倾向","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书 + 一方だ","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：表示某种趋势不断单向发展。","说明经常发生、略有迹象或不断加剧。","评价行为或状态是否容易、过度或偏向某一方向。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示变化持续朝单一方向发展，常用于不受控制的趋势。","「がち／気味／っぽい」的负面程度和适用词类不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不能表示两个方面的「一方で」。","趋势表达通常不用于一次性的偶然事件。"]},"gx-n3-16wej1y":{"overview":"「～つつある」的核心意义是：书面表达：“正在逐渐……”。描述容易出现的倾向、程度过量或持续发展的趋势。","category":"趋势・倾向","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vます去ます + つつある","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。"],"usages":["用于表达：书面表达：“正在逐渐……”。","说明经常发生、略有迹象或不断加剧。","评价行为或状态是否容易、过度或偏向某一方向。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["书面地表示变化正在逐步进行，常用于社会、技术、环境趋势。","不要保留「ます」再接句型。","「がち／気味／っぽい」的负面程度和适用词类不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不用于短暂的眼前动作。","趋势表达通常不用于一次性的偶然事件。"]},"gx-n3-lp6k0f":{"overview":"「～てくる」的核心意义是：表示变化从过去延续到现在，或动作朝说话人方向而来。描述状态、习惯、能力或趋势发生变化，以及人为改变。","category":"变化・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + くる","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：表示变化从过去延续到现在，或动作朝说话人方向而来。","说明从过去到现在或从现在向未来的变化。","表达自然变化、主动改变或动作的开始／持续／结束。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["空间意义分别朝说话人而来／离去；时间意义分别从过去到现在／从现在向未来。","要区分自然变化「なる」与人为改变「する」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["选择取决于叙述基准点，不只是中文“来／去”。","方向补助动词「てくる／ていく」也可表示时间上的变化。"]},"gx-n3-1k4xgac":{"overview":"「～ていく」的核心意义是：表示变化从现在延续到未来，或动作远离说话人。描述状态、习惯、能力或趋势发生变化，以及人为改变。","category":"变化・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + いく","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：表示变化从现在延续到未来，或动作远离说话人。","说明从过去到现在或从现在向未来的变化。","表达自然变化、主动改变或动作的开始／持续／结束。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["空间意义分别朝说话人而来／离去；时间意义分别从过去到现在／从现在向未来。","要区分自然变化「なる」与人为改变「する」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["选择取决于叙述基准点，不只是中文“来／去”。","方向补助动词「てくる／ていく」也可表示时间上的变化。"]},"gx-n3-14hjox7":{"overview":"「～てばかりいる」的核心意义是：表示反复只做某事，常带责备。描述容易出现的倾向、程度过量或持续发展的趋势。","category":"趋势・倾向","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + ばかりいる","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：表示反复只做某事，常带责备。","说明经常发生、略有迹象或不断加剧。","评价行为或状态是否容易、过度或偏向某一方向。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示反复只做某事，常含责备；「ばかり」限定的是行为倾向。","「がち／気味／っぽい」的负面程度和适用词类不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不要与「Vたばかり＝刚做完」混淆。","趋势表达通常不用于一次性的偶然事件。"]},"gx-n3-no11ov":{"overview":"「～ところだった」的核心意义是：表示差一点发生某事：“险些……”。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书 + ところだった","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：表示差一点发生某事：“险些……”。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["常与「もう少しで／危うく」搭配，表示险些发生但实际上未发生。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前接辞书形。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"gx-n3-1a6lbmt":{"overview":"「～ほど」的核心意义是：表示程度：“达到……程度／越是……”。设定比较基准，或说明数量、性质和程度。","category":"比较・程度","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形／N + ほど","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示程度：“达到……程度／越是……”。","比较两个对象或范围内的高低。","用极端例子、数量或结果说明程度。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示达到某种程度、比例关系或“越……越……”中的程度基准。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","比较对象、基准和评价对象的助词不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["具体解释取决于前后结构，不能一律译为“左右”。","否定比较与最高级结构有固定语序。"]},"gx-n3-tyebpd":{"overview":"「～という」的核心意义是：用于定义、命名或引用内容。引用话语、想法和信息，或给事物命名、下定义。","category":"引用・定义","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + というN／普通形 + という","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：用于定义、命名或引用内容。","转述说话内容或表达自己的判断。","说明名称、概念和前文结论。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可命名、定义或用引用内容修饰名词。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","直接引用与间接引用的人称、时态和语气处理不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「というN」中的引用内容可是一整句。","引用助词「と」前通常使用普通形。"]},"gx-n3-1kidszy":{"overview":"「～ということだ」的核心意义是：表示传闻或将前文概括为“也就是说……”。引用话语、想法和信息，或给事物命名、下定义。","category":"引用・定义","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + ということだ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：表示传闻或将前文概括为“也就是说……”。","转述说话内容或表达自己的判断。","说明名称、概念和前文结论。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示传闻，也可把前文概括为逻辑结论“也就是说”。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","直接引用与间接引用的人称、时态和语气处理不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["判断传闻还是总结，要看信息来源和上下文。","引用助词「と」前通常使用普通形。"]},"gx-n3-ru4h12":{"overview":"「～と言っても」的核心意义是：虽说……但实际程度有限或与想象不同。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + と言っても","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：虽说……但实际程度有限或与想象不同。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["承认名称或事实后，限制其实际程度，避免听者过度想象。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与普通逆接相比，重点是修正前项给人的印象。","要区分既成事实的逆接与假设条件的让步。"]},"gx-n3-1sa4vvz":{"overview":"「～にしても」的核心意义是：即使从某种立场看／就算……。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形／N + にしても","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：即使从某种立场看／就算……。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示即使从该立场看，或退一步承认前项，后项仍成立。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["列举两项时可用「AにしてもBにしても」。","要区分既成事实的逆接与假设条件的让步。"]},"gx-n3-1q11lw9":{"overview":"「～に比べて」的核心意义是：表示比较：“与……相比”。设定比较基准，或说明数量、性质和程度。","category":"比较・程度","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + に比べて","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：表示比较：“与……相比”。","比较两个对象或范围内的高低。","用极端例子、数量或结果说明程度。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「に比べて」中性比较；「に引き換え」强调鲜明反差，常带评价。","比较对象、基准和评价对象的助词不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["比较对象需具有可比性。","否定比较与最高级结构有固定语序。"]},"gx-n3-57nghi":{"overview":"「～たまま」的核心意义是：保持动作完成后的状态不变。表示动作的时间、进行阶段、完成状态或结果状态。","category":"时态・体","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vた + まま","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。"],"usages":["用于表达：保持动作完成后的状态不变。","说明动作是否发生、是否完成或是否持续。","把两个动作按先后或状态关系连接起来。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示前项动作完成后的状态保持不变；常含未做后续动作。","日语的过去形也表示完成；「ている」不一定等于中文“正在”。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与「ながら」的同时动作不同。","瞬间动词与持续动词接体表达时，解释可能不同。"]},"gx-n3-1gvqrf2":{"overview":"「～っぱなし」的核心意义是：某动作后状态一直放任不管，常带负面评价。表示动作的时间、进行阶段、完成状态或结果状态。","category":"时态・体","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vます去ます + っぱなし","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。"],"usages":["用于表达：某动作后状态一直放任不管，常带负面评价。","说明动作是否发生、是否完成或是否持续。","把两个动作按先后或状态关系连接起来。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示动作持续，也可表示动作后放任状态，后者常带负面评价。","不要保留「ます」再接句型。","日语的过去形也表示完成；「ている」不一定等于中文“正在”。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["接动词ます形词干。","瞬间动词与持续动词接体表达时，解释可能不同。"]},"gx-n3-iwxdp4":{"overview":"「～ないで」的核心意义是：不做前项而做后项：“没有……就……”。表示不做前项、维持某状态，或动作后状态持续。","category":"状态保持・附带","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vない + で","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：不做前项而做后项：“没有……就……”。","说明保持原样、放任不管或在不做A的情况下做B。","用较书面形式连接伴随状态。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["都可表示不做前项而做后项；「ずに／ことなく」更书面，「する」变为「せずに」。","先正确变出ない形，不能从辞书形机械删除词尾。","「ないで」可表示“不做而……”也可表示请求禁止，需看后项。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「ないで」还可用于禁止请求，需看后项。","「っぱなし」常带放任不管的负面评价。"]},"gx-n3-17hks9q":{"overview":"「～ずに」的核心意义是：「～ないで」的较书面形式。表示不做前项、维持某状态，或动作后状态持续。","category":"状态保持・附带","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vない去ない + ずに（する→せずに）","formationNotes":["先变成ない形，再去掉「ない」连接；「する／来る」按不规则形式处理。"],"usages":["用于表达：「～ないで」的较书面形式。","说明保持原样、放任不管或在不做A的情况下做B。","用较书面形式连接伴随状态。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["都可表示不做前项而做后项；「ずに／ことなく」更书面，「する」变为「せずに」。","先正确变出ない形，不能从辞书形机械删除词尾。","「ないで」可表示“不做而……”也可表示请求禁止，需看后项。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「ないで」还可用于禁止请求，需看后项。","「っぱなし」常带放任不管的负面评价。"]},"gx-n3-10anrcb":{"overview":"「～てもらいたい」的核心意义是：希望别人为自己做某事。用于请求、邀请、提议或向对方征求行动意见。","category":"请求・邀请","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて + もらいたい","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：希望别人为自己做某事。","礼貌地请对方做或不做某事。","邀请共同参与，或主动提出帮助。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["从受益者视角表达希望别人为自己做某事，比直接命令委婉。","礼貌程度取决于句型、句尾和人际关系；对上级需避免命令感。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["对上级常用「ていただきたい」，但仍带明确要求。","否定请求、提议和许可的形式相似，必须看完整句型。"]},"g-n2-001":{"overview":"「～ものの」的核心意义是：虽然……但是……；书面感较强。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"普通形 + ものの","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：虽然……但是……；书面感较强。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["均表示事实性逆接；「にもかかわらず」反差更强且正式。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前项被承认为事实，不是单纯假设。","要区分既成事实的逆接与假设条件的让步。"]},"g-n2-002":{"overview":"「～にもかかわらず」的核心意义是：尽管……却……；表示强烈反差。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形/N + にもかかわらず","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：尽管……却……；表示强烈反差。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["均表示事实性逆接；「にもかかわらず」反差更强且正式。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前项被承认为事实，不是单纯假设。","要区分既成事实的逆接与假设条件的让步。"]},"g-n2-003":{"overview":"「～くせに」的核心意义是：明明……却……；常含责备、不满。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + くせに","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：明明……却……；常含责备、不满。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["带责备、轻蔑或不满，对他人使用时攻击性较强。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["用于自己时可带自嘲。","要区分既成事实的逆接与假设条件的让步。"]},"g-n2-004":{"overview":"「～反面」的核心意义是：一方面……另一方面……，同一事物的两面性。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形/Nである + 反面","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：一方面……另一方面……，同一事物的两面性。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「反面」多说同一事物的两面；「一方で」也可并列不同主体或事实。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前后评价方向通常形成对照。","要区分既成事实的逆接与假设条件的让步。"]},"g-n2-005":{"overview":"「～一方で」的核心意义是：一方面……另一方面……；可比较两个并列事实。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + 一方で","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：一方面……另一方面……；可比较两个并列事实。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「反面」多说同一事物的两面；「一方で」也可并列不同主体或事实。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前后评价方向通常形成对照。","要区分既成事实的逆接与假设条件的让步。"]},"g-n2-006":{"overview":"「～ことから」的核心意义是：由某事实判断原因、由来或依据。补充背景、原因、依据或说话人的解释。","category":"说明・理由","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + ことから","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：由某事实判断原因、由来或依据。","解释为什么出现某结果。","在会话、说明文或正式通知中交代理由。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可由事实推断原因、名称由来或判断依据。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","原因句型可能带客观说明、感谢、责怪或辩解等不同语气。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["强调客观可观察的线索，未必是直接原因。","后项能否接命令、请求或意志表达，取决于具体形式。"]},"g-n2-007":{"overview":"「～ことだから」的核心意义是：由于某人一贯的性格/特点，推测其行为。补充背景、原因、依据或说话人的解释。","category":"说明・理由","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Nの + ことだから","formationNotes":["名词后先加「の」再连接。"],"usages":["用于表达：由于某人一贯的性格/特点，推测其行为。","解释为什么出现某结果。","在会话、说明文或正式通知中交代理由。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["以前项人物一贯性格／特点为依据推测其行为。","原因句型可能带客观说明、感谢、责怪或辩解等不同语气。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前接多为人物名词＋の，不用于一般事物原因。","后项能否接命令、请求或意志表达，取决于具体形式。"]},"g-n2-008":{"overview":"「～以上（は）」的核心意义是：既然已经……就应该……。基于常识、责任、既定事实或立场提出应有行动。","category":"建议・责任","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + 以上（は）","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：既然已经……就应该……。","给出建议、忠告或道义判断。","表示既然前项成立，就应承担相应后果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["三者都表示“既然”；「上は」较书面，「からには」责任／决心感强。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","语气通常比单纯建议强；对听话人使用时需注意礼貌。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项常接义务、决心、当然判断，不接单纯过去事实。","客观义务、个人意见和社会责任应分别选择合适形式。"]},"g-n2-009":{"overview":"「～上は」的核心意义是：既然已经决定/到了这种地步，就……；书面。基于常识、责任、既定事实或立场提出应有行动。","category":"建议・责任","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书/た + 上は","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：既然已经决定/到了这种地步，就……；书面。","给出建议、忠告或道义判断。","表示既然前项成立，就应承担相应后果。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["三者都表示“既然”；「上は」较书面，「からには」责任／决心感强。","语气通常比单纯建议强；对听话人使用时需注意礼貌。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项常接义务、决心、当然判断，不接单纯过去事实。","客观义务、个人意见和社会责任应分别选择合适形式。"]},"g-n2-010":{"overview":"「～からには」的核心意义是：既然……就……，强调相应责任或决心。基于常识、责任、既定事实或立场提出应有行动。","category":"建议・责任","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + からには","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：既然……就……，强调相应责任或决心。","给出建议、忠告或道义判断。","表示既然前项成立，就应承担相应后果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["三者都表示“既然”；「上は」较书面，「からには」责任／决心感强。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","语气通常比单纯建议强；对听话人使用时需注意礼貌。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项常接义务、决心、当然判断，不接单纯过去事实。","客观义务、个人意见和社会责任应分别选择合适形式。"]},"g-n2-011":{"overview":"把前项设为不可缺少的必要条件；若不先满足该条件，后项便无法判断、行动或成立。","category":"条件・假定","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vない + ことには","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["强调开始讨论或作出判断之前必须具备的前提。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。"],"cautions":["后项多为「分からない／できない」等否定或含否定意义的表达。","先正确变出ない形，不能从辞书形机械删除词尾。"],"specialCases":["比一般「ないと」更强调“前提不成立就无从谈起”。"]},"g-n2-012":{"overview":"「～どころか」的核心意义是：别说……，反而……；实际情况远超预想。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N/普通形 + どころか","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：别说……，反而……；实际情况远超预想。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["先否定较低预期，再指出实际情况相反或程度更高。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项通常比前项更出乎意料。","强调句型常带说话人评价，正式度也各不相同。"]},"g-n2-013":{"overview":"「～どころではない」的核心意义是：根本不是做……的时候/情况。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书/N + どころではない","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：根本不是做……的时候/情况。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示由于更紧迫情况，根本没有余裕做前项。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不是场所意义的「ところ」。","强调句型常带说话人评价，正式度也各不相同。"]},"g-n2-014":{"overview":"「～ばかりか」的核心意义是：不仅……而且……；后项程度更高。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N/普通形 + ばかりか","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：不仅……而且……；后项程度更高。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示“不仅A而且B”，后项通常在范围或程度上进一步扩展；「のみならず」更书面。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前后项应保持并列层级。","强调句型常带说话人评价，正式度也各不相同。"]},"g-n2-015":{"overview":"「～のみならず」的核心意义是：不仅……而且……；较正式书面。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N/普通形 + のみならず","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：不仅……而且……；较正式书面。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示“不仅A而且B”，后项通常在范围或程度上进一步扩展；「のみならず」更书面。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前后项应保持并列层级。","强调句型常带说话人评价，正式度也各不相同。"]},"g-n2-016":{"overview":"「～に限らず」的核心意义是：不限于……；不仅仅是……。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + に限らず","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：不限于……；不仅仅是……。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["从某一范围扩展到更广范围，常与「〜も」呼应。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与“唯独／偏偏”的「に限って」不同。","强调句型常带说话人评价，正式度也各不相同。"]},"g-n2-017":{"overview":"「～に限って」的核心意义是：偏偏在……的时候；或唯独……。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + に限って","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：偏偏在……的时候；或唯独……。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示偏偏在某时、唯独某人例外，或基于信赖断定“不可能”。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["具体意义高度依赖后项。","强调句型常带说话人评价，正式度也各不相同。"]},"g-n2-018":{"overview":"「～限り」的核心意义是：只要……就……；在……范围内。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书/ている/Nである + 限り","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：只要……就……；在……范围内。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示只要状态持续、在所知范围内或竭尽全部能力。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不同接续会改变意义，不能统一译为“只要”。","必要条件与充分条件不应混为一谈。"]},"g-n2-019":{"overview":"「～に際して」的核心意义是：在……之际；正式场合。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N/V辞书 + に際して","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：在……之际；正式场合。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["都用于重要场合；「にあたって」更强调为此采取准备或态度。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["日常小事通常不用，语体正式。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n2-020":{"overview":"「～にあたって」的核心意义是：面临重要事件之时，为此做准备。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N/V辞书 + にあたって","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：面临重要事件之时，为此做准备。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["都用于重要场合；「にあたって」更强调为此采取准备或态度。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["日常小事通常不用，语体正式。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n2-021":{"overview":"「～に先立って」的核心意义是：在……之前，先进行某事；正式。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N/V辞书 + に先立って","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：在……之前，先进行某事；正式。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示在重要事件前预先做准备，时间先后明确。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["比普通「前に」正式。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n2-022":{"overview":"「～を通じて／通して」的核心意义是：通过某种媒介；或贯穿整个期间。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + を通じて/通して","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：通过某种媒介；或贯穿整个期间。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示借助媒介，也可表示贯穿整个期间；由所接名词判断。","可表示借助媒介，也可表示贯穿整个期间；根据名词类型判断。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["“以材料为基础创作”更常用「をもとに」。","媒介用法与期间用法不要混为一种固定译法。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"g-n2-023":{"overview":"「～をめぐって」的核心意义是：围绕某主题产生讨论、争论等。引出讨论、评价、态度或动作所针对的主题和对象。","category":"主题・对象","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + をめぐって","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：围绕某主题产生讨论、争论等。","说明关于什么进行调查、说明或讨论。","指出态度、作用或对比所面向的对象。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["常接争论、讨论、对立等，表示围绕一个议题。","表示主题的形式与表示动作对象、对比对象的形式不能完全互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["修饰名词用「をめぐるN」。","修饰名词时常需改用「〜に関する／〜についての」等连体形式。"]},"g-n2-024":{"overview":"「～に基づいて」的核心意义是：以某资料、事实、标准为依据。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + に基づいて","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：以某资料、事实、标准为依据。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["以事实、数据、法律等可靠依据为基础行动或判断。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["修饰名词用「に基づくN」。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"g-n2-025":{"overview":"「～に応じて」的核心意义是：根据……的变化、需求采取相应措施。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + に応じて","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：根据……的变化、需求采取相应措施。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["前项变化或需求不同，后项采取相应变化或措施。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["强调对应关系，不只是单向自然变化。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"g-n2-026":{"overview":"「～に伴って」的核心意义是：随着某变化，同时出现另一变化。表示两个动作并行、顺便进行，或两个变化相互伴随。","category":"同步・伴随","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N/V辞书 + に伴って","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：随着某变化，同时出现另一变化。","说明同一主体同时做两件事。","表达随一个变化发生另一个变化，或利用机会顺便做事。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["两项变化通常同向、逐渐或相伴发生；后项多为非意志变化。","同时动作常要求主语一致；长期副业与一次性顺便行为要区分。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["单纯同时发生不一定适用。","正式书面形式与日常「ながら」在语域上不同。"]},"g-n2-027":{"overview":"「～に沿って」的核心意义是：沿着……；按照方针、要求执行。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + に沿って","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：沿着……；按照方针、要求执行。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["可表示沿着路线，也可表示按方针、希望、计划执行。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["强调不偏离既定线索或标准。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"g-n2-028":{"overview":"「～にわたって」的核心意义是：跨越较长时间、范围。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + にわたって","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：跨越较长时间、范围。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["强调时间、空间、次数或范围跨度大。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["点状、很短范围通常不使用。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n2-029":{"overview":"「～次第」的核心意义是：一……马上……；后项多为意志行为。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vます去ます + 次第","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。"],"usages":["用于表达：一……马上……；后项多为意志行为。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["接动词ます形词干表示“一……立即……”，后项多为说话人可控制的行动。","不要保留「ます」再接句型。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不能用于自然发生、过去偶然事件；正式通知常见。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n2-030":{"overview":"「～次第で」的核心意义是：取决于……；根据……而改变。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + 次第で","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：取决于……；根据……而改变。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["名词＋次第で表示结果取决于前项；「次第だ」还可用于正式说明缘由。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与“一……就……”的动词词干＋次第区分。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"g-n2-031":{"overview":"「～てたまらない」的核心意义是：感情、感觉强烈到无法忍受。表达强烈感受、持续愿望或无法抑制的自然反应。","category":"情感・不可抑制","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて/い形くて/な形で + たまらない","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：感情、感觉强烈到无法忍受。","说明情绪、感觉强烈到难以控制。","表达某事必然引起反应，或长期怀有愿望。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「たまらない」强调主观强烈感受；「ならない」偏自然涌现；「かなわない」强调困扰、承受不了。","部分形式只适合第一人称内在感受，描述第三者时需有观察依据。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["描述第三者内心时需有可观察依据或引用。","「たまらない／ならない／かなわない」侧重点不同。"]},"g-n2-032":{"overview":"「～てならない」的核心意义是：自然而然产生强烈感情、感觉。表达强烈感受、持续愿望或无法抑制的自然反应。","category":"情感・不可抑制","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vて/い形くて/な形で + ならない","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：自然而然产生强烈感情、感觉。","说明情绪、感觉强烈到难以控制。","表达某事必然引起反应，或长期怀有愿望。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「たまらない」强调主观强烈感受；「ならない」偏自然涌现；「かなわない」强调困扰、承受不了。","部分形式只适合第一人称内在感受，描述第三者时需有观察依据。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["描述第三者内心时需有可观察依据或引用。","「たまらない／ならない／かなわない」侧重点不同。"]},"g-n2-033":{"overview":"「～ざるを得ない」的核心意义是：虽不情愿，但客观上不得不……；书面。表达没有必要、不能按意愿行事或不得不采取某行动。","category":"必要・无奈","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vない去ない + ざるを得ない（する→せざる）","formationNotes":["先变成ない形，再去掉「ない」连接；「する／来る」按不规则形式处理。"],"usages":["用于表达：虽不情愿，但客观上不得不……；书面。","说明现实、责任或社会常识造成的限制。","表达不做不能了结、只能接受或没有必要做。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["接ない形去「ない」；「する」固定为「せざるを得ない」。","先正确变出ない形，不能从辞书形机械删除词尾。","要区分客观能力不足、社会立场限制与外部强迫。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["比「なければならない」更突出非本意、没有其他选择。","否定成分多时应按整句理解，不能逐词相消。"]},"g-n2-034":{"overview":"「～ないわけにはいかない」的核心意义是：由于责任、常识等，不能不做。表达没有必要、不能按意愿行事或不得不采取某行动。","category":"必要・无奈","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vない + わけにはいかない","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：由于责任、常识等，不能不做。","说明现实、责任或社会常识造成的限制。","表达不做不能了结、只能接受或没有必要做。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["前者表示因责任、立场不能做；后者双重否定表示不能不做。","先正确变出ない形，不能从辞书形机械删除词尾。","要区分客观能力不足、社会立场限制与外部强迫。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不是能力上的“做不到”，而是社会或心理限制。","否定成分多时应按整句理解，不能逐词相消。"]},"gx-n2-w8mcip":{"overview":"「～に違いない」的核心意义是：基于依据强烈判断：“一定……”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + に違いない","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：基于依据强烈判断：“一定……”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["前者偏基于证据推断，后者偏说话人强烈、理所当然的断定。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["均是判断而非已经确认的事实。","确信度、证据来源和语体决定应选哪一种形式。"]},"gx-n2-13cnigy":{"overview":"「～に決まっている」的核心意义是：主观上非常确信：“肯定……／当然……”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + に決まっている","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：主观上非常确信：“肯定……／当然……”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["前者偏基于证据推断，后者偏说话人强烈、理所当然的断定。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["均是判断而非已经确认的事实。","确信度、证据来源和语体决定应选哪一种形式。"]},"gx-n2-1bcl8n3":{"overview":"「～にすぎない」的核心意义是：限定评价：“只不过……而已”。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形／N + にすぎない","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：限定评价：“只不过……而已”。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["把前项评价限定为“只不过”，常用于压低程度或范围。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["语气比单纯「だけ」更书面、评价性更强。","强调句型常带说话人评价，正式度也各不相同。"]},"gx-n2-lghw8v":{"overview":"「～にほかならない」的核心意义是：强调本质或原因：“正是……；无非是……”。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + にほかならない","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：强调本质或原因：“正是……；无非是……”。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["强调本质、真正原因或身份正是前项。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["多接名词，书面性强。","强调句型常带说话人评价，正式度也各不相同。"]},"gx-n2-wa3n4v":{"overview":"「～ものだから」的核心意义是：解释带有个人情由的原因，常用于辩解。补充背景、原因、依据或说话人的解释。","category":"说明・理由","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + ものだから","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：解释带有个人情由的原因，常用于辩解。","解释为什么出现某结果。","在会话、说明文或正式通知中交代理由。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["用于解释个人情由，常带辩解或希望对方体谅的语气。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","原因句型可能带客观说明、感谢、责怪或辩解等不同语气。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["正式客观原因不宜滥用。","后项能否接命令、请求或意志表达，取决于具体形式。"]},"gx-n2-ecdhn0":{"overview":"「～ものなら」的核心意义是：假定极难实现的事情：“如果能……的话”。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"可能形 + ものなら","formationNotes":["前接可能形；一段动词与被动形同形，需先确认语义。"],"usages":["用于表达：假定极难实现的事情：“如果能……的话”。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["常接可能形，假设实现困难或几乎不可能的愿望。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不要与普通可实现条件混用。","必要条件与充分条件不应混为一谈。"]},"gx-n2-nnrjmi":{"overview":"「～ものか」的核心意义是：强烈否定意志：“怎么会……／绝不……”。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"偏口语","note":"适合会话或带个人态度的表达；正式场合需选择更中性的形式。"},"formation":"普通形 + ものか","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：强烈否定意志：“怎么会……／绝不……”。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","适合会话或带个人态度的表达；正式场合需选择更中性的形式。"],"cautions":["以反问形式表达强烈否定或拒绝，口语感强。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["礼貌场合慎用。","强调句型常带说话人评价，正式度也各不相同。"]},"gx-n2-ezi68d":{"overview":"「～ことなく」的核心意义是：不做某事就……，书面表达。表示不做前项、维持某状态，或动作后状态持续。","category":"状态保持・附带","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书 + ことなく","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：不做某事就……，书面表达。","说明保持原样、放任不管或在不做A的情况下做B。","用较书面形式连接伴随状态。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["都可表示不做前项而做后项；「ずに／ことなく」更书面，「する」变为「せずに」。","「ないで」可表示“不做而……”也可表示请求禁止，需看后项。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「ないで」还可用于禁止请求，需看后项。","「っぱなし」常带放任不管的负面评价。"]},"gx-n2-1uicg27":{"overview":"用双重否定表达弱肯定：“也不是不能／并非完全不”，通常带保留、条件或不积极态度。","category":"限定・强调","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vない + ことはない","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["承认存在可能性，同时暗示有限制。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。"],"cautions":["语气不是强烈肯定，后面常接「が／けれど」。","先正确变出ない形，不能从辞书形机械删除词尾。"],"specialCases":["与必要条件「ないことには」意义完全不同。"]},"gx-n2-1lu02k0":{"overview":"「～ないではいられない」的核心意义是：情感或身体上“不由得……”。表达强烈感受、持续愿望或无法抑制的自然反应。","category":"情感・不可抑制","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vない + ではいられない","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：情感或身体上“不由得……”。","说明情绪、感觉强烈到难以控制。","表达某事必然引起反应，或长期怀有愿望。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示情感或生理上无法抑制；后者更书面。","先正确变出ない形，不能从辞书形机械删除词尾。","部分形式只适合第一人称内在感受，描述第三者时需有观察依据。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「する」的书面形式为「せずにはいられない」。","「たまらない／ならない／かなわない」侧重点不同。"]},"gx-n2-12fy20m":{"overview":"「～ずにはいられない」的核心意义是：「ないではいられない」的书面形式。表达强烈感受、持续愿望或无法抑制的自然反应。","category":"情感・不可抑制","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vない去ない + ずにはいられない","formationNotes":["先变成ない形，再去掉「ない」连接；「する／来る」按不规则形式处理。"],"usages":["用于表达：「ないではいられない」的书面形式。","说明情绪、感觉强烈到难以控制。","表达某事必然引起反应，或长期怀有愿望。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示情感或生理上无法抑制；后者更书面。","先正确变出ない形，不能从辞书形机械删除词尾。","部分形式只适合第一人称内在感受，描述第三者时需有观察依据。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「する」的书面形式为「せずにはいられない」。","「たまらない／ならない／かなわない」侧重点不同。"]},"gx-n2-11pfflz":{"overview":"「～かねない」的核心意义是：有发生负面结果的危险：“可能会……”。指出某种负面结果存在发生的可能。","category":"风险","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vます去ます + かねない","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。"],"usages":["用于表达：有发生负面结果的危险：“可能会……”。","警告当前做法可能造成不良后果。","在分析、劝告或正式说明中提示风险。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["虽含「ない」，整体表示存在发生坏结果的可能。","不要保留「ます」再接句型。","形式虽含「ない」，整体并不表示否定。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["一般不用于值得期待的积极结果。","通常只用于令人担心的结果。"]},"gx-n2-1h2hgee":{"overview":"表示由于立场、权限、规定或心理上的困难而“难以做／无法做”，常用于正式场合的委婉拒绝。","category":"困难・委婉拒绝","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vます去ます + かねる","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。"],"usages":["礼貌拒绝回答、判断、承诺或满足要求。","说明不是单纯不愿意，而是受客观立场或权限限制。","商务答复中常使用礼貌形「〜かねます」。"],"cautions":["接续是「Vます去ます＋かねる」，不存在独立句型「〜しかねる」。","「答える→答えかねる」；「判断する→判断しかねる」中的「し」是「する」的词干。","「お答えしかねます」来自「お答えする→お答えし＋かねます」。","不要保留「ます」再接句型。"],"specialCases":["「かねない」表示可能发生坏结果，并不是「かねる」的否定。","搭配用字上，“满足要求”通常是「要望に応える」，“回答问题”是「質問に答える」。"]},"gx-n2-126asqm":{"overview":"「～かのようだ」的核心意义是：实际上并非如此，但“仿佛……一样”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + かのようだ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：实际上并非如此，但“仿佛……一样”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「ようだ」偏中性，「みたいだ」更口语；名词接续分别常为「Nのようだ／Nみたいだ」。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["修饰名词用「ような」，修饰动词或形容词用「ように」。","确信度、证据来源和语体决定应选哪一种形式。"]},"gx-n2-10l1x9q":{"overview":"「～に従って」的核心意义是：随着……／按照……。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N／V辞书 + に従って","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：随着……／按照……。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示随变化而变化，也可表示遵照指示；两种意义需由名词性质判断。","既可表示随变化，也可表示遵照；汉字写法常见于正式文体。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["表示“按照”时多接规则、指示、方针。","与「に伴って」相比，“遵照”意义更突出。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"gx-n2-1unjzqg":{"overview":"「～をもとに（して）」的核心意义是：以材料、事实、经验等为基础重新构成。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + をもとに（して）","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：以材料、事实、经验等为基础重新构成。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["以材料、经验为基础进行加工、创作或判断，允许重新构成。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["严格不偏离规则时更适合「に基づいて／に沿って」。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"gx-n2-1h5pbov":{"overview":"「～を通じて／～を通して」的核心意义是：通过某媒介；或贯穿整个期间。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + を通じて／を通して","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：通过某媒介；或贯穿整个期间。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示借助媒介，也可表示贯穿整个期间；由所接名词判断。","可表示借助媒介，也可表示贯穿整个期间；根据名词类型判断。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["“以材料为基础创作”更常用「をもとに」。","媒介用法与期间用法不要混为一种固定译法。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"gx-n2-fmv6b1":{"overview":"「～に関して」的核心意义是：关于……，比「について」正式。引出讨论、评价、态度或动作所针对的主题和对象。","category":"主题・对象","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + に関して","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：关于……，比「について」正式。","说明关于什么进行调查、说明或讨论。","指出态度、作用或对比所面向的对象。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["修饰名词时用「についてのN／に関するN」；「に関して」更正式。","表示主题的形式与表示动作对象、对比对象的形式不能完全互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["多用于主题，不一定能替代具体动作对象的格助词。","修饰名词时常需改用「〜に関する／〜についての」等连体形式。"]},"gx-n2-15ki1s1":{"overview":"「～だけあって」的核心意义是：正因为具备某背景，所以结果与期待相符。突出原因、经过及最终结果，常附带说话人的评价。","category":"原因・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + だけあって","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：正因为具备某背景，所以结果与期待相符。","说明由于某一原因而产生结果。","总结长时间、反复过程后的结局。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「だけあって」表示结果符合背景期待；「だけに」强调正因为如此结果更强，可正可负。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「ばかりに／あげく」多倾向负面结果，而「末に」可好可坏。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不要与单纯限定「だけ」混淆。","原因与结果之间应具有自然、可理解的联系。"]},"gx-n2-m22kpj":{"overview":"「～だけに」的核心意义是：正因为……所以更……；可正可负。突出原因、经过及最终结果，常附带说话人的评价。","category":"原因・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + だけに","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：正因为……所以更……；可正可负。","说明由于某一原因而产生结果。","总结长时间、反复过程后的结局。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「だけあって」表示结果符合背景期待；「だけに」强调正因为如此结果更强，可正可负。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「ばかりに／あげく」多倾向负面结果，而「末に」可好可坏。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不要与单纯限定「だけ」混淆。","原因与结果之间应具有自然、可理解的联系。"]},"gx-n2-1efp0yv":{"overview":"「～ばかりに」的核心意义是：只因为某原因而导致不好的结果。突出原因、经过及最终结果，常附带说话人的评价。","category":"原因・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + ばかりに","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：只因为某原因而导致不好的结果。","说明由于某一原因而产生结果。","总结长时间、反复过程后的结局。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["突出仅因一个原因导致遗憾或坏结果，常含后悔。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「ばかりに／あげく」多倾向负面结果，而「末に」可好可坏。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项通常不是积极结果。","原因与结果之间应具有自然、可理解的联系。"]},"gx-n2-puwqot":{"overview":"「～あまり」的核心意义是：由于程度过高而导致结果。突出原因、经过及最终结果，常附带说话人的评价。","category":"原因・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Nの／V辞书 + あまり","formationNotes":["前接动词使用辞书形，不接「ます」。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：由于程度过高而导致结果。","说明由于某一原因而产生结果。","总结长时间、反复过程后的结局。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示程度过高而自然导致结果，常接感情、压力等。","「ばかりに／あげく」多倾向负面结果，而「末に」可好可坏。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["名词接「Nのあまり」。","原因与结果之间应具有自然、可理解的联系。"]},"gx-n2-xa6aca":{"overview":"「～あげく」的核心意义是：经过长时间或反复之后，最终出现多为负面的结果。突出原因、经过及最终结果，常附带说话人的评价。","category":"原因・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vた／Nの + あげく","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：经过长时间或反复之后，最终出现多为负面的结果。","说明由于某一原因而产生结果。","总结长时间、反复过程后的结局。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["都表示经过过程后的结果；「あげく」多负面，「末に」可好可坏且更中性。","「ばかりに／あげく」多倾向负面结果，而「末に」可好可坏。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前项通常是较长、反复的过程。","原因与结果之间应具有自然、可理解的联系。"]},"gx-n2-14dxe7j":{"overview":"「～末に」的核心意义是：经过一段过程后最终得出结果；结果可好可坏。突出原因、经过及最终结果，常附带说话人的评价。","category":"原因・结果","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vた／Nの + 末に","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：经过一段过程后最终得出结果；结果可好可坏。","说明由于某一原因而产生结果。","总结长时间、反复过程后的结局。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["都表示经过过程后的结果；「あげく」多负面，「末に」可好可坏且更中性。","「ばかりに／あげく」多倾向负面结果，而「末に」可好可坏。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前项通常是较长、反复的过程。","原因与结果之间应具有自然、可理解的联系。"]},"gx-n2-1deey5z":{"overview":"「～ところを」的核心意义是：在本应/正处某状态时；常用于客套感谢或道歉。突出特殊场合、极端对象或说话人对某对象的评价。","category":"立场・处境","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + ところを","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：在本应/正处某状态时；常用于客套感谢或道歉。","说明在特殊环境下采取的行动。","把话题焦点推到特别值得评论的对象。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["指出对方正处某情况却受到打扰，常用于感谢、道歉等客套表达。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","通常带明显语境和评价，不能作为中性主题标记替代「について」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见「お忙しいところを」「お休みのところを」。","前后文需明确特殊性或说话人的态度。"]},"gx-n2-39oxwz":{"overview":"「～というより」的核心意义是：与其说A，不如说B更准确。设定比较基准，或说明数量、性质和程度。","category":"比较・程度","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + というより","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：与其说A，不如说B更准确。","比较两个对象或范围内的高低。","用极端例子、数量或结果说明程度。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["不是简单比较两物，而是修正措辞，说明B比A更准确。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","比较对象、基准和评价对象的助词不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常用「Aというより（も）B」。","否定比较与最高级结构有固定语序。"]},"gx-n2-pzvide":{"overview":"「～といっても」的核心意义是：虽说……，实际上程度没有想象得那么高。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + といっても","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：虽说……，实际上程度没有想象得那么高。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["承认名称或事实后，限制其实际程度，避免听者过度想象。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与普通逆接相比，重点是修正前项给人的印象。","要区分既成事实的逆接与假设条件的让步。"]},"gx-n2-zrt8fu":{"overview":"「～としたら／～とすれば」的核心意义是：假设某情况成立：“如果……的话”。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"普通形 + としたら／とすれば","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：假设某情况成立：“如果……的话”。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["把尚未确定的情况作为推理前提；后项常为判断、结论。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「とすると」也常见，语气较逻辑化。","必要条件与充分条件不应混为一谈。"]},"gx-n2-107g1jy":{"overview":"「～とともに」的核心意义是：与……一起；同时；随着……。并列理由、动作或例子，并说明列举是否完整。","category":"并列・列举","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N／V辞书 + とともに","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：与……一起；同时；随着……。","列出多个同类事实、理由或动作。","用代表性项目暗示还有其他内容。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可表示与某人一起、同时发生，或随变化而变化，书面性较强。","「と」偏完整列举，「や／など／とか」多为不完全列举。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["意义由前接名词／动词和后项决定。","列举句型通常要求前后项目在语法形式和评价方向上协调。"]},"gx-n2-1daz7eh":{"overview":"「～につき」的核心意义是：正式通知中表示“因为……／每……”。补充背景、原因、依据或说话人的解释。","category":"说明・理由","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + につき","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：正式通知中表示“因为……／每……”。","解释为什么出现某结果。","在会话、说明文或正式通知中交代理由。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["正式通知中可表示原因，也可表示单位比例“每……”。","原因句型可能带客观说明、感谢、责怪或辩解等不同语气。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["日常会话中不自然；两种意义靠名词和语境区分。","后项能否接命令、请求或意志表达，取决于具体形式。"]},"gx-n2-1l2o2tp":{"overview":"「～につけ」的核心意义是：每当看到/听到某事就产生同样感情。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书 + につけ","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：每当看到/听到某事就产生同样感情。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["常用「見るにつけ／聞くにつけ」表示每次接触便产生同样情感。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项多为自然感想，不是意志行动。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"gx-n2-1gsdfk2":{"overview":"「～上で」的核心意义是：在做A之后再做B；或在某方面。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"Vた／Nの + 上で","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：在做A之后再做B；或在某方面。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["「Vた上で」表示完成A后再B；「Nの上で」可表示在某方面。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与“既然”的「上は」不同。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"gx-n2-12h81zc":{"overview":"「～にしては」的核心意义是：以某标准来说结果出乎意料。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N／普通形 + にしては","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：以某标准来说结果出乎意料。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["以身份、年龄、标准等衡量，实际结果超出预期。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前项是评价基准，不是原因。","要区分既成事实的逆接与假设条件的让步。"]},"gx-n2-ntyuu1":{"overview":"「～にしても～にしても」的核心意义是：无论A还是B，后项都成立。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N／普通形 + にしても + N／普通形 + にしても","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：无论A还是B，后项都成立。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["列举两个代表选项，表示无论哪一个，后项判断都相同。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前后形式应平行。","要区分既成事实的逆接与假设条件的让步。"]},"gx-n2-15rt1kw":{"overview":"「～からして」的核心意义是：从一个典型例子就能推断整体；或从……来看。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + からして","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：从一个典型例子就能推断整体；或从……来看。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["可从一个典型例子推断整体，也可表示从某立场判断。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与单纯起点「から」无关。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"gx-n2-on341t":{"overview":"「～からすると／～からすれば」的核心意义是：从某立场或依据来判断。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + からすると","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：从某立场或依据来判断。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示从某人的立场或某依据来看；人名后常译为“在……看来”。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不能表示动作起点。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"gx-n2-6zyu1c":{"overview":"「～に加えて」的核心意义是：在已有事项上再增加：“加上……”。并列理由、动作或例子，并说明列举是否完整。","category":"并列・列举","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + に加えて","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：在已有事项上再增加：“加上……”。","列出多个同类事实、理由或动作。","用代表性项目暗示还有其他内容。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["在已有事实上追加同方向的信息，常用于书面说明。","「と」偏完整列举，「や／など／とか」多为不完全列举。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["若前后项评价方向相反，应使用对照表达。","列举句型通常要求前后项目在语法形式和评价方向上协调。"]},"gx-n2-17r20j8":{"overview":"「～に反して」的核心意义是：与预期、规则、愿望等相反。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"N + に反して","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：与预期、规则、愿望等相反。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["表示结果与期待、预测、规则或愿望相反。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前项通常是「期待・予想・意志・規則」等名词。","要区分既成事实的逆接与假设条件的让步。"]},"gx-n2-1590q2w":{"overview":"「～恐れがある」的核心意义是：正式表达存在负面风险：“有……的可能”。根据观察、证据、传闻或主观判断表达不确定信息。","category":"推量・传闻","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书／Nの + 恐れがある","formationNotes":["前接动词使用辞书形，不接「ます」。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：正式表达存在负面风险：“有……的可能”。","表达看起来、听说、也许或高度确信。","区分信息来源、外观印象和说话人的推断。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["正式指出负面风险，常见于新闻、警告和报告。","中文都可能译成“好像”，但样态、传闻、推测和典型性不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["积极可能性不用「恐れ」。","确信度、证据来源和语体决定应选哪一种形式。"]},"gx-n2-vdz39q":{"overview":"「～ことだ」的核心意义是：对听话人提出建议或忠告：“应该……”。基于常识、责任、既定事实或立场提出应有行动。","category":"建议・责任","register":{"label":"中性","note":"可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"},"formation":"V辞书／Vない + ことだ","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：对听话人提出建议或忠告：“应该……”。","给出建议、忠告或道义判断。","表示既然前项成立，就应承担相应后果。","可用于一般会话和书面语，礼貌度主要由句末形式和上下文决定。"],"cautions":["V辞书／ない＋ことだ用于忠告；并非名词化的普通「こと」。","先正确变出ない形，不能从辞书形机械删除词尾。","语气通常比单纯建议强；对听话人使用时需注意礼貌。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["语气比「ほうがいい」更像原则性建议。","客观义务、个人意见和社会责任应分别选择合适形式。"]},"g-n1-001":{"overview":"「～が早いか」的核心意义是：刚一……就……；后项几乎同时发生。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书/た + が早いか","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：刚一……就……；后项几乎同时发生。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["都表示紧接发生；后项多为过去叙述，不能随意接命令、意志。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「なり」前后主语通常相同；三者均偏书面。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n1-002":{"overview":"「～や否や」的核心意义是：刚一……就……；书面、叙述性强。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书 + や否や","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：刚一……就……；书面、叙述性强。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["都表示紧接发生；后项多为过去叙述，不能随意接命令、意志。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「なり」前后主语通常相同；三者均偏书面。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n1-003":{"overview":"「～なり」的核心意义是：一……就……；前后主语通常相同。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书 + なり","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：一……就……；前后主语通常相同。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["都表示紧接发生；后项多为过去叙述，不能随意接命令、意志。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「なり」前后主语通常相同；三者均偏书面。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n1-004":{"overview":"「～そばから」的核心意义是：刚做完又……，常表示反复发生且令人困扰。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书/た + そばから","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：刚做完又……，常表示反复发生且令人困扰。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示刚做完同类问题又反复出现，常带无奈或困扰。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不是单纯“一……就……”，含反复性。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n1-005":{"overview":"「～が最後」的核心意义是：一旦……就会一直/再也无法……。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vた + が最後","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。"],"usages":["用于表达：一旦……就会一直/再也无法……。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示一旦前项发生便难以挽回或必然持续后果。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项通常负面且不可逆。","必要条件与充分条件不应混为一谈。"]},"g-n1-006":{"overview":"「～かたがた」的核心意义是：顺便兼做……；正式礼貌。表示两个动作并行、顺便进行，或两个变化相互伴随。","category":"同步・伴随","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + かたがた","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：顺便兼做……；正式礼貌。","说明同一主体同时做两件事。","表达随一个变化发生另一个变化，或利用机会顺便做事。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["以一个正式目的为主，同时兼做另一事，常用于访问、问候、感谢。","同时动作常要求主语一致；长期副业与一次性顺便行为要区分。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["多接具有礼仪性的名词。","正式书面形式与日常「ながら」在语域上不同。"]},"g-n1-007":{"overview":"「～かたわら」的核心意义是：一边从事主要活动，一边长期兼做另一活动。表示两个动作并行、顺便进行，或两个变化相互伴随。","category":"同步・伴随","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书/Nの + かたわら","formationNotes":["前接动词使用辞书形，不接「ます」。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：一边从事主要活动，一边长期兼做另一活动。","说明同一主体同时做两件事。","表达随一个变化发生另一个变化，或利用机会顺便做事。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示长期主要活动之外持续兼做另一活动。","同时动作常要求主语一致；长期副业与一次性顺便行为要区分。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["一次性顺便行为用「がてら」。","正式书面形式与日常「ながら」在语域上不同。"]},"g-n1-008":{"overview":"「～がてら」的核心意义是：借做 A 的机会顺便做 B。表示两个动作并行、顺便进行，或两个变化相互伴随。","category":"同步・伴随","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vます去ます/N + がてら","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：借做 A 的机会顺便做 B。","说明同一主体同时做两件事。","表达随一个变化发生另一个变化，或利用机会顺便做事。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["借做A的机会顺便做B，通常是一次性、同一路径上的动作。","不要保留「ます」再接句型。","同时动作常要求主语一致；长期副业与一次性顺便行为要区分。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["比「かたがた」口语一些。","正式书面形式与日常「ながら」在语域上不同。"]},"g-n1-009":{"overview":"「～つつ」的核心意义是：一边……一边……；较书面。表示两个动作并行、顺便进行，或两个变化相互伴随。","category":"同步・伴随","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vます去ます + つつ","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。"],"usages":["用于表达：一边……一边……；较书面。","说明同一主体同时做两件事。","表达随一个变化发生另一个变化，或利用机会顺便做事。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示同时动作时前后主语原则上相同，后项通常是主要动作。","不要保留「ます」再接句型。","同时动作常要求主语一致；长期副业与一次性顺便行为要区分。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「つつ」比「ながら」书面；「つつも」则表示逆接。","正式书面形式与日常「ながら」在语域上不同。"]},"g-n1-010":{"overview":"「～つつも」的核心意义是：虽然明知/正在……却……；书面。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vます去ます + つつも","formationNotes":["先变成ます形，再去掉「ます」连接；サ变动词的词干是「し」。"],"usages":["用于表达：虽然明知/正在……却……；书面。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["承认自己知道或处于前项状态，却做出相反行为，常含反省。","不要保留「ます」再接句型。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前后主语通常相同，书面语。","要区分既成事实的逆接与假设条件的让步。"]},"g-n1-011":{"overview":"「～といえども」的核心意义是：即使是……也……；正式书面。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N/普通形 + といえども","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：即使是……也……；正式书面。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["即使承认具有特殊身份或极端条件，后项仍成立，正式书面。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常与「いかなる／どんな」等呼应。","要区分既成事实的逆接与假设条件的让步。"]},"g-n1-012":{"overview":"「～とあって」的核心意义是：正因为是特殊情况，所以出现自然结果。补充背景、原因、依据或说话人的解释。","category":"说明・理由","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N/普通形 + とあって","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：正因为是特殊情况，所以出现自然结果。","解释为什么出现某结果。","在会话、说明文或正式通知中交代理由。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["「とあって」说明特殊情况带来自然结果；「とあれば／とあっては」设定特殊条件并表达相应态度。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","原因句型可能带客观说明、感谢、责怪或辩解等不同语气。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["均偏书面，不能与普通条件完全互换。","后项能否接命令、请求或意志表达，取决于具体形式。"]},"g-n1-013":{"overview":"「～とあれば」的核心意义是：如果真是……的话，就会……。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N/普通形 + とあれば","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：如果真是……的话，就会……。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["「とあって」说明特殊情况带来自然结果；「とあれば／とあっては」设定特殊条件并表达相应态度。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["均偏书面，不能与普通条件完全互换。","必要条件与充分条件不应混为一谈。"]},"g-n1-014":{"overview":"「～とあっては」的核心意义是：如果是那种特殊情况，则不得不采取相应态度。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N/普通形 + とあっては","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：如果是那种特殊情况，则不得不采取相应态度。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["「とあって」说明特殊情况带来自然结果；「とあれば／とあっては」设定特殊条件并表达相应态度。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["均偏书面，不能与普通条件完全互换。","必要条件与充分条件不应混为一谈。"]},"g-n1-015":{"overview":"「～ではあるまいし」的核心意义是：又不是……，所以不应该……；多用于批评。补充背景、原因、依据或说话人的解释。","category":"说明・理由","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N/普通形 + ではあるまいし","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：又不是……，所以不应该……；多用于批评。","解释为什么出现某结果。","在会话、说明文或正式通知中交代理由。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["以“又不是……”为理由批评后项行为不合适。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","原因句型可能带客观说明、感谢、责怪或辩解等不同语气。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["含责备，不适合礼貌地对上级说。","后项能否接命令、请求或意志表达，取决于具体形式。"]},"g-n1-016":{"overview":"「～までもない」的核心意义是：没必要特地……。表达没有必要、不能按意愿行事或不得不采取某行动。","category":"必要・无奈","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书 + までもない","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：没必要特地……。","说明现实、责任或社会常识造成的限制。","表达不做不能了结、只能接受或没有必要做。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["都可表示没有必要；「には及ばない」还可表示不及、比不上。","要区分客观能力不足、社会立场限制与外部强迫。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["语体正式，需靠谓语或名词判断具体义。","否定成分多时应按整句理解，不能逐词相消。"]},"g-n1-017":{"overview":"「～には及ばない」的核心意义是：没有必要……；也可表示比不上。表达没有必要、不能按意愿行事或不得不采取某行动。","category":"必要・无奈","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书/N + には及ばない","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：没有必要……；也可表示比不上。","说明现实、责任或社会常识造成的限制。","表达不做不能了结、只能接受或没有必要做。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["都可表示没有必要；「には及ばない」还可表示不及、比不上。","要区分客观能力不足、社会立场限制与外部强迫。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["语体正式，需靠谓语或名词判断具体义。","否定成分多时应按整句理解，不能逐词相消。"]},"g-n1-018":{"overview":"「～ずにはおかない」的核心意义是：必然会引起某结果；一定要使……。表达强烈感受、持续愿望或无法抑制的自然反应。","category":"情感・不可抑制","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vない去ない + ずにはおかない","formationNotes":["先变成ない形，再去掉「ない」连接；「する／来る」按不规则形式处理。"],"usages":["用于表达：必然会引起某结果；一定要使……。","说明情绪、感觉强烈到难以控制。","表达某事必然引起反应，或长期怀有愿望。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示必然引起某反应，或主语强烈意志一定要使之发生。","先正确变出ない形，不能从辞书形机械删除词尾。","部分形式只适合第一人称内在感受，描述第三者时需有观察依据。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不是单纯“不得不”，而是结果不会不发生。","「たまらない／ならない／かなわない」侧重点不同。"]},"g-n1-019":{"overview":"「～ずにはすまない」的核心意义是：由于责任或社会常识，不做就无法了结。表达没有必要、不能按意愿行事或不得不采取某行动。","category":"必要・无奈","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vない去ない + ずにはすまない","formationNotes":["先变成ない形，再去掉「ない」连接；「する／来る」按不规则形式处理。"],"usages":["用于表达：由于责任或社会常识，不做就无法了结。","说明现实、责任或社会常识造成的限制。","表达不做不能了结、只能接受或没有必要做。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["因责任、道义或社会常识，不做前项便无法了结。","先正确变出ない形，不能从辞书形机械删除词尾。","要区分客观能力不足、社会立场限制与外部强迫。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「する」变为「せずにはすまない」。","否定成分多时应按整句理解，不能逐词相消。"]},"g-n1-020":{"overview":"「～を禁じ得ない」的核心意义是：无法抑制某种感情；正式书面。表达强烈感受、持续愿望或无法抑制的自然反应。","category":"情感・不可抑制","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + を禁じ得ない","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：无法抑制某种感情；正式书面。","说明情绪、感觉强烈到难以控制。","表达某事必然引起反应，或长期怀有愿望。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["多接「同情・怒り・笑い」等感情名词，表示无法抑制，极正式。","部分形式只适合第一人称内在感受，描述第三者时需有观察依据。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不是一般动作不能。","「たまらない／ならない／かなわない」侧重点不同。"]},"g-n1-021":{"overview":"「～を余儀なくされる」的核心意义是：由于外部原因，被迫……。表达没有必要、不能按意愿行事或不得不采取某行动。","category":"必要・无奈","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + を余儀なくされる","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：由于外部原因，被迫……。","说明现实、责任或社会常识造成的限制。","表达不做不能了结、只能接受或没有必要做。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["外部情况迫使主语接受某行动／状态，主语多为受影响者。","要区分客观能力不足、社会立场限制与外部强迫。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["主动形式「を余儀なくさせる」表示迫使他人。","否定成分多时应按整句理解，不能逐词相消。"]},"g-n1-022":{"overview":"「～をものともせず」的核心意义是：不把困难、危险放在眼里，毅然行动。表示不顾周围反应或不把困难当回事而采取行动。","category":"无视・克服","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + をものともせず","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：不把困难、危险放在眼里，毅然行动。","描写顶住困难继续行动。","对照周围人的期待、批评或状态。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示不把困难、危险放在眼里而行动，通常带赞扬。","「ものともせず」常带赞扬，「よそに／尻目に」多带批评或对照。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前项多为障碍或逆境。","所接名词通常是困难、反应或旁人的状态。"]},"g-n1-023":{"overview":"「～に堪えない」的核心意义是：不值得……/令人无法忍受……。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N/V辞书 + に堪えない","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：不值得……/令人无法忍受……。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["可表示不堪看／听，也有「感謝に堪えない」等无法抑制的正式固定表达。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与“值得”的肯定「に堪える」区分。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"g-n1-024":{"overview":"「～に堪える」的核心意义是：值得……；经得起……。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N/V辞书 + に堪える","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：值得……；经得起……。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示值得观赏／评价，或能够经受某种使用与考验。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["否定形式「に堪えない」可能有“不值得／不堪”的不同解释。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"g-n1-025":{"overview":"「～に足る」的核心意义是：值得……；足以……。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N/V辞书 + に足る","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：值得……；足以……。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示足以／不足以作为信赖、评价或讨论对象，书面性强。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「足る」读作「たる」，不是身份表达「たるもの」。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"g-n1-026":{"overview":"「～に足りない」的核心意义是：不足以……；不值得……。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N/V辞书 + に足りない","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：不足以……；不值得……。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示足以／不足以作为信赖、评价或讨论对象，书面性强。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「足る」读作「たる」，不是身份表达「たるもの」。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"g-n1-027":{"overview":"「～まじき」的核心意义是：不应该发生在某身份/立场上的行为。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书 + まじき + N","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：不应该发生在某身份/立场上的行为。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["放在名词前，表示与某身份、立场严重不相称。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见「〜としてあるまじき／〜にあるまじき」。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"g-n1-028":{"overview":"「～べからず」的核心意义是：禁止：“不得……”；公告、规则等书面表达。表达可以做、不可以做、必须做或不必做。","category":"许可・禁止・义务","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书 + べからず","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：禁止：“不得……”；公告、规则等书面表达。","说明规则、许可、禁止和必要性。","在日常交流中询问或给予行动许可。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示强烈、书面的禁止，常见于规章、格言、告示。","义务强度与礼貌度不同，对特定听话人直接使用强制表达可能显得生硬。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「する」可变为「すべからず」。","口语中常有缩约，但正式说明应使用完整形式。"]},"g-n1-029":{"overview":"「～いかんで」的核心意义是：取决于……如何。用正式书面语表达条件取决、无论如何或缺少前提便不能成立。","category":"正式条件・范围","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + いかんで","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：取决于……如何。","在公告、议论和正式说明中设定条件。","表达结果取决于内容，或不受条件影响。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示结果取决于前项内容、方式如何，正式书面。","「いかん」是名词性书面表达，前接多用「N（の）」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见「N（の）いかんで／いかんによって」。","肯定的“取决于”与“无论如何”形式不同。"]},"g-n1-030":{"overview":"「～いかんによらず」的核心意义是：无论……如何，都……。用正式书面语表达条件取决、无论如何或缺少前提便不能成立。","category":"正式条件・范围","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + いかんによらず","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：无论……如何，都……。","在公告、议论和正式说明中设定条件。","表达结果取决于内容，或不受条件影响。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示不论前项内容如何，后项一律成立。","「いかん」是名词性书面表达，前接多用「N（の）」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与取决于条件的「いかんで」意义相反。","肯定的“取决于”与“无论如何”形式不同。"]},"g-n1-031":{"overview":"「～んばかり」的核心意义是：几乎要……似的；程度非常强烈。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vない去ない + んばかり","formationNotes":["先变成ない形，再去掉「ない」连接；「する／来る」按不规则形式处理。"],"usages":["用于表达：几乎要……似的；程度非常强烈。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["接ない形去「ない」表示几乎就要发生的强烈样态；「する」常为「せんばかり」。","先正确变出ない形，不能从辞书形机械删除词尾。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不是实际已经发生。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"g-n1-032":{"overview":"「～とばかりに」的核心意义是：仿佛在说“……”似地做某动作。引用话语、想法和信息，或给事物命名、下定义。","category":"引用・定义","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"引用 + とばかりに","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：仿佛在说“……”似地做某动作。","转述说话内容或表达自己的判断。","说明名称、概念和前文结论。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["把非语言动作解释为仿佛在说某句话。","直接引用与间接引用的人称、时态和语气处理不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前项通常是引用内容，后项描述表情、动作。","引用助词「と」前通常使用普通形。"]},"g-n1-033":{"overview":"「～極まりない／極まる」的核心意义是：极其……；多接负面评价，书面。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"な形 + 極まりない","formationNotes":["な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。"],"usages":["用于表达：极其……；多接负面评价，书面。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["多接な形容词词干，表示评价达到极点；书面、语气强。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「極まりない」虽有「ない」，整体不是程度否定。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"g-n1-034":{"overview":"「～の至り」的核心意义是：达到……的极点；常见固定正式表达。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + の至り","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：达到……的极点；常见固定正式表达。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["构成正式固定表达，表示某种感情或状态达到极点。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见「光栄の至り／感激の極み」等搭配，不能任意接所有名词。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"g-n1-035":{"overview":"「～とは」的核心意义是：对意外事实表示惊讶：“竟然……”。引用话语、想法和信息，或给事物命名、下定义。","category":"引用・定义","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"普通形 + とは","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：对意外事实表示惊讶：“竟然……”。","转述说话内容或表达自己的判断。","说明名称、概念和前文结论。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["句末用法对意外事实表示惊讶；定义用法则是「Nとは〜ことだ」。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","直接引用与间接引用的人称、时态和语气处理不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["应结合句子位置区分。","引用助词「と」前通常使用普通形。"]},"g-n1-036":{"overview":"「～たるもの」的核心意义是：身为某身份的人理应具备相应态度。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + たるもの","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：身为某身份的人理应具备相应态度。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["以身份为前提说明理应具备的责任或态度，语气庄重。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见「教師たるもの」。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"g-n1-037":{"overview":"「～に至って」的核心意义是：到了某阶段才……；事情发展至极端阶段。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N/V辞书 + に至って","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：到了某阶段才……；事情发展至极端阶段。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["分别突出到达某阶段、范围甚至扩展到极端、或举出极端对象。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「に至って」常含直到此时才发生的迟延感。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n1-038":{"overview":"「～に至るまで」的核心意义是：甚至到……，表示范围扩展到极端。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + に至るまで","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：甚至到……，表示范围扩展到极端。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["分别突出到达某阶段、范围甚至扩展到极端、或举出极端对象。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「に至って」常含直到此时才发生的迟延感。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"g-n1-039":{"overview":"「～に即して」的核心意义是：严格按照事实、规则、方针。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + に即して","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：严格按照事实、规则、方针。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["「即して」按事实／实际情况；「則って」严格遵照规则、法律、惯例。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["汉字不同，依据类型也不同。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"g-n1-040":{"overview":"「～ならでは」的核心意义是：只有……才有的独特特点。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + ならでは","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：只有……才有的独特特点。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示只有该人、地方或事物才具有的独特优点／特征。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["通常用于肯定评价，修饰名词时常说「ならではのN」。","强调句型常带说话人评价，正式度也各不相同。"]},"gx-n1-1yju691":{"overview":"「～ものを」的核心意义是：明明……却……；带遗憾、责备语气。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"普通形 + ものを","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：明明……却……；带遗憾、责备语气。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示若按前项本可有不同结果，却出现遗憾现实，常省略后项。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["带遗憾或责备，书面／郑重。","要区分既成事实的逆接与假设条件的让步。"]},"gx-n1-c2okls":{"overview":"「～とはいえ」的核心意义是：虽说……但……，承认前项后提出限制或反例。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"普通形 + とはいえ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：虽说……但……，承认前项后提出限制或反例。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["先承认前项，再补充限制或例外，比普通「けれど」书面。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不表示完全推翻前项。","要区分既成事实的逆接与假设条件的让步。"]},"gx-n1-x2tqi1":{"overview":"「～なくして（は）」的核心意义是：没有……就不可能……，正式表达。用正式书面语表达条件取决、无论如何或缺少前提便不能成立。","category":"正式条件・范围","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + なくして（は）","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：没有……就不可能……，正式表达。","在公告、议论和正式说明中设定条件。","表达结果取决于内容，或不受条件影响。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示缺少必要条件便不能实现后项；后项常为否定或不可能。","「いかん」是名词性书面表达，前接多用「N（の）」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「なくして」更郑重抽象，「なしに」也可表示未经许可等。","肯定的“取决于”与“无论如何”形式不同。"]},"gx-n1-1k5c5vl":{"overview":"「～なしに（は）」的核心意义是：不经过/没有……就……。用正式书面语表达条件取决、无论如何或缺少前提便不能成立。","category":"正式条件・范围","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + なしに（は）","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：不经过/没有……就……。","在公告、议论和正式说明中设定条件。","表达结果取决于内容，或不受条件影响。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示缺少必要条件便不能实现后项；后项常为否定或不可能。","「いかん」是名词性书面表达，前接多用「N（の）」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「なくして」更郑重抽象，「なしに」也可表示未经许可等。","肯定的“取决于”与“无论如何”形式不同。"]},"gx-n1-1axnapf":{"overview":"「～に至っては」的核心意义是：举出极端例子：“至于……更是……”。突出特殊场合、极端对象或说话人对某对象的评价。","category":"立场・处境","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + に至っては","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：举出极端例子：“至于……更是……”。","说明在特殊环境下采取的行动。","把话题焦点推到特别值得评论的对象。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["分别突出到达某阶段、范围甚至扩展到极端、或举出极端对象。","通常带明显语境和评价，不能作为中性主题标记替代「について」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「に至って」常含直到此时才发生的迟延感。","前后文需明确特殊性或说话人的态度。"]},"gx-n1-1xlfkjt":{"overview":"「～にあって」的核心意义是：在特殊环境、时期或处境下。突出特殊场合、极端对象或说话人对某对象的评价。","category":"立场・处境","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + にあって","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：在特殊环境、时期或处境下。","说明在特殊环境下采取的行动。","把话题焦点推到特别值得评论的对象。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示在特殊时代、环境或处境之下，后项常突出仍然采取的行为。","通常带明显语境和评价，不能作为中性主题标记替代「について」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["正式书面，不用于普通地点。","前后文需明确特殊性或说话人的态度。"]},"gx-n1-bldvau":{"overview":"「～にかかわる」的核心意义是：关系到重大事项：“涉及……”。引出讨论、评价、态度或动作所针对的主题和对象。","category":"主题・对象","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + にかかわる","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：关系到重大事项：“涉及……”。","说明关于什么进行调查、说明或讨论。","指出态度、作用或对比所面向的对象。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示关系到生命、名誉、根本等重大事项。","表示主题的形式与表示动作对象、对比对象的形式不能完全互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不要与“不论”的「にかかわらず」混淆。","修饰名词时常需改用「〜に関する／〜についての」等连体形式。"]},"gx-n1-166ezii":{"overview":"「～に則って」的核心意义是：严格按照规则、惯例、法律等。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + に則って","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：严格按照规则、惯例、法律等。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["「即して」按事实／实际情况；「則って」严格遵照规则、法律、惯例。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["汉字不同，依据类型也不同。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"gx-n1-qldmna":{"overview":"「～を踏まえて」的核心意义是：在充分考虑某事实/结果的基础上。说明行动或判断的依据、标准、来源、方式和对应关系。","category":"依据・方法","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + を踏まえて","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：在充分考虑某事实/结果的基础上。","指出按照什么资料、方针或情况行动。","说明信息来源、判断立场或因条件而异。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["在充分考虑前项事实、经验、结果后再行动。","「によって」可表示手段、原因、主体和差异，必须结合句型判断。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["比单纯“根据”更强调吸收和考虑。","“依据原材料重新创作”与“严格遵照规则”所用形式不同。"]},"gx-n1-1a00ddp":{"overview":"「～を皮切りに」的核心意义是：以某事为开端，随后同类事件接连发生。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + を皮切りに","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：以某事为开端，随后同类事件接连发生。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["以一个显著事件为开端，随后同类事件连续展开。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项应有扩展、接连发生的内容。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"gx-n1-n45rh4":{"overview":"「～を限りに」的核心意义是：以某时间/事件为最后期限：“到……为止”。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + を限りに","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：以某时间/事件为最后期限：“到……为止”。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["以某时点／事件作为最后界限，此后停止或改变。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见「今日を限りに」。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"gx-n1-65huz4":{"overview":"「～をもって」的核心意义是：正式表示时间界限、手段或资格。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + をもって","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：正式表示时间界限、手段或资格。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["可正式表示时间界限、手段或资格；公告中常见。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不是所有「で」都可替换为「をもって」。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"gx-n1-41qobi":{"overview":"「～たりとも」的核心意义是：即使最小单位也不例外：“哪怕……也……”。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"数量词 + たりとも + 否定","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：即使最小单位也不例外：“哪怕……也……”。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["与最小数量词及否定呼应，表示哪怕一点也不例外。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见「一秒たりとも〜ない」。","强调句型常带说话人评价，正式度也各不相同。"]},"gx-n1-1gbufpk":{"overview":"「～だに」的核心意义是：连想/听都……；仅仅……就……，古典书面色彩。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N／V辞书 + だに","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：连想/听都……；仅仅……就……，古典书面色彩。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示连想、听等最低程度都引发强烈反应，古典书面色彩浓。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见固定搭配「想像するだに」。","强调句型常带说话人评价，正式度也各不相同。"]},"gx-n1-1fsx6z7":{"overview":"「～すら」的核心意义是：连……都……；比「さえ」更书面。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + すら","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：连……都……；比「さえ」更书面。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["举出极端例子“连……都”，比「さえ」更书面。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["格助词有时与之组合。","强调句型常带说话人评价，正式度也各不相同。"]},"gx-n1-1he2h2d":{"overview":"「～べく」的核心意义是：为了……而……，正式书面表达。说明行动的目的、目标或为了达到某状态而采取的措施。","category":"目的","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书 + べく（する→すべく）","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：为了……而……，正式书面表达。","说明移动或行动是为了做什么。","表达努力达到能力、状态或避免某结果。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["接辞书形表示正式目的；「する」通常为「すべく」。","「ために」与「ように」对意志性、主语和可控制性有不同限制。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项是为实现目的采取的行动。","目的句前后主语是否相同，需要按具体句型确认。"]},"gx-n1-161ya17":{"overview":"「～なりとも」的核心意义是：哪怕……也好；至少……。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + なりとも","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：哪怕……也好；至少……。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示哪怕最低限度的对象也好，带让步与希望。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常与请求、愿望搭配。","强调句型常带说话人评价，正式度也各不相同。"]},"gx-n1-14n3t0x":{"overview":"「～ともなく／～ともなしに」的核心意义是：无意识、漫不经心地做某事。表示不做前项、维持某状态，或动作后状态持续。","category":"状态保持・附带","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书 + ともなく","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：无意识、漫不经心地做某事。","说明保持原样、放任不管或在不做A的情况下做B。","用较书面形式连接伴随状态。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示无明确意识、对象或目的地做某事。","「ないで」可表示“不做而……”也可表示请求禁止，需看后项。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见「見るともなく見る」「どこへともなく」。","「っぱなし」常带放任不管的负面评价。"]},"gx-n1-1621eqo":{"overview":"「～ともなると」的核心意义是：一旦到了某程度/身份，就自然出现后项。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + ともなると","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：一旦到了某程度/身份，就自然出现后项。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["一旦达到特殊身份、季节或规模，后项自然出现。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["前项通常具有阶段性或特殊性。","必要条件与充分条件不应混为一谈。"]},"gx-n1-ujpye9":{"overview":"「～ゆえ（に）」的核心意义是：因为……；由于……，正式书面语。补充背景、原因、依据或说话人的解释。","category":"说明・理由","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Nの／普通形 + ゆえ（に）","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：因为……；由于……，正式书面语。","解释为什么出现某结果。","在会话、说明文或正式通知中交代理由。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["正式表示原因；「がゆえに」更强调正因为该原因而产生结果。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","原因句型可能带客观说明、感谢、责怪或辩解等不同语气。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见于书面论述，日常会话用「ので／から」。","后项能否接命令、请求或意志表达，取决于具体形式。"]},"gx-n1-1alrjhq":{"overview":"「～がゆえに」的核心意义是：正因为……而导致某结果，书面语。补充背景、原因、依据或说话人的解释。","category":"说明・理由","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"普通形 + がゆえに","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。"],"usages":["用于表达：正因为……而导致某结果，书面语。","解释为什么出现某结果。","在会话、说明文或正式通知中交代理由。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["正式表示原因；「がゆえに」更强调正因为该原因而产生结果。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","原因句型可能带客观说明、感谢、责怪或辩解等不同语气。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见于书面论述，日常会话用「ので／から」。","后项能否接命令、请求或意志表达，取决于具体形式。"]},"gx-n1-1992fyh":{"overview":"「～手前」的核心意义是：考虑到自己的身份、承诺或面子，不能不……。基于常识、责任、既定事实或立场提出应有行动。","category":"建议・责任","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vた／V辞书／Nの + 手前","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。","前接动词使用辞书形，不接「ます」。","名词后先加「の」再连接。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：考虑到自己的身份、承诺或面子，不能不……。","给出建议、忠告或道义判断。","表示既然前项成立，就应承担相应后果。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["因顾及自己说过的话、身份或面子而不能不采取某态度。","语气通常比单纯建议强；对听话人使用时需注意礼貌。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项常是义务、不能退让。","客观义务、个人意见和社会责任应分别选择合适形式。"]},"gx-n1-1v9w3r1":{"overview":"「～始末だ」的核心意义是：经过负面发展后最终落到糟糕结果。突出原因、经过及最终结果，常附带说话人的评价。","category":"原因・结果","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书 + 始末だ","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：经过负面发展后最终落到糟糕结果。","说明由于某一原因而产生结果。","总结长时间、反复过程后的结局。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["总结一连串负面发展最终落到糟糕结局。","「ばかりに／あげく」多倾向负面结果，而「末に」可好可坏。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不能用于好结果。","原因与结果之间应具有自然、可理解的联系。"]},"gx-n1-1dx3ho":{"overview":"「～羽目になる」的核心意义是：因某原因陷入不情愿的处境：“结果不得不……”。表达没有必要、不能按意愿行事或不得不采取某行动。","category":"必要・无奈","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书 + 羽目になる","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：因某原因陷入不情愿的处境：“结果不得不……”。","说明现实、责任或社会常识造成的限制。","表达不做不能了结、只能接受或没有必要做。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示因事态发展陷入非本意、麻烦的处境。","要区分客观能力不足、社会立场限制与外部强迫。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常用于自己遭遇，含无奈。","否定成分多时应按整句理解，不能逐词相消。"]},"gx-n1-zfq70q":{"overview":"「～極まりない」的核心意义是：极其……；用于强烈负面或评价性形容。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"な形词干 + 極まりない","formationNotes":["な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。"],"usages":["用于表达：极其……；用于强烈负面或评价性形容。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["多接な形容词词干，表示评价达到极点；书面、语气强。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「極まりない」虽有「ない」，整体不是程度否定。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"gx-n1-1l7avjr":{"overview":"「～極まる」的核心意义是：极其……，书面表达。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"な形词干 + 極まる","formationNotes":["な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。"],"usages":["用于表达：极其……，书面表达。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["多接な形容词词干，表示评价达到极点；书面、语气强。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["「極まりない」虽有「ない」，整体不是程度否定。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"gx-n1-bg3gf9":{"overview":"「～の極み」的核心意义是：……到了极点，正式表达。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + の極み","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：……到了极点，正式表达。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["构成正式固定表达，表示某种感情或状态达到极点。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见「光栄の至り／感激の極み」等搭配，不能任意接所有名词。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"gx-n1-4mde8p":{"overview":"「～てやまない」的核心意义是：长期强烈地抱有某种愿望/敬意等。表达强烈感受、持续愿望或无法抑制的自然反应。","category":"情感・不可抑制","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vて + やまない","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。"],"usages":["用于表达：长期强烈地抱有某种愿望/敬意等。","说明情绪、感觉强烈到难以控制。","表达某事必然引起反应，或长期怀有愿望。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["多接「願う・愛する・尊敬する」等持续感情，表示始终强烈怀有。","部分形式只适合第一人称内在感受，描述第三者时需有观察依据。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不用于短暂感官感觉。","「たまらない／ならない／かなわない」侧重点不同。"]},"gx-n1-1heejwy":{"overview":"「～てならない」的核心意义是：某种情绪或感觉自然而强烈地产生：“……得不得了”。表达强烈感受、持续愿望或无法抑制的自然反应。","category":"情感・不可抑制","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vて／い形くて／な形で + ならない","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：某种情绪或感觉自然而强烈地产生：“……得不得了”。","说明情绪、感觉强烈到难以控制。","表达某事必然引起反应，或长期怀有愿望。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["「たまらない」强调主观强烈感受；「ならない」偏自然涌现；「かなわない」强调困扰、承受不了。","部分形式只适合第一人称内在感受，描述第三者时需有观察依据。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["描述第三者内心时需有可观察依据或引用。","「たまらない／ならない／かなわない」侧重点不同。"]},"gx-n1-1ty80o5":{"overview":"「～てたまらない」的核心意义是：主观感觉极其强烈：“……得受不了”。表达强烈感受、持续愿望或无法抑制的自然反应。","category":"情感・不可抑制","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vて／い形くて／な形で + たまらない","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：主观感觉极其强烈：“……得受不了”。","说明情绪、感觉强烈到难以控制。","表达某事必然引起反应，或长期怀有愿望。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["「たまらない」强调主观强烈感受；「ならない」偏自然涌现；「かなわない」强调困扰、承受不了。","部分形式只适合第一人称内在感受，描述第三者时需有观察依据。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["描述第三者内心时需有可观察依据或引用。","「たまらない／ならない／かなわない」侧重点不同。"]},"gx-n1-1m6h4oz":{"overview":"「～てかなわない」的核心意义是：某状况令人难以忍受，常带困扰。表达强烈感受、持续愿望或无法抑制的自然反应。","category":"情感・不可抑制","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vて／い形くて／な形で + かなわない","formationNotes":["动词使用て形，五段动词要注意促音便、イ音便和拨音便。","な形容词可能接「な／で／だ／である」，严格按接续栏所列形式使用。","い形容词根据公式保留「い」或变为「く／くて／かった」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：某状况令人难以忍受，常带困扰。","说明情绪、感觉强烈到难以控制。","表达某事必然引起反应，或长期怀有愿望。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["「たまらない」强调主观强烈感受；「ならない」偏自然涌现；「かなわない」强调困扰、承受不了。","部分形式只适合第一人称内在感受，描述第三者时需有观察依据。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["描述第三者内心时需有可观察依据或引用。","「たまらない／ならない／かなわない」侧重点不同。"]},"gx-n1-1e8b3ze":{"overview":"「～ないまでも」的核心意义是：即使达不到前项程度，至少也应该后项。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vない + までも","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：即使达不到前项程度，至少也应该后项。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["即使达不到前项较高标准，至少后项应成立。","先正确变出ない形，不能从辞书形机械删除词尾。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项通常提出较低、现实的最低要求。","要区分既成事实的逆接与假设条件的让步。"]},"gx-n1-1ar8wes":{"overview":"「～ないものでもない」的核心意义是：在特定条件下并非完全不可能。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vない + ものでもない","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：在特定条件下并非完全不可能。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["在特定条件下并非完全不可能，语气保留。","先正确变出ない形，不能从辞书形机械删除词尾。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常后接条件「〜なら」。","必要条件与充分条件不应混为一谈。"]},"gx-n1-t6byyc":{"overview":"「～であれ」的核心意义是：无论是……；即使是……，书面表达。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + であれ","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：无论是……；即使是……，书面表达。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["正式让步，表示无论属于何种身份／情况，后项不变。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常与疑问词或并列形式呼应。","要区分既成事实的逆接与假设条件的让步。"]},"gx-n1-g1n7kx":{"overview":"「～であろうと」的核心意义是：无论……也……；让步条件，正式。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N／普通形 + であろうと","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：无论……也……；让步条件，正式。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["正式让步，表示无论属于何种身份／情况，后项不变。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常与疑问词或并列形式呼应。","要区分既成事实的逆接与假设条件的让步。"]},"gx-n1-1rsi7bn":{"overview":"「～をおいて」的核心意义是：除了……没有更合适的人/事。限定范围、突出焦点，或用极端对象加强语气。","category":"限定・强调","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + をおいて（ほかに）","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：除了……没有更合适的人/事。","表示只有、不仅、甚至或正是某对象。","缩小适用范围，或把焦点放在特殊例子上。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["常与「ほかに〜ない」呼应，表示除前项外没有更合适者。","有些限定形式必须与否定呼应，有些则可用于肯定句。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["用于高度评价或唯一选择。","强调句型常带说话人评价，正式度也各不相同。"]},"gx-n1-3oagib":{"overview":"「～にかたくない」的核心意义是：很容易想象/理解：“不难……”。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"V辞书 + にかたくない","formationNotes":["前接动词使用辞书形，不接「ます」。"],"usages":["用于表达：很容易想象/理解：“不难……”。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["多与「想像する／理解する」搭配，表示不难做到。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不是物理硬度的“硬”。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"gx-n1-1kso2i7":{"overview":"「～にたえない」的核心意义是：不堪……／不值得……；也可表示强烈感谢等固定用法。以正式、强烈的方式评价程度、价值、资格或应有规范。","category":"极端・评价","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N／V辞书 + にたえない","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：不堪……／不值得……；也可表示强烈感谢等固定用法。","表示极其、值得、不值得或不符合身份。","对行为、感情和社会角色作郑重评价。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["可表示不堪看／听，也有「感謝に堪えない」等无法抑制的正式固定表达。","多为书面或固定表达，不能随意替换为日常程度副词。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与“值得”的肯定「に堪える」区分。","汉字写法与读音、肯定和否定形式需要分别记忆。"]},"gx-n1-6apf0":{"overview":"「～と相まって」的核心意义是：两个因素相互作用，使结果更加明显。表示两个动作并行、顺便进行，或两个变化相互伴随。","category":"同步・伴随","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + と相まって","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：两个因素相互作用，使结果更加明显。","说明同一主体同时做两件事。","表达随一个变化发生另一个变化，或利用机会顺便做事。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["两个因素相互作用，使后项结果更明显。","同时动作常要求主语一致；长期副业与一次性顺便行为要区分。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["通常列出两个同方向因素。","正式书面形式与日常「ながら」在语域上不同。"]},"gx-n1-hupg10":{"overview":"「～ないではおかない」的核心意义是：必然使某事发生；一定要做到。表达强烈感受、持续愿望或无法抑制的自然反应。","category":"情感・不可抑制","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vない + ではおかない","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：必然使某事发生；一定要做到。","说明情绪、感觉强烈到难以控制。","表达某事必然引起反应，或长期怀有愿望。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示必然引起某反应，或主语强烈意志一定要使之发生。","先正确变出ない形，不能从辞书形机械删除词尾。","部分形式只适合第一人称内在感受，描述第三者时需有观察依据。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不是单纯“不得不”，而是结果不会不发生。","「たまらない／ならない／かなわない」侧重点不同。"]},"gx-n1-7fqw9u":{"overview":"「～ではすまない」的核心意义是：不能只以……了事；后果更严重。表达没有必要、不能按意愿行事或不得不采取某行动。","category":"必要・无奈","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N／普通形 + ではすまない","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：不能只以……了事；后果更严重。","说明现实、责任或社会常识造成的限制。","表达不做不能了结、只能接受或没有必要做。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示不能只以某种简单处理了结，必然有更严重责任或后果。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","要区分客观能力不足、社会立场限制与外部强迫。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与“不做不能了结”的「ずにはすまない」区分。","否定成分多时应按整句理解，不能逐词相消。"]},"gx-n1-1l937mb":{"overview":"「～をよそに」的核心意义是：不顾周围人的担忧、期待、批评等。表示不顾周围反应或不把困难当回事而采取行动。","category":"无视・克服","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + をよそに","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：不顾周围人的担忧、期待、批评等。","描写顶住困难继续行动。","对照周围人的期待、批评或状态。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["都表示不顾周围；「尻目に」更有旁人状态与主体行动的鲜明对照。","「ものともせず」常带赞扬，「よそに／尻目に」多带批评或对照。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常带批评，偶尔也用于突出领先。","所接名词通常是困难、反应或旁人的状态。"]},"gx-n1-wmbnax":{"overview":"「～を尻目に」的核心意义是：无视/不顾旁人的状态，自己采取另一行动。表示不顾周围反应或不把困难当回事而采取行动。","category":"无视・克服","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + を尻目に","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：无视/不顾旁人的状态，自己采取另一行动。","描写顶住困难继续行动。","对照周围人的期待、批评或状态。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["都表示不顾周围；「尻目に」更有旁人状态与主体行动的鲜明对照。","「ものともせず」常带赞扬，「よそに／尻目に」多带批评或对照。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常带批评，偶尔也用于突出领先。","所接名词通常是困难、反应或旁人的状态。"]},"gx-n1-19tdtkq":{"overview":"「～ときたら」的核心意义是：提起某人/事时带强烈不满、惊讶等评价。突出特殊场合、极端对象或说话人对某对象的评价。","category":"立场・处境","register":{"label":"偏口语","note":"适合会话或带个人态度的表达；正式场合需选择更中性的形式。"},"formation":"N + ときたら","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：提起某人/事时带强烈不满、惊讶等评价。","说明在特殊环境下采取的行动。","把话题焦点推到特别值得评论的对象。","适合会话或带个人态度的表达；正式场合需选择更中性的形式。"],"cautions":["提出话题后表达强烈不满、惊讶或感叹，口语评价性强。","通常带明显语境和评价，不能作为中性主题标记替代「について」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不用于中性介绍。","前后文需明确特殊性或说话人的态度。"]},"gx-n1-dw3t5v":{"overview":"「～たところで」的核心意义是：即使做了前项，后项结果也不会改变。承认前项后，提出与预期不符、受限制或不受影响的后项。","category":"逆接・让步","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vた + ところで","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。"],"usages":["用于表达：即使做了前项，后项结果也不会改变。","表达“虽然／即使……但是……”。","比较同一事物的两面，或修正过度理解。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["让步假设：即使做了前项，后项结果也不会改善。","部分形式含责备、遗憾或意外，不适合用于中性正式说明。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["不同于「Vたところ、〜」表示做后发现结果。","要区分既成事实的逆接与假设条件的让步。"]},"gx-n1-1f1m2vy":{"overview":"「～たが最後」的核心意义是：一旦做了前项，就难以回到原状或必然出现后果。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"Vた + が最後","formationNotes":["前接动词使用た形；这里表示完成／相对过去，不一定是整句的绝对过去时。"],"usages":["用于表达：一旦做了前项，就难以回到原状或必然出现后果。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示一旦前项发生便难以挽回或必然持续后果。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项通常负面且不可逆。","必要条件与充分条件不应混为一谈。"]},"gx-n1-gykt41":{"overview":"「～ようが～まいが」的核心意义是：无论做不做某事，后项都不受影响。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"意向形 + が + V辞书 + まいが","formationNotes":["前接动词使用辞书形，不接「ます」。","前接意向形，如「行こう／食べよう／しよう／来よう」。"],"usages":["用于表达：无论做不做某事，后项都不受影响。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示无论做还是不做，后项不受影响；书面、强烈。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["同一动词通常分别使用意向形和「まい」形式。","必要条件与充分条件不应混为一谈。"]},"gx-n1-16kc1dd":{"overview":"「～ようと～まいと」的核心意义是：无论是否……。设定条件、假定场景或事情成立所需的前提。","category":"条件・假定","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"意向形 + と + V辞书 + まいと","formationNotes":["前接动词使用辞书形，不接「ます」。","前接意向形，如「行こう／食べよう／しよう／来よう」。"],"usages":["用于表达：无论是否……。","说明满足前项时后项如何成立。","基于话题提出建议、判断或不可逆后果。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示无论做还是不做，后项不受影响；书面、强烈。","「と／ば／たら／なら」对时间先后、意志句和既成事实的限制不同。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["同一动词通常分别使用意向形和「まい」形式。","必要条件与充分条件不应混为一谈。"]},"gx-n1-gzh265":{"overview":"「～いかんだ／～いかんで」的核心意义是：结果取决于……如何，正式。用正式书面语表达条件取决、无论如何或缺少前提便不能成立。","category":"正式条件・范围","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + いかんだ／いかんで","formationNotes":["斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：结果取决于……如何，正式。","在公告、议论和正式说明中设定条件。","表达结果取决于内容，或不受条件影响。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示结果取决于前项内容、方式如何，正式书面。","「いかん」是名词性书面表达，前接多用「N（の）」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见「N（の）いかんで／いかんによって」。","肯定的“取决于”与“无论如何”形式不同。"]},"gx-n1-1hy926q":{"overview":"「～いかんにかかわらず」的核心意义是：无论……如何都……，正式。用正式书面语表达条件取决、无论如何或缺少前提便不能成立。","category":"正式条件・范围","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + のいかんにかかわらず","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：无论……如何都……，正式。","在公告、议论和正式说明中设定条件。","表达结果取决于内容，或不受条件影响。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示不论前项内容如何，后项一律成立。","「いかん」是名词性书面表达，前接多用「N（の）」。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["与取决于条件的「いかんで」意义相反。","肯定的“取决于”与“无论如何”形式不同。"]},"gx-n1-4din17":{"overview":"「～を経て」的核心意义是：经过某过程、阶段之后。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + を経て","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：经过某过程、阶段之后。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示经过阶段、地点、人物或程序之后到达结果。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["强调过程，不只是时间先后。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"gx-n1-ax66nu":{"overview":"「～に先立って」的核心意义是：在重要事件之前预先做某事。标明动作发生的时间点、期间、阶段、先后或截止范围。","category":"时间・阶段","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N／V辞书 + に先立って","formationNotes":["前接动词使用辞书形，不接「ます」。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：在重要事件之前预先做某事。","说明何时开始、持续、结束或紧接发生。","突出某个关键阶段、期限或反复出现的时点。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["表示在重要事件前预先做准备，时间先后明确。","辞书形、ている形和た形会改变动作相对时间。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["比普通「前に」正式。","瞬间发生、持续期间和完成后状态需要选用不同形式。"]},"gx-n1-1iqfo3z":{"overview":"「～に引き換え」的核心意义是：与前项形成鲜明对照：“与……相反”。设定比较基准，或说明数量、性质和程度。","category":"比较・程度","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + に引き換え","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：与前项形成鲜明对照：“与……相反”。","比较两个对象或范围内的高低。","用极端例子、数量或结果说明程度。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["「に比べて」中性比较；「に引き換え」强调鲜明反差，常带评价。","比较对象、基准和评价对象的助词不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["比较对象需具有可比性。","否定比较与最高级结构有固定语序。"]},"gx-n1-1sq8ghj":{"overview":"「～にもまして」的核心意义是：比……更……，强调程度进一步提高。设定比较基准，或说明数量、性质和程度。","category":"比较・程度","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + にもまして","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：比……更……，强调程度进一步提高。","比较两个对象或范围内的高低。","用极端例子、数量或结果说明程度。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["以某基准为参照，表示现在／另一对象程度更高。","比较对象、基准和评价对象的助词不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常见「以前にもまして」。","否定比较与最高级结构有固定语序。"]},"gx-n1-gdbnso":{"overview":"「～にひきかえ」的核心意义是：与……相比完全不同。设定比较基准，或说明数量、性质和程度。","category":"比较・程度","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N／普通形 + にひきかえ","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：与……相比完全不同。","比较两个对象或范围内的高低。","用极端例子、数量或结果说明程度。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["「に比べて」中性比较；「に引き換え」强调鲜明反差，常带评价。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","比较对象、基准和评价对象的助词不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["比较对象需具有可比性。","否定比较与最高级结构有固定语序。"]},"gx-n1-1srsfxj":{"overview":"「～にもほどがある」的核心意义是：表示程度过分：“也该有个限度”。设定比较基准，或说明数量、性质和程度。","category":"比较・程度","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N／普通形 + にもほどがある","formationNotes":["普通形包括辞书形、た形、ない形、なかった形；名词和な形容词的现在肯定接续需按公式确认。","斜线表示根据词类或意义择一使用，不是把所有形式同时叠加。"],"usages":["用于表达：表示程度过分：“也该有个限度”。","比较两个对象或范围内的高低。","用极端例子、数量或结果说明程度。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["批评程度超过常识界限，“也该有个限度”。","名词、な形容词现在肯定是否带「だ／な／である」，必须看本条公式。","比较对象、基准和评价对象的助词不能互换。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["常接负面行为或状态，语气强。","否定比较与最高级结构有固定语序。"]},"gx-n1-t2rknr":{"overview":"「～と言わず～と言わず」的核心意义是：不分A还是B，全部都……。并列理由、动作或例子，并说明列举是否完整。","category":"并列・列举","register":{"label":"偏书面／正式","note":"多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"},"formation":"N + と言わず + N + と言わず","formationNotes":["先完成前接词的活用，再连接接续栏所列的固定形式。"],"usages":["用于表达：不分A还是B，全部都……。","列出多个同类事实、理由或动作。","用代表性项目暗示还有其他内容。","多见于文章、新闻、商务说明或郑重发言，日常会话中可能显得生硬。"],"cautions":["列出两个代表部位／时间，表示其范围内无一例外。","「と」偏完整列举，「や／など／とか」多为不完全列举。","不要只按中文译词替换近义句型，还要确认接续、语体和说话人态度。"],"specialCases":["后项通常描述遍及整体的状态。","列举句型通常要求前后项目在语法形式和评价方向上协调。"]}};
  const items = Object.values(DATA.grammar).flat();
  for (const item of items) {
    const detail = DETAILS[item.id];
    if (!detail) throw new Error(`Missing grammar detail: ${item.id} ${item.title}`);
    item.detail = detail;
  }
  if (Object.keys(DETAILS).length !== items.length) {
    throw new Error(`Grammar detail count mismatch: ${Object.keys(DETAILS).length}/${items.length}`);
  }
  for (const item of items) {
    const d = item.detail;
    if (!d?.overview || !d?.formation || !d?.category || !d?.register?.label || d.usages.length < 3 || d.cautions.length < 2 || d.specialCases.length < 1) {
      throw new Error(`Incomplete grammar detail: ${item.id} ${item.title}`);
    }
  }
  window.JLPT_GRAMMAR_DETAIL_COUNT = items.length;
  if (typeof document === 'undefined') console.log(`Grammar details: ${items.length}/${items.length} complete`);
})();
